105→static int json_escape(const char *in, char *out, size_t cap)
106→{
107→  size_t o = 0;
108→  size_t i;
109→
110→  if (!in || !out || cap < 2)
111→    {
112→      return -1;
113→    }
114→  for (i = 0; in[i] && o + 8 < cap; i++)
115→    {
116→      unsigned char ch = (unsigned char)in[i];
117→      if (ch == '"' || ch == '\\')
118→        {
119→          out[o++] = '\\';
120→          out[o++] = (char)ch;
121→        }
122→      else if (ch == '\n')
123→        {
124→          out[o++] = '\\';
125→          out[o++] = 'n';
126→        }
127→      else if (ch < 0x20)
128→        {
129→          /* skip control chars */
130→        }
131→      else
132→        {
133→          out[o++] = (char)ch;
134→        }
135→    }
136→  out[o] = '\0';
137→  return (int)o;
138→}
