187→int dm_chat_hist_json(char *out, int cap)
188→{
189→  char esc[HIST_LINE * 2];
190→  int o = 0;
191→  int i;
192→
193→  if (!out || cap < 2)
194→    {
195→      return -1;
196→    }
197→  out[0] = '\0';
198→  for (i = 0; i < s_hist_n; i++)
199→    {
200→      int n;
201→
202→      if (s_hist[i].user[0])
203→        {
204→          json_escape(s_hist[i].user, esc, sizeof(esc));
205→          n = snprintf(out + o, (size_t)(cap - o),
206→                       "{\"role\":\"user\",\"content\":\"%s\"},", esc);
207→          if (n < 0 || n >= cap - o)
208→            {
209→              out[o] = '\0';
210→              return -1;
211→            }
212→          o += n;
213→        }
214→      if (s_hist[i].bot[0])
215→        {
216→          json_escape(s_hist[i].bot, esc, sizeof(esc));
217→          n = snprintf(out + o, (size_t)(cap - o),
218→                       "{\"role\":\"assistant\",\"content\":\"%s\"},", esc);
219→          if (n < 0 || n >= cap - o)
220→            {
221→              out[o] = '\0';
222→              return -1;
223→            }
224→          o += n;
225→        }
226→    }
227→  return o;
