 95→int dm_voice_rec_start(int max_seconds)
 96→{
 97→  pthread_t th;
 98→  pthread_attr_t attr;
 99→
100→  pthread_mutex_lock(&s_rec_lock);
101→  if (s_rec_active)
102→    {
103→      pthread_mutex_unlock(&s_rec_lock);
104→      return 0;
105→    }
106→
107→  unlink(WAV_REC);
108→  s_rec = nxrecorder_create();
109→  if (!s_rec)
110→    {
111→      pthread_mutex_unlock(&s_rec_lock);
112→      s_st = DM_VOICE_ERR;
113→      return -1;
114→    }
115→  (void)nxrecorder_setdevice(s_rec, "/dev/audio/pcm0c");
116→  if (nxrecorder_recordinternal(s_rec, WAV_REC, AUDIO_FMT_PCM,
117→                                REC_CH, REC_BITS, REC_RATE, 1) != OK)
118→    {
119→      nxrecorder_release(s_rec);
120→      s_rec = NULL;
121→      pthread_mutex_unlock(&s_rec_lock);
122→      s_st = DM_VOICE_ERR;
123→      return -1;
124→    }
125→  s_rec_active = 1;
126→  s_st = DM_VOICE_REC;
127→  pthread_mutex_unlock(&s_rec_lock);
128→
129→  pthread_attr_init(&attr);
130→  pthread_attr_setstacksize(&attr, 4096);
131→  if (pthread_create(&th, &attr, rec_auto_stop,
132→                     (void *)(intptr_t)(max_seconds > 0 ? max_seconds
133→                                                        : REC_MAX_SEC)) == 0)
134→    {
135→      pthread_detach(th);
136→    }
137→  pthread_attr_destroy(&attr);
138→  return 0;
139→}
