187→/* nxplayer treats .wav as raw PCM and never reads the WAV header
188→ * (its PCM ops->pre_parse is NULL), so the fmt chunk is parsed here and
189→ * the payload is fed via nxplayer_playraw() with explicit parameters. */
190→static int play_wav(const char *path)
191→{
192→  const char *src = (path && path[0]) ? path : WAV_TTS;
193→  struct nxplayer_s *p;
194→  FILE *f;
195→  FILE *o;
196→  uint8_t hdr[44];
197→  char buf[1024];
198→  size_t n;
199→  uint32_t rate;
200→  uint16_t ch;
201→  uint16_t bits;
202→
203→  p = player_get();
204→  if (!p)
205→    {
206→      return -1;
207→    }
208→
209→  f = fopen(src, "rb");
210→  if (!f)
211→    {
212→      return -1;
213→    }
214→  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
215→    {
216→      fclose(f);
217→      return -1;
218→    }
219→  ch = (uint16_t)(hdr[22] | (hdr[23] << 8));
220→  rate = (uint32_t)(hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) |
221→                    ((uint32_t)hdr[27] << 24));
222→  bits = (uint16_t)(hdr[34] | (hdr[35] << 8));
223→  if (rate < 8000 || rate > 48000)
224→    {
225→      rate = 24000;
226→    }
227→  if (ch < 1 || ch > 2)
228→    {
229→      ch = 1;
230→    }
231→  if (bits != 8 && bits != 16)
232→    {
233→      bits = 16;
234→    }
235→
236→  o = fopen(PCM_RAW, "wb");
237→  if (!o)
238→    {
239→      fclose(f);
240→      return -1;
241→    }
242→  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
243→    {
244→      fwrite(buf, 1, n, o);
245→    }
246→  fclose(o);
247→  fclose(f);
248→
249→  (void)nxplayer_stop(p); /* ignore error when idle */
250→  return (nxplayer_playraw(p, PCM_RAW, AUDIO_FMT_PCM, 0, (uint8_t)ch,
251→                           (uint8_t)bits, rate, 1) == OK) ? 0 : -1;
252→}
