335→static const char b64tab[] =
336→    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
337→
338→static int b64_encode(const unsigned char *in, size_t inlen, char *out, size_t outcap)
339→{
340→  size_t i = 0, o = 0;
341→  while (i < inlen && o + 4 < outcap)
342→    {
343→      unsigned int v = in[i++] << 16;
344→      if (i < inlen) v |= in[i++] << 8;
345→      if (i < inlen) v |= in[i++];
346→      out[o++] = b64tab[(v >> 18) & 63];
347→      out[o++] = b64tab[(v >> 12) & 63];
348→      out[o++] = b64tab[(v >> 6) & 63];
349→      out[o++] = b64tab[v & 63];
350→    }
351→  out[o] = '\0';
352→  return (int)o;
353→}
354→
355→static int b64_decode(const char *in, unsigned char *out, size_t outcap)
356→{
357→  int val = 0, valb = -8;
358→  size_t o = 0;
359→  for (; *in && *in != '=' && o < outcap; in++)
360→    {
361→      const char *p = strchr(b64tab, *in);
362→      if (!p) continue;
363→      val = (val << 6) + (int)(p - b64tab);
364→      valb += 6;
365→      if (valb >= 0)
366→        {
367→          out[o++] = (unsigned char)((val >> valb) & 255);
368→          valb -= 8;
369→        }
370→    }
371→  return (int)o;
372→}
