374→static int http_post_json(const char *path, const char *json_body,
375→                          const char *out_path)
376→{
377→  char cmd[1400];
378→  FILE *f = fopen(JSON_REQ, "w");
379→
380→  if (!f)
381→    {
382→      return -1;
383→    }
384→  fwrite(json_body, 1, strlen(json_body), f);
385→  fclose(f);
386→  unlink(out_path);
387→  snprintf(cmd, sizeof(cmd),
388→           "curl -skS --cacert /resource/etc/ssl/curl/ca-certificates.crt "
389→           "-m 25 -X POST %s%s "
390→           "-H 'Authorization: Bearer %s' "
391→           "-H 'Content-Type: application/json' "
392→           "-d @%s -o %s",
393→           VOICE_BASE, path, VOICE_KEY, JSON_REQ, out_path);
394→  return run_curl_script(cmd);
