619→static int tts_synth(const char *text, const char *wav_path)
620→{
621→  char esc[400];
622→  char *body;
623→  char *rsp;
624→  FILE *f;
625→  long sz;
626→  int n;
627→  char *p;
628→  unsigned char *raw;
629→  int rawlen;
630→
631→  json_escape(text, esc, sizeof(esc));
632→  body = malloc(700);
633→  if (!body)
634→    {
635→      return -1;
636→    }
637→  /* chat/completions TTS: assistant content is spoken */
638→  n = snprintf(body, 700,
639→               "{\"model\":\"%s\",\"messages\":["
640→               "{\"role\":\"user\",\"content\":\"请朗读\"},"
641→               "{\"role\":\"assistant\",\"content\":\"%s\"}]}",
642→               TTS_MODEL, esc);
643→  if (n <= 0 || n >= 700)
644→    {
645→      free(body);
646→      return -1;
647→    }
648→  if (http_post_json("/chat/completions", body, TXT_CHAT) != 0)
649→    {
650→      free(body);
651→      return -1;
652→    }
653→  free(body);
654→
655→  f = fopen(TXT_CHAT, "rb");
656→  if (!f)
657→    {
658→      return -1;
659→    }
660→  fseek(f, 0, SEEK_END);
661→  sz = ftell(f);
662→  fseek(f, 0, SEEK_SET);
663→  if (sz <= 0 || sz > 4 * 1024 * 1024)
664→    {
665→      fclose(f);
666→      return -1;
667→    }
668→  rsp = malloc((size_t)sz + 1);
669→  if (!rsp)
670→    {
671→      fclose(f);
672→      return -1;
673→    }
674→  if (fread(rsp, 1, (size_t)sz, f) != (size_t)sz)
675→    {
676→      free(rsp);
677→      fclose(f);
678→      return -1;
679→    }
680→  rsp[sz] = '\0';
681→  fclose(f);
682→
683→  p = strstr(rsp, "\"data\"");
684→  if (!p)
685→    {
686→      free(rsp);
687→      return -1;
688→    }
689→  p = strchr(p + 6, '"');
690→  if (!p)
691→    {
692→      free(rsp);
693→      return -1;
694→    }
695→  {
696→    char *q = strchr(p + 1, '"');
697→    if (!q)
698→      {
699→        free(rsp);
700→        return -1;
701→      }
702→    *q = '\0';
703→  }
704→  raw = malloc((size_t)sz);
705→  if (!raw)
706→    {
707→      free(rsp);
708→      return -1;
709→    }
710→  rawlen = b64_decode(p + 1, raw, (size_t)sz);
711→  free(rsp);
712→  if (rawlen <= 0)
713→    {
714→      free(raw);
715→      return -1;
716→    }
717→  f = fopen(wav_path, "wb");
718→  if (!f)
719→    {
720→      free(raw);
721→      return -1;
722→    }
723→  fwrite(raw, 1, (size_t)rawlen, f);
724→  fclose(f);
725→  free(raw);
726→  return 0;
727→}
