 277→/* Verify the current association is really the expected SSID.
 278→ * Returns 1 = match, 0 = mismatch / not associated, -1 = cannot read. */
 279→static int wifi_verify_assoc(const char *expected)
 280→{
 281→  char assoc[33];
 282→
 283→  if (!expected || !expected[0])
 284→    {
 285→      return -1;
 286→    }
 287→  if (!wifi_is_associated(assoc, sizeof(assoc)))
 288→    {
 289→      return 0;
 290→    }
 291→  if (!assoc[0])
 292→    {
 293→      return -1;
 294→    }
 295→  return strcmp(assoc, expected) == 0 ? 1 : 0;
 296→}
