 386→void dm_wifi_poll(void)
 387→{
 388→  struct in_addr addr;
 389→
 390→  if (!s_wifi_enabled || !dm_wifi_connected())
 391→    {
 392→      return;
 393→    }
 394→
 395→  s_poll_ticks++;
 396→  if ((s_poll_ticks & 7) != 0)
 397→    {
 398→      return;
 399→    }
 400→
 401→  if (wifi_get_valid_ip(&addr) != 0)
 402→    {
 403→      wifi_mark_link_lost();
 404→      return;
 405→    }
 406→
 407→  if ((s_poll_ticks & 31) == 0 && wifi_is_link_up() == 0)
 408→    {
 409→      wifi_mark_link_lost();
 410→    }
 411→}
