 438→static void wifi_unquote(char *s)
 439→{
 440→  size_t n;
 441→
 442→  if (!s || s[0] != '"')
 443→    {
 444→      return;
 445→    }
 446→  n = strlen(s);
 447→  if (n >= 2 && s[n - 1] == '"')
 448→    {
 449→      memmove(s, s + 1, n - 2);
 450→      s[n - 2] = 0;
 451→    }
 452→}
