 847→/* Official connect — ifup → mode 2 → psk(3 2) → essid(1) → wait → renew */
 848→static void *conn_thread(void *arg)
 849→{
 850→  char cmd[192];
 851→  char qssid[80];
 852→  char qpass[160];
 853→  int i;
 854→  int attempt;
 855→  int got_ip = 0;
 856→  int is_auto = s_conn_is_auto;
 857→  struct in_addr addr;
 858→  char try_ssid[33];
 859→  char try_pass[64];
 860→  bool try_open;
 861→
 862→  (void)arg;
 863→
 864→  if (!s_wifi_enabled)
 865→    {
 866→      s_conn_busy = 0;
 867→      s_conn_fail = 1;
 868→      return NULL;
 869→    }
 870→
 871→  strncpy(try_ssid, s_pending_ssid, sizeof(try_ssid) - 1);
 872→  try_ssid[sizeof(try_ssid) - 1] = 0;
 873→  strncpy(try_pass, s_pending_pass, sizeof(try_pass) - 1);
 874→  try_pass[sizeof(try_pass) - 1] = 0;
 875→  try_open = s_pending_open;
 876→
 877→  if (try_ssid[0] == 0 || if_nametoindex(DM_WIFI_IF) == 0)
 878→    {
 879→      syslog(LOG_ERR, "[deskmate-wifi] connect abort: no ssid/wlan0\n");
 880→      s_conn_busy = 0;
 881→      s_conn_fail = 1;
 882→      return NULL;
 883→    }
 884→
 885→  if (ensure_driver() < 0)
 886→    {
 887→      s_conn_busy = 0;
 888→      s_conn_fail = 1;
 889→      return NULL;
 890→    }
 891→
 892→  if (is_auto && s_manual_override)
 893→    {
 894→      s_conn_busy = 0;
 895→      return NULL;
 896→    }
 897→
 898→  /* NOTE: credentials are persisted only after a verified connection (below).
 899→
 900→   * 9) The 9.5 wifi_manager retries the whole sequence every 5s until it is
 901→   * associated. Port that behaviour here: up to DM_WIFI_CONN_ROUNDS tries. */
 902→  for (attempt = 0; attempt < DM_WIFI_CONN_ROUNDS; attempt++)
 903→    {
 904→      if (attempt > 0)
 905→        {
 906→          syslog(LOG_INFO, "[deskmate-wifi] retry %d/%d in %ds\n",
 907→                 attempt + 1, DM_WIFI_CONN_ROUNDS, DM_WIFI_CONN_RETRY_SEC);
 908→          sleep(DM_WIFI_CONN_RETRY_SEC);
 909→        }
 910→
 911→      got_ip = 0;
 912→
 913→      /* 1) ifup + STA mode */
 914→      cli_sta_up();
 915→
 916→  /* 1.5) Drop the previous association so switching between networks
 917→   *      (WPA2 <-> open) always starts from a clean driver state. */
 918→  syslog(LOG_INFO, "[deskmate-wifi] wapi disconnect %s\n", DM_WIFI_IF);
 919→  (void)system("wapi disconnect wlan0");
 920→  usleep(100 * 1000);
 921→
 922→  /* 2) psk — WPA_ALG_CCMP = 3, WPA2 = 2 */
 923→  if (!try_open && try_pass[0])
 924→    {
 925→      if (shell_quote(try_pass, qpass, sizeof(qpass)) < 0)
 926→        {
 927→          s_conn_busy = 0;
 928→          s_conn_fail = 1;
 929→          return NULL;
 930→        }
 931→      snprintf(cmd, sizeof(cmd), "wapi psk %s %s 3 2", DM_WIFI_IF, qpass);
 932→      syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
 933→      if (system(cmd) != 0)
 934→        {
 935→          syslog(LOG_ERR, "[deskmate-wifi] psk failed (passphrase must be 8-63 chars)\n");
 936→          s_conn_busy = 0;
 937→          s_conn_fail = 1;
 938→          return NULL;
 939→        }
 940→    }
 941→  else
 942→    {
 943→      /* Open AP: clear any leftover WPA key (alg 0 = WPA_ALG_NONE), otherwise
 944→       * the driver keeps the previous CCMP key and cannot join open networks. */
 945→      syslog(LOG_INFO, "[deskmate-wifi] open AP: clear psk\n");
 946→      (void)system("wapi psk wlan0 00000000 0");
 947→    }
 948→
 949→  /* 3) essid — flag 1 = connect */
 950→  if (shell_quote(try_ssid, qssid, sizeof(qssid)) < 0)
 951→    {
 952→      s_conn_busy = 0;
 953→      s_conn_fail = 1;
 954→      return NULL;
 955→    }
 956→  snprintf(cmd, sizeof(cmd), "wapi essid %s %s 1", DM_WIFI_IF, qssid);
 957→  syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
 958→  if (system(cmd) != 0)
 959→    {
 960→      syslog(LOG_ERR, "[deskmate-wifi] essid join failed\n");
 961→      s_conn_busy = 0;
 962→      s_conn_fail = 1;
 963→      return NULL;
 964→    }
 965→
 966→  /* 4) Wait for WPA2 4-way handshake / association (interruptible if auto) */
 967→  for (i = 0; i < 25; i++)
 968→    {
 969→      if (!s_wifi_enabled)
 970→        {
 971→          s_conn_busy = 0;
 972→          return NULL;
 973→        }
 974→      if (is_auto && s_manual_override)
 975→        {
 976→          s_conn_busy = 0;
 977→          return NULL;
 978→        }
 979→      usleep(100 * 1000);
 980→    }
 981→
 982→  /* 5) DHCP renew — single DHCP call per attempt */
 983→  for (i = 0; i < 4; i++)
 984→    {
 985→      if (is_auto && s_manual_override)
 986→        {
 987→          s_conn_busy = 0;
 988→          return NULL;
 989→        }
 990→
 991→      (void)system("renew wlan0");
 992→      if (wifi_get_valid_ip(&addr) == 0)
 993→        {
 994→          got_ip = 1;
 995→          break;
 996→        }
 997→
 998→      if (is_auto && s_manual_override)
 999→        {
1000→          s_conn_busy = 0;
1001→          return NULL;
1002→        }
1003→
1004→      if (netlib_obtain_ipv4addr(DM_WIFI_IF) >= 0 &&
1005→          wifi_get_valid_ip(&addr) == 0)
1006→        {
1007→          got_ip = 1;
1008→          break;
1009→        }
1010→
1011→      syslog(LOG_WARNING, "[deskmate-wifi] renew retry %d\n", i + 1);
1012→      sleep(1);
1013→    }
1014→
1015→  /* Verify we are really associated with the intended SSID (an old IPv4
1016→   * address may still be configured while switching networks). */
1017→  if (got_ip)
1018→    {
1019→      int assoc = wifi_verify_assoc(try_ssid);
1020→      if (assoc == 0)
1021→        {
1022→          syslog(LOG_ERR,
1023→                 "[deskmate-wifi] associated to another SSID, treat as failure\n");
1024→          got_ip = 0;
1025→        }
1026→      else if (assoc < 0)
1027→        {
1028→          syslog(LOG_WARNING,
1029→                 "[deskmate-wifi] cannot verify ESSID, assume connected\n");
1030→        }
1031→    }
1032→
1033→      /* Ported check: "wapi show" reports AP all-zero when not associated. */
1034→      if (got_ip && wifi_is_link_up() == 0)
1035→        {
1036→          syslog(LOG_WARNING, "[deskmate-wifi] wapi show: not associated yet\n");
1037→          got_ip = 0;
1038→        }
1039→
1040→      if (got_ip)
1041→        {
1042→          break;
1043→        }
1044→
1045→      syslog(LOG_WARNING, "[deskmate-wifi] attempt %d/%d failed\n",
1046→             attempt + 1, DM_WIFI_CONN_ROUNDS);
1047→    }
1048→
1049→  if (got_ip && !s_wifi_enabled)
1050→    {
1051→      got_ip = 0;
1052→    }
1053→
1054→  /* Fix: Only set s_cur_ssid when got_ip is true! */
1055→  pthread_mutex_lock(&s_lock);
1056→  if (got_ip)
1057→    {
1058→      strncpy(s_cur_ssid, try_ssid, sizeof(s_cur_ssid) - 1);
1059→      s_cur_ssid[sizeof(s_cur_ssid) - 1] = 0;
1060→      strncpy(s_cur_ip, inet_ntoa(addr), sizeof(s_cur_ip) - 1);
1061→      s_cur_ip[sizeof(s_cur_ip) - 1] = 0;
1062→    }
1063→  else
1064→    {
1065→      s_cur_ssid[0] = 0;
1066→      s_cur_ip[0] = 0;
1067→    }
1068→  pthread_mutex_unlock(&s_lock);
1069→
1070→  if (!got_ip)
1071→    {
1072→      syslog(LOG_ERR,
1073→             "[deskmate-wifi] connect fail after %d attempts "
1074→             "(ssid=%s wlan0=%d)\n",
1075→             DM_WIFI_CONN_ROUNDS, try_ssid,
1076→             (int)if_nametoindex(DM_WIFI_IF));
1077→      s_conn_busy = 0;
1078→      s_conn_fail = 1;
1079→      return NULL;
1080→    }
1081→
1082→  syslog(LOG_INFO, "[deskmate-wifi] connected ssid=%s ip=%s\n",
1083→         s_cur_ssid, s_cur_ip);
1084→
1085→  if (system("wapi save_config wlan0") != 0)
1086→    {
1087→      syslog(LOG_WARNING, "[deskmate-wifi] wapi save_config failed\n");
1088→    }
1089→  wifi_cred_save(try_ssid, try_pass);
1090→
1091→  s_conn_busy = 0;
1092→  s_conn_ok = 1;
1093→  return NULL;
1094→}
1095→
1096→static int wifi_start_connect_internal(const char *ssid, const char *pass,
1097→                                       int is_auto)
1098→{
1099→  pthread_t th;
1100→  pthread_attr_t attr;
1101→  int ret;
1102→  int i;
1103→
1104→  if (!ssid || !ssid[0])
1105→    {
1106→      return -1;
1107→    }
1108→
1109→  if (!is_auto)
1110→    {
1111→      s_manual_override = 1;
1112→      for (i = 0; i < 50 && (s_scan_busy || (s_conn_busy && s_conn_is_auto)); i++)
1113→        {
1114→          usleep(100 * 1000);
1115→        }
1116→    }
1117→
1118→  if (s_scan_busy || s_conn_busy)
1119→    {
1120→      return -1;
1121→    }
1122→
1123→  strncpy(s_pending_ssid, ssid, sizeof(s_pending_ssid) - 1);
1124→  s_pending_ssid[sizeof(s_pending_ssid) - 1] = 0;
1125→  if (pass)
1126→    {
1127→      strncpy(s_pending_pass, pass, sizeof(s_pending_pass) - 1);
1128→      s_pending_pass[sizeof(s_pending_pass) - 1] = 0;
1129→    }
1130→  else
1131→    {
1132→      s_pending_pass[0] = 0;
1133→    }
1134→  s_pending_open = (pass == NULL || s_pending_pass[0] == 0);
1135→
1136→  s_conn_ok = 0;
1137→  s_conn_fail = 0;
1138→  s_conn_is_auto = is_auto;
1139→  s_conn_busy = 1;
1140→
1141→  pthread_attr_init(&attr);
1142→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1143→  ret = pthread_create(&th, &attr, conn_thread, NULL);
1144→  pthread_attr_destroy(&attr);
1145→  if (ret != 0)
1146→    {
1147→      s_conn_busy = 0;
1148→      return -1;
1149→    }
1150→  pthread_detach(th);
1151→  return 0;
1152→}
1153→
1154→int dm_wifi_connect(const char *ssid, const char *pass)
1155→{
1156→  return wifi_start_connect_internal(ssid, pass, 0);
1157→}
