1159→/* Boot auto-connect: checks if already connected, otherwise tries saved
1160→ * credentials once or twice and immediately yields if user opens manual scan. */
1161→static void *auto_thread(void *arg)
1162→{
1163→  char ssid[33];
1164→  char pass[64];
1165→  struct in_addr addr;
1166→  int round;
1167→  int i;
1168→
1169→  (void)arg;
1170→
1171→  ssid[0] = 0;
1172→  pass[0] = 0;
1173→  if (wifi_cred_load(ssid, sizeof(ssid), pass, sizeof(pass)) != 0 ||
1174→      !ssid[0])
1175→    {
1176→      if (DM_WIFI_AUTO_SSID[0] == 0)
1177→        {
1178→          syslog(LOG_INFO,
1179→                 "[deskmate-wifi] no saved credentials; skip auto-connect\n");
1180→          return NULL;
1181→        }
1182→      snprintf(ssid, sizeof(ssid), "%s", DM_WIFI_AUTO_SSID);
1183→      snprintf(pass, sizeof(pass), "%s", DM_WIFI_AUTO_PSK);
1184→    }
1185→
1186→  syslog(LOG_INFO,
1187→         "[deskmate-wifi] auto-connect ssid=%s — wait wlan0 first\n", ssid);
1188→
1189→  for (round = 0; round < 2 && !s_manual_override; round++)
1190→    {
1191→      if (ensure_driver_wait(300) < 0)
1192→        {
1193→          if (s_manual_override)
1194→            {
1195→              return NULL;
1196→            }
1197→          sleep(2);
1198→          continue;
1199→        }
1200→
1201→      /* If board or wifi_manager already obtained an IP, adopt it directly */
1202→      if (wifi_get_valid_ip(&addr) == 0)
1203→        {
1204→          char assoc_ssid[33];
1205→          wifi_is_associated(assoc_ssid, sizeof(assoc_ssid));
1206→          pthread_mutex_lock(&s_lock);
1207→          snprintf(s_cur_ssid, sizeof(s_cur_ssid), "%s",
1208→                   assoc_ssid[0] ? assoc_ssid : ssid);
1209→          snprintf(s_cur_ip, sizeof(s_cur_ip), "%s", inet_ntoa(addr));
1210→          pthread_mutex_unlock(&s_lock);
1211→          syslog(LOG_INFO, "[deskmate-wifi] already connected ssid=%s ip=%s\n",
1212→                 s_cur_ssid, s_cur_ip);
1213→          return NULL;
1214→        }
1215→
1216→      if (dm_wifi_connected() || s_manual_override)
1217→        {
1218→          return NULL;
1219→        }
1220→
1221→      dm_wifi_clear_conn_flags();
1222→      if (wifi_start_connect_internal(ssid, pass, 1) != 0)
1223→        {
1224→          sleep(2);
1225→          continue;
1226→        }
1227→
1228→      /* Wait for conn_thread to finish or manual override */
1229→      for (i = 0; i < 180 && s_conn_busy && !s_manual_override; i++)
1230→        {
1231→          usleep(100 * 1000);
1232→        }
1233→
1234→      if (dm_wifi_connected())
1235→        {
1236→          syslog(LOG_INFO, "[deskmate-wifi] auto connected ssid=%s ip=%s\n",
1237→                 dm_wifi_cur_ssid(), dm_wifi_cur_ip());
1238→          dm_wifi_clear_conn_flags();
1239→          return NULL;
1240→        }
1241→
1242→      dm_wifi_clear_conn_flags();
1243→      if (s_manual_override)
1244→        {
1245→          return NULL;
1246→        }
1247→      sleep(2);
1248→    }
1249→
1250→  syslog(LOG_INFO,
1251→         "[deskmate-wifi] auto-connect finished; manual UI ready\n");
1252→  return NULL;
1253→}
1254→
1255→/* Boot auto-connect: reads saved credentials (/data/deskmate_wifi.txt or
1256→ * /data/wifi.cfg) and reconnects, yielding to the manual UI if the user
1257→ * starts a scan/connect first.  Called once from deskmate_main.c. */
1258→void dm_wifi_auto_start(void)
1259→{
1260→  pthread_t th;
1261→  pthread_attr_t attr;
1262→
1263→  if (s_auto_started)
1264→    {
1265→      return;
1266→    }
1267→  s_auto_started = 1;
1268→
1269→  pthread_attr_init(&attr);
1270→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1271→  if (pthread_create(&th, &attr, auto_thread, NULL) == 0)
1272→    {
1273→      pthread_detach(th);
1274→    }
1275→  pthread_attr_destroy(&attr);
1276→}
