301→void dm_chat_tick(void)
302→{
303→  /* apply worker results on LVGL thread */
304→  if (s_out_ready)
305→    {
306→      s_out_ready = 0;
307→      if (s_out_ans[0])
308→        {
309→          set_ans(s_out_ans);
310→        }
311→      if (s_out_sub[0])
312→        {
