 63→ * Pre-processor Definitions
 64→ ****************************************************************************/
 65→
 66→#define CURL4NX_STATE_STATUSLINE   0
 67→#define CURL4NX_STATE_STATUSCODE   1
 68→#define CURL4NX_STATE_STATUSREASON 2
 69→#define CURL4NX_STATE_HEADERS      3
 70→#define CURL4NX_STATE_DATA_NORMAL  4
 71→#define CURL4NX_STATE_DATA_CHUNKED 5
