 97→  r2 = snd_ctl_set(CODEC_CARD, "DACR digital volume", reg);
 98→  syslog(LOG_INFO, "[dm-vol] dac vol reg=%u (dACL=%d dACR=%d)\n", reg, r1, r2);
 99→
100→  /* also keep TTS helper in sync (percent, 0 when mute) */
101→  dm_voice_set_speaker_volume(s_mute ? 0 : s_vol);
102→}
