191→/* ---- player: nxplayer (buffer-queue API) ---- */
192→
193→static struct nxplayer_s *s_play;
194→
195→static struct nxplayer_s *player_get(void)
196→{
197→  if (!s_play)
198→    {
199→      s_play = nxplayer_create();
200→      if (s_play)
201→        {
202→          (void)nxplayer_setdevice(s_play, "/dev/audio/pcm0p");
203→        }
204→    }
