1839→/****************************************************************************
1840→ * Name: nxplayer_playinternal
1841→ *
1842→ *   nxplayer_playinternal() tries to play the specified file/raw data
1843→ *   using the Audio system.  If a preferred device is specified, it will
1844→ *   try to use that device otherwise it will perform a search of the Audio
1845→ *   device files to find a suitable device.
1846→ *
1847→ * Input:
1848→ *   pplayer    Pointer to the initialized MPlayer context
1849→ *   filefmt    Format of the file or AUD_FMT_UNDEF if unknown / to be
1850→ *              determined by nxplayer_playfile()
1851→ *   subfmt     Sub-Format of the file or AUD_FMT_UNDEF if unknown / to be
1852→ *              determined by nxplayer_playfile()
1853→ *   nchannels  channels num (raw data playback needed)
1854→ *   bpsamp     bits pre sample (raw data playback needed)
1855→ *   samprate  samplre rate (raw data playback needed)
1856→ *   chmap      channel map (raw data playback needed)
1857→ *
1858→ * Returns:
1859→ *   OK         File is being played
1860→ *   -EBUSY     The media device is busy
1861→ *   -ENOSYS    The media file is an unsupported type
1862→ *   -ENODEV    No audio device suitable to play the media type
1863→ *   -ENOENT    The media file was not found
1864→ *
1865→ *
1866→ ****************************************************************************/
1867→
1868→static int nxplayer_playinternal(FAR struct nxplayer_s *pplayer,
1869→                                 int filefmt, int subfmt,
1870→                                 uint8_t nchannels, uint8_t bpsamp,
1871→                                 uint32_t samprate, uint8_t chmap)
1872→{
1873→  struct mq_attr      attr;
1874→  struct sched_param  sparam;
1875→  pthread_attr_t      tattr;
1876→  struct audio_caps_desc_s cap_desc;
1877→  struct ap_buffer_info_s  buf_info;
1878→  struct audio_caps_s      caps;
1879→  int                      min_channels;
1880→  int                 ret;
1881→
1882→  /* Try to open the device */
1883→
1884→  ret = nxplayer_opendevice(pplayer, filefmt, subfmt);
1885→  if (ret < 0)
1886→    {
1887→      /* Error opening the device */
1888→
1889→      auderr("ERROR: nxplayer_opendevice failed: %d\n", ret);
1890→      return ret;
1891→    }
1892→
1893→  /* Try to reserve the device */
1894→
1895→#ifdef CONFIG_AUDIO_MULTI_SESSION
1896→  ret = ioctl(pplayer->dev_fd, AUDIOIOC_RESERVE,
1897→              (unsigned long)&pplayer->session);
1898→#else
1899→  ret = ioctl(pplayer->dev_fd, AUDIOIOC_RESERVE, 0);
1900→#endif
1901→  if (ret < 0)
1902→    {
1903→      /* Device is busy or error */
1904→
1905→      auderr("ERROR: Failed to reserve device: %d\n", ret);
1906→      ret = -errno;
1907→      goto err_out;
1908→    }
1909→
1910→  caps.ac_len = sizeof(caps);
1911→  caps.ac_type = AUDIO_TYPE_OUTPUT;
1912→  caps.ac_subtype = AUDIO_TYPE_QUERY;
1913→
1914→  if (ioctl(pplayer->dev_fd, AUDIOIOC_GETCAPS,
1915→      (unsigned long)&caps) == caps.ac_len)
1916→    {
1917→      min_channels = caps.ac_channels >> 4;
1918→
1919→      if (min_channels != 0 && nchannels < min_channels)
1920→        {
1921→          ret = -EINVAL;
1922→          goto err_out;
1923→        }
1924→    }
1925→
1926→  if (nchannels && samprate && bpsamp)
1927→    {
1928→#ifdef CONFIG_AUDIO_MULTI_SESSION
1929→      cap_desc.session = pplayer->session;
1930→#endif
1931→      cap_desc.caps.ac_len            = sizeof(struct audio_caps_s);
1932→      cap_desc.caps.ac_type           = AUDIO_TYPE_OUTPUT;
1933→      cap_desc.caps.ac_channels       = nchannels;
1934→      cap_desc.caps.ac_chmap          = chmap;
1935→      cap_desc.caps.ac_controls.hw[0] = samprate;
1936→      cap_desc.caps.ac_controls.b[3]  = samprate >> 16;
1937→      cap_desc.caps.ac_controls.b[2]  = bpsamp;
1938→      cap_desc.caps.ac_subtype        = filefmt;
1939→
1940→      ioctl(pplayer->dev_fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap_desc);
1941→    }
1942→
1943→  /* Query the audio device for its preferred buffer count */
1944→
1945→  if (ioctl(pplayer->dev_fd, AUDIOIOC_GETBUFFERINFO,
1946→            (unsigned long)&buf_info) != OK)
1947→    {
1948→      /* Driver doesn't report its buffer size.  Use our default. */
1949→
1950→      buf_info.nbuffers = CONFIG_AUDIO_NUM_BUFFERS;
1951→    }
1952→
1953→  /* Create a message queue for the playthread */
1954→
1955→  attr.mq_maxmsg  = buf_info.nbuffers + 8;
1956→  attr.mq_msgsize = sizeof(struct audio_msg_s);
1957→  attr.mq_curmsgs = 0;
1958→  attr.mq_flags   = 0;
1959→
1960→  snprintf(pplayer->mqname, sizeof(pplayer->mqname), "/tmp/%0lx",
1961→           (unsigned long)((uintptr_t)pplayer));
1962→
1963→  pplayer->mq = mq_open(pplayer->mqname, O_RDWR | O_CREAT, 0644, &attr);
1964→  if (pplayer->mq == (mqd_t) -1)
1965→    {
1966→      /* Unable to open message queue! */
1967→
1968→      ret = -errno;
1969→      auderr("ERROR: mq_open failed: %d\n", ret);
1970→      goto err_out;
1971→    }
1972→
1973→  /* Register our message queue with the audio device */
1974→
1975→  ioctl(pplayer->dev_fd, AUDIOIOC_REGISTERMQ, (unsigned long)pplayer->mq);
1976→
1977→  /* Check if there was a previous thread and join it if there was
1978→   * to perform clean-up.
1979→   */
1980→
1981→  nxplayer_jointhread(pplayer);
1982→
1983→  /* Start the playfile thread to stream the media file to the
1984→   * audio device.
1985→   */
1986→
1987→  ret = pthread_attr_init(&tattr);
1988→  if (ret != OK)
1989→    {
1990→      auderr("ERROR: Failed to init playthread: %d\n", ret);
1991→      goto err_out;
1992→    }
1993→
1994→  sparam.sched_priority = sched_get_priority_max(SCHED_FIFO) - 9;
1995→  pthread_attr_setschedparam(&tattr, &sparam);
1996→  pthread_attr_setstacksize(&tattr,
1997→                            CONFIG_NXPLAYER_PLAYTHREAD_STACKSIZE);
1998→
1999→  /* Add a reference count to the player for the thread and start the
2000→   * thread.  We increment for the thread to avoid thread start-up
2001→   * race conditions.
2002→   */
2003→
2004→  nxplayer_reference(pplayer);
2005→  ret = pthread_create(&pplayer->play_id, &tattr, nxplayer_playthread,
2006→                       (pthread_addr_t) pplayer);
2007→  pthread_attr_destroy(&tattr);
2008→  if (ret != OK)
2009→    {
2010→      auderr("ERROR: Failed to create playthread: %d\n", ret);
2011→      goto err_out;
2012→    }
2013→
2014→  /* Name the thread */
2015→
2016→  pthread_setname_np(pplayer->play_id, "playthread");
2017→  return OK;
2018→
2019→err_out:
2020→  close(pplayer->dev_fd);
2021→  pplayer->dev_fd = -1;
2022→
2023→  return ret;
2024→}
