1322→static void *reconnect_thread(void *arg)
1323→{
1324→  char ssid[33];
1325→  char pass[64];
1326→  int attempt;
1327→  int i;
1328→
1329→  (void)arg;
1330→  ssid[0] = '\0';
1331→  pass[0] = '\0';
1332→  if (wifi_cred_load(ssid, sizeof(ssid), pass, sizeof(pass)) != 0 ||
1333→      !ssid[0])
1334→    {
1335→      syslog(LOG_WARNING, "[deskmate-wifi] reconnect skipped: no saved credentials\n");
1336→      goto done;
1337→    }
1338→
1339→  for (attempt = 0; attempt < 4 && s_wifi_enabled; attempt++)
1340→    {
1341→      if (dm_wifi_connected() || s_manual_override)
1342→        {
1343→          break;
1344→        }
1345→
1346→      if (attempt > 0)
1347→        {
1348→          sleep(DM_WIFI_CONN_RETRY_SEC);
1349→        }
1350→      if (s_scan_busy || s_conn_busy)
1351→        {
1352→          continue;
1353→        }
1354→
1355→      syslog(LOG_INFO, "[deskmate-wifi] saved-network reconnect attempt %d\n",
1356→             attempt + 1);
1357→      if (wifi_start_connect_internal(ssid, pass, 1) != 0)
1358→        {
1359→          continue;
1360→        }
1361→
1362→      for (i = 0; i < 240 && s_conn_busy && s_wifi_enabled &&
1363→                  !s_manual_override; i++)
1364→        {
1365→          usleep(100 * 1000);
1366→        }
1367→      if (dm_wifi_connected())
1368→        {
1369→          break;
1370→        }
1371→    }
1372→
1373→done:
1374→  s_reconnect_running = 0;
1375→  return NULL;
1376→}
