511→/****************************************************************************
512→ * Name: nxrecorder_thread_recordthread
513→ *
514→ *  This is the thread that write the audio file file and enqueues /
515→ *  dequeues buffers from the selected and opened audio device.
516→ *
517→ ****************************************************************************/
518→
519→static FAR void *nxrecorder_recordthread(pthread_addr_t pvarg)
520→{
521→  FAR struct nxrecorder_s *precorder = (FAR struct nxrecorder_s *)pvarg;
522→  struct audio_msg_s      msg;
523→  struct audio_buf_desc_s buf_desc;
524→  ssize_t                 size;
525→  bool                    running = true;
526→  bool                    streaming = true;
527→  bool                    failed = false;
528→  struct ap_buffer_info_s buf_info;
529→  FAR struct ap_buffer_s  **pbuffers;
530→  unsigned int            prio;
531→#ifdef CONFIG_DEBUG_FEATURES
532→  int                     outstanding = 0;
533→#endif
534→  int                     x;
535→  int                     ret;
536→
537→  audinfo("Entry\n");
538→
539→  /* Query the audio device for its preferred buffer size / qty */
540→
541→  if ((ret = ioctl(precorder->dev_fd, AUDIOIOC_GETBUFFERINFO,
542→                   (uintptr_t)&buf_info)) != OK)
543→    {
544→      /* Driver doesn't report its buffer size.  Use our default. */
545→
546→      buf_info.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
547→      buf_info.nbuffers = CONFIG_AUDIO_NUM_BUFFERS;
548→    }
549→
550→  /* Create array of pointers to buffers */
551→
552→  pbuffers = (FAR struct ap_buffer_s **) malloc(buf_info.nbuffers *
553→                                                sizeof(FAR void *));
554→  if (pbuffers == NULL)
555→    {
556→      /* Error allocating memory for buffer storage! */
557→
558→      ret = -ENOMEM;
559→      running = false;
560→      goto err_out;
561→    }
562→
563→  /* Create our audio pipeline buffers to use for queueing up data */
564→
565→  for (x = 0; x < buf_info.nbuffers; x++)
566→    {
567→      pbuffers[x] = NULL;
568→    }
569→
570→  for (x = 0; x < buf_info.nbuffers; x++)
571→    {
572→      /* Fill in the buffer descriptor struct to issue an alloc request */
573→
574→#ifdef CONFIG_AUDIO_MULTI_SESSION
575→      buf_desc.session = precorder->session;
576→#endif
577→
578→      buf_desc.numbytes = buf_info.buffer_size;
579→      buf_desc.u.pbuffer = &pbuffers[x];
580→
581→      ret = ioctl(precorder->dev_fd, AUDIOIOC_ALLOCBUFFER,
582→                  (uintptr_t)&buf_desc);
583→      if (ret != sizeof(buf_desc))
584→        {
585→          /* Buffer alloc Operation not supported or error allocating! */
586→
587→          auderr("ERROR: Could not allocate buffer %d\n", x);
588→          running = false;
589→          goto err_out;
590→        }
591→    }
592→
593→  /* Fill up the pipeline with enqueued buffers */
594→
595→  for (x = 0; x < buf_info.nbuffers; x++)
596→    {
597→      /* Write the next buffer of data */
598→
599→      ret = nxrecorder_enqueuebuffer(precorder, pbuffers[x]);
600→      if (ret != OK)
601→        {
602→          /* Failed to enqueue the buffer.  The driver is not happy with
603→           * the buffer.  Perhaps a encoder has detected something that it
604→           * does not like in the stream and has stopped streaming.  This
605→           * would happen normally if we send a file in the incorrect format
606→           * to an audio encoder.
607→           *
608→           * We must stop streaming as gracefully as possible.  Close the
609→           * file so that no further data is written.
610→           */
611→
612→          close(precorder->fd);
613→          precorder->fd = -1;
614→
615→          /* We are no longer streaming data to the file.  Be we will
616→           * need to wait for any outstanding buffers to be recovered.  We
617→           * also still expect the audio driver to send a AUDIO_MSG_COMPLETE
618→           * message after all queued buffers have been returned.
619→           */
620→
621→           streaming = false;
622→           failed = true;
623→           break;
624→        }
625→#ifdef CONFIG_DEBUG_FEATURES
626→      else
627→        {
628→          /* The audio driver has one more buffer */
629→
630→          outstanding++;
631→        }
632→#endif
633→    }
634→
635→  audinfo("%d buffers queued, running=%d streaming=%d\n",
636→          x, running, streaming);
637→
638→  /* Start the audio device */
639→
640→  if (running && !failed)
641→    {
642→#ifdef CONFIG_AUDIO_MULTI_SESSION
643→      ret = ioctl(precorder->dev_fd, AUDIOIOC_START,
644→                  (uintptr_t)precorder->session);
645→#else
646→      ret = ioctl(precorder->dev_fd, AUDIOIOC_START, 0);
647→#endif
648→
649→      if (ret < 0)
650→        {
651→          /* Error starting the audio stream!  We need to continue running
652→           * in order to recover the audio buffers that have already been
653→           * queued.
654→           */
655→
656→          failed = true;
657→        }
658→    }
659→
660→  if (running && !failed)
661→    {
662→      /* Indicate we are recording a file */
663→
664→      precorder->state = NXRECORDER_STATE_RECORDING;
665→    }
666→
667→  /* Loop until we specifically break.  running == true means that we are
668→   * still looping waiting for the recordback to complete.  All of the file
669→   * data may have been sent (if streaming == false), but the recordback is
670→   * not complete until we get the AUDIO_MSG_COMPLETE (or AUDIO_MSG_STOP)
671→   * message
672→   *
673→   * The normal protocol for streaming errors detected by the audio driver
674→   * is as follows:
675→   *
676→   * (1) The audio driver will indicated the error by returning a negated
677→   *     error value when the next buffer is enqueued.  The upper level
678→   *     then knows that this buffer was not queue.
679→   * (2) The audio driver must return all queued buffers using the
680→

