  89→static struct nxrecorder_s *s_rec;
  90→
  91→static void *rec_auto_stop(void *arg)
  92→{
  93→  int max_sec = (int)(intptr_t)arg;
  94→
  95→  sleep(max_sec > 0 ? max_sec : REC_MAX_SEC);
  96→  (void)dm_voice_rec_stop();
