 347→/* Play one short 440Hz test tone.  This is synchronous by design; callers
 348→ * run it on a worker so neither LVGL nor the recorder UI can block. */
 349→int dm_voice_beep(void)
 350→{
 351→  struct nxplayer_s *p = NULL;
 352→  int rc = -1;
 353→
 354→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 355→    {
 356→      return -EBUSY;
 357→    }
 358→  if (s_rec_active)
 359→    {
 360→      pthread_mutex_unlock(&s_audio_lock);
 361→      return -EBUSY;
 362→    }
 363→
 364→  p = nxplayer_create();
 365→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
 366→    {
 367→      goto out;
 368→    }
 369→
 370→  if (nxplayer_playtone(p, 16000, 440, 1) != OK)
 371→    {
 372→      goto out;
 373→    }
 374→
 375→  /* Tone playback is asynchronous; wait slightly beyond its duration and
 376→   * join it before allowing the next audio operation. */
 377→  usleep(1150 * 1000);
 378→  (void)nxplayer_stop(p);
 379→  rc = 0;
 380→
 381→out:
 382→  if (p)
 383→    {
 384→      nxplayer_release(p);
 385→    }
 386→  pthread_mutex_unlock(&s_audio_lock);
 387→  return rc;
 388→}
