 406→static void json_escape(const char *in, char *out, size_t cap)
 407→{
 408→  size_t o = 0;
 409→  size_t i;
 410→  if (!in || !out || cap < 2)
 411→    {
 412→      if (out && cap)
 413→        {
 414→          out[0] = '\0';
 415→        }
 416→      return;
 417→    }
 418→  for (i = 0; in[i] && o + 8 < cap; i++)
 419→    {
 420→      unsigned char ch = (unsigned char)in[i];
 421→      if (ch == '"' || ch == '\\')
 422→        {
 423→          out[o++] = '\\';
 424→          out[o++] = (char)ch;
 425→        }
 426→      else if (ch == '\n')
 427→        {
 428→          out[o++] = '\\';
 429→          out[o++] = 'n';
 430→        }
 431→      else if (ch >= 0x20)
 432→        {
 433→          out[o++] = (char)ch;
 434→        }
 435→    }
 436→  out[o] = '\0';
 437→}
