 984→int dm_voice_asr_chat_tts(const char *wav_path, char *reply, int cap)
 985→{
 986→  char text[256];
 987→  const char *asr_path;
 988→  int play_rc = -1;
 989→
 990→  if (!wav_path || !reply || cap < 8)
 991→    {
 992→      return -1;
 993→    }
 994→  reply[0] = '\0';
 995→
 996→  if (voice_prepare_wav(wav_path, &asr_path) != 0)
 997→    {
 998→      s_st = DM_VOICE_ERR;
 999→      return -1;
1000→    }
1001→
1002→  s_st = DM_VOICE_ASR;
1003→  if (asr_wav(asr_path, text, sizeof(text)) != 0)
1004→    {
1005→      s_st = DM_VOICE_ERR;
1006→      return -1;
1007→    }
1008→
1009→  s_st = DM_VOICE_CHAT;
1010→  if (chat_reply(text, reply, cap) != 0)
1011→    {
1012→      strncpy(reply, "（网络忙，没听清）", (size_t)cap - 1);
1013→      reply[cap - 1] = '\0';
1014→      s_st = DM_VOICE_ERR;
1015→      return -1;
1016→    }
1017→
1018→  /* Preserve the text answer even if playback fails; the caller can show
1019→   * that the reply is text-only rather than pretending the speaker worked. */
1020→  s_st = DM_VOICE_TTS;
1021→  if (tts_synth(reply, WAV_TTS) == 0)
1022→    {
1023→      s_st = DM_VOICE_PLAY;
1024→      play_rc = play_wav(WAV_TTS);
1025→    }
1026→  s_st = DM_VOICE_IDLE;
1027→  return play_rc == 0 ? 0 : 1;
1028→}
