184→      for (i = 1; i < HIST_TURN_MAX; i++)
185→        {
186→          s_hist[i - 1] = s_hist[i];
187→        }
188→      s_hist_n = HIST_TURN_MAX - 1;
189→    }
190→  strncpy(s_hist[s_hist_n].user, user, HIST_LINE - 1);
191→  s_hist[s_hist_n].user[HIST_LINE - 1] = '\0';
192→  if (assistant)
193→    {
194→      strncpy(s_hist[s_hist_n].bot, assistant, HIST_LINE - 1);
195→      s_hist[s_hist_n].bot[HIST_LINE - 1] = '\0';
196→    }
197→  else
198→    {
199→      s_hist[s_hist_n].bot[0] = '\0';
200→    }
201→  s_hist_n++;
202→}
