204→/* emit {"role":..,"content":..}, entries (each with trailing comma) */
205→int dm_chat_hist_json(char *out, int cap)
206→{
207→  char esc[HIST_LINE * 2];
208→  int o = 0;
209→  int i;
210→
211→  if (!out || cap < 2)
212→    {
213→      return -1;
214→    }
215→  out[0] = '\0';
216→  for (i = 0; i < s_hist_n; i++)
217→    {
218→      int n;
219→
220→      if (s_hist[i].user[0])
221→        {
222→          json_escape(s_hist[i].user, esc, sizeof(esc));
223→          n = snprintf(out + o, (size_t)(cap - o),
224→                       "{\"role\":\"user\",\"content\":\"%s\"},", esc);
225→          if (n < 0 || n >= cap - o)
226→            {
227→              out[o] = '\0';
228→              return -1;
229→            }
230→          o += n;
231→        }
232→      if (s_hist[i].bot[0])
233→        {
234→          json_escape(s_hist[i].bot, esc, sizeof(esc));
235→          n = snprintf(out + o, (size_t)(cap - o),
236→                       "{\"role\":\"assistant\",\"content\":\"%s\"},", esc);
237→          if (n < 0 || n >= cap - o)
238→            {
239→              out[o] = '\0';
240→              return -1;
241→            }
242→          o += n;
243→        }
244→    }
245→  return o;
246→}
