 272→static void wifi_restart_ntp_after_link(void)
 273→{
 274→  int stop_rc;
 275→  int start_rc;
 276→
 277→  /* The boot-time daemon may have spent its exponential retry delay without
 278→   * a network. Wake/restart it after WLAN gets a valid address. */
 279→  stop_rc = ntpc_stop();
 280→  start_rc = ntpc_start();
 281→  syslog(start_rc < 0 ? LOG_WARNING : LOG_INFO,
 282→         "[deskmate-wifi] NTP refresh requested stop=%d start=%d\n",
 283→         stop_rc, start_rc);
 284→}
 285→
 286→int dm_wifi_wait_time_sync(int timeout_sec)
 287→{
 288→  int i;
 289→
 290→  if (timeout_sec < 0)
 291→    {
 292→      timeout_sec = 0;
 293→    }
 294→  if (timeout_sec > 90)
 295→    {
 296→      timeout_sec = 90;
 297→    }
 298→
 299→  for (i = 0; i <= timeout_sec; i++)
 300→    {
 301→      if (wifi_clock_synced())
 302→        {
 303→          return 0;
 304→        }
 305→      if (!dm_wifi_connected())
 306→        {
 307→          return -ENETDOWN;
 308→        }
 309→      if (i < timeout_sec)
 310→        {
 311→          sleep(1);
 312→        }
 313→    }
 314→
 315→  syslog(LOG_WARNING,
 316→         "[deskmate-wifi] NTP time not ready; HTTPS request deferred\n");
 317→  return -ETIMEDOUT;
 318→}
