 366→/* Verify the current association is really the expected SSID.
 367→ * Returns 1 = match, 0 = mismatch / not associated, -1 = cannot read. */
 368→static int wifi_verify_assoc(const char *expected)
 369→{
 370→  char assoc[33];
 371→
 372→  if (!expected || !expected[0])
 373→    {
 374→      return -1;
 375→    }
 376→  if (!wifi_is_associated(assoc, sizeof(assoc)))
 377→    {
 378→      return 0;
 379→    }
 380→  if (!assoc[0])
 381→    {
 382→      return -1;
 383→    }
 384→  return strcmp(assoc, expected) == 0 ? 1 : 0;
 385→}
