 535→static void wifi_unquote(char *s)
 536→{
 537→  size_t n;
 538→
 539→  if (!s || s[0] != '"')
 540→    {
 541→      return;
 542→    }
 543→  n = strlen(s);
 544→  if (n >= 2 && s[n - 1] == '"')
 545→    {
 546→      memmove(s, s + 1, n - 2);
 547→      s[n - 2] = 0;
 548→    }
 549→}
