 673→static int wifi_cred_load(char *ssid, size_t slen, char *pass, size_t plen)
 674→{
 675→  FILE *f = fopen(DM_WIFI_SAVE_PATH, "r");
 676→  char line[96];
 677→
 678→  if (f)
 679→    {
 680→      if (fgets(line, sizeof(line), f))
 681→        {
 682→          line[strcspn(line, "\r\n")] = 0;
 683→          if (line[0])
 684→            {
 685→              snprintf(ssid, slen, "%s", line);
