1343→static void *reconnect_thread(void *arg)
1344→{
1345→  char ssid[33];
1346→  char pass[64];
1347→  int attempt;
1348→  int i;
1349→
1350→  (void)arg;
1351→  ssid[0] = '\0';
1352→  pass[0] = '\0';
1353→  if (wifi_cred_load(ssid, sizeof(ssid), pass, sizeof(pass)) != 0 ||
1354→      !ssid[0])
1355→    {
1356→      syslog(LOG_WARNING, "[deskmate-wifi] reconnect skipped: no saved credentials\n");
1357→      goto done;
1358→    }
1359→
1360→  for (attempt = 0; attempt < 4 && s_wifi_enabled; attempt++)
1361→    {
1362→      if (dm_wifi_connected() || s_manual_override)
1363→        {
1364→          break;
1365→        }
1366→
1367→      if (attempt > 0)
1368→        {
1369→          sleep(DM_WIFI_CONN_RETRY_SEC);
1370→        }
1371→      if (s_scan_busy || s_conn_busy)
1372→        {
1373→          continue;
1374→        }
1375→
1376→      syslog(LOG_INFO, "[deskmate-wifi] saved-network reconnect attempt %d\n",
1377→             attempt + 1);
1378→      if (wifi_start_connect_internal(ssid, pass, 1) != 0)
1379→        {
1380→          continue;
1381→        }
1382→
1383→      for (i = 0; i < 600 && s_conn_busy && s_wifi_enabled &&
1384→                  !s_manual_override; i++)
1385→        {
1386→          usleep(100 * 1000);
1387→        }
1388→      if (dm_wifi_connected())
1389→        {
1390→          break;
1391→        }
1392→    }
1393→
1394→done:
1395→  s_reconnect_running = 0;
1396→  s_reconnect_retry_after_ms = wifi_monotonic_ms() + 30000;
1397→  return NULL;
1398→}
1399→
1400→static void wifi_request_reconnect(void)
1401→{
1402→  pthread_t th;
1403→  pthread_attr_t attr;
1404→
1405→  uint64_t now_ms = wifi_monotonic_ms();
1406→
1407→  if (!s_wifi_enabled || s_manual_override || dm_wifi_connected() ||
1408→      s_reconnect_running || s_auto_thread_active || s_scan_busy || s_conn_busy ||
1409→      (s_reconnect_retry_after_ms != 0 &&
1410→       now_ms < s_reconnect_retry_after_ms))
1411→    {
1412→      return;
1413→    }
1414→
1415→  s_reconnect_running = 1;
1416→  pthread_attr_init(&attr);
1417→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1418→  if (pthread_create(&th, &attr, reconnect_thread, NULL) == 0)
1419→    {
1420→      pthread_detach(th);
1421→    }
1422→  else
1423→    {
1424→      s_reconnect_running = 0;
1425→    }
1426→  pthread_attr_destroy(&attr);
1427→}
