 99→/* worker thread — NO LVGL calls here */
100→static void *voice_worker(void *arg)
101→{
102→  char reply[CHAT_LINE_MAX];
103→  int voice_rc;
104→
105→  (void)arg;
106→
107→  if (s_job == 1)
108→    {
109→      /* nxrecorder_stop() joins its audio worker.  Never call it from the
110→       * LVGL click callback: a slow/failed PCM read must not freeze the UI. */
111→      if (dm_voice_rec_stop() != 0)
112→        {
113→          snprintf(s_out_ans, sizeof(s_out_ans), "%s",
114→                   dm_t("录音失败，未采集到有效音频",
115→                        "Recording failed; no audio captured"));
116→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
117→                   dm_t("检查麦克风和 /dev/audio/pcm0c",
118→                        "Check the microphone and /dev/audio/pcm0c"));
119→          s_out_ready = 1;
120→          return NULL;
121→        }
122→
123→      snprintf(s_out_sub, sizeof(s_out_sub), "%s",
124→               dm_t("ASR → 模型 → 喇叭播报", "ASR → LLM → speaker"));
125→      voice_rc = dm_voice_asr_chat_tts("/tmp/dm_voice_in.wav", reply,
126→                                       sizeof(reply));
127→      if (voice_rc >= 0)
128→        {
129→          snprintf(s_out_ans, sizeof(s_out_ans), "%s", reply);
130→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
131→                   voice_rc == 0
132→                     ? dm_t("已通过喇叭播放回复", "Reply played on speaker")
133→                     : dm_t("文字回复已显示，语音播报失败",
134→                            "Text reply shown; speech playback failed"));
135→          s_out_ready = 1;
136→        }
137→      else
138→        {
139→          /* Do not replace failed speech recognition with a fabricated
140→           * generic chat prompt; preserve the failure and let the user retry
141→           * or explicitly choose the face/text-chat action. */
142→          snprintf(s_out_ans, sizeof(s_out_ans), "%s",
143→                   dm_t("语音识别失败，请重试", "Speech recognition failed"));
144→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
145→                   dm_t("检查录音和网络，或点脸使用文字聊天",
146→                        "Check mic/network, or tap the face for text chat"));
147→          s_out_ready = 1;
148→        }
149→    }
150→  else if (s_job == 2)
151→    {
152→      const char *r = dm_chat_ai_ask(s_pending);
153→      snprintf(s_out_ans, sizeof(s_out_ans), "%s", r ? r : "……");
154→      if (r && r[0] && dm_chat_ai_remote_ok())
155→        {
156→          if (dm_voice_tts_play(r) == 0)
157→            {
158→              snprintf(s_out_sub, sizeof(s_out_sub), "%s",
159→                       dm_t("已通过喇叭播放回复", "Reply played on speaker"));
160→            }
161→          else
162→            {
163→              snprintf(s_out_sub, sizeof(s_out_sub), "%s",
164→                       dm_t("文字回复已显示，语音播报失败",
165→                            "Text reply shown; speech playback failed"));
166→            }
167→        }
168→      else if (r && r[0])
169→        {
170→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
171→                   dm_t("云端连接失败，当前显示离线回复",
172→                        "Cloud unavailable; showing offline reply"));
173→        }
174→      else
175→        {
176→          s_out_sub[0] = '\0';
177→        }
178→      s_out_ready = 1;
179→    }
180→  return NULL;
181→}
