 47→static void request_preview(const char *text)
 48→{
 49→  struct voice_preview_job_s *job;
 50→  pthread_t th;
 51→  pthread_attr_t attr;
 52→  int ret;
 53→
 54→  if (s_preview_busy)
 55→    {
 56→      return;
 57→    }
 58→
 59→  job = malloc(sizeof(*job));
 60→  if (!job)
 61→    {
 62→      if (s_tip_l)
 63→        {
 64→          lv_label_set_text(s_tip_l, dm_t("内存不足，无法试听",
 65→                                          "Not enough memory to preview"));
 66→        }
 67→      return;
 68→    }
 69→  snprintf(job->text, sizeof(job->text), "%s", text ? text : "");
 70→  s_preview_busy = 1;
 71→  s_preview_done = 0;
 72→
 73→  pthread_attr_init(&attr);
 74→  pthread_attr_setstacksize(&attr, 24576);
 75→  ret = pthread_create(&th, &attr, voice_preview_worker, job);
 76→  pthread_attr_destroy(&attr);
 77→  if (ret == 0)
 78→    {
 79→      pthread_detach(th);
 80→    }
 81→  else
 82→    {
 83→      free(job);
 84→      s_preview_busy = 0;
 85→      if (s_tip_l)
 86→        {
 87→          lv_label_set_text(s_tip_l, dm_t("试听启动失败",
 88→                                          "Could not start preview"));
 89→        }
 90→    }
 91→}
