211→/* NSH-safe single-quote wrap; reject embedded single quotes */
212→static int shell_quote(const char *in, char *out, size_t outsz)
213→{
214→  size_t n;
215→  size_t o = 0;
216→
217→  if (!in || !out || outsz < 3)
218→    {
219→      return -1;
220→    }
221→  if (strchr(in, '\'') != NULL)
222→    {
223→      return -1;
224→    }
225→  n = strlen(in);
226→  if (n + 3 > outsz)
227→    {
228→      return -1;
229→    }
230→  out[o++] = '\'';
231→  memcpy(out + o, in, n);
232→  o += n;
233→  out[o++] = '\'';
234→  out[o] = 0;
235→  return 0;
236→}
