/* Check for a runtime-only key file without ever logging or embedding its
 * contents in the firmware or generated curl script. */
static int voice_key_available(void)
{
  FILE *f = fopen(MIMO_KEY_PATH, "rb");
  char key[128];
  size_t i;
  size_t n;
  int valid = 0;

  if (!f)
    {
      return 0;
    }

  if (fgets(key, sizeof(key), f))
    {
      n = strlen(key);
      while (n > 0 && (key[n - 1] == '\r' || key[n - 1] == '\n' ||
                       key[n - 1] == ' ' || key[n - 1] == '\t'))
        {
          key[--n] = '\0';
        }
      valid = n > 8 && n < sizeof(key) - 1;
      for (i = 0; valid && i < n; i++)
        {
          unsigned char ch = (unsigned char)key[i];
          if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
                (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' ||
                ch == '.'))
            {
              valid = 0;
            }
        }
    }

  memset(key, 0, sizeof(key));
  fclose(f);
  return valid;
}

/* Run curl from a script so nsh cannot strip quoted header arguments. The
 * script reads the key at runtime, keeping credentials out of /tmp scripts. */
static int run_curl_script(const char *line)
{
  FILE *f;
  int write_ok;
  int close_rc;
  int rc;

  if (!voice_key_available())
    {
      s_last_failure = DM_VOICE_FAILURE_API_KEY;
      syslog(LOG_ERR, "[dm-voice] runtime API key missing or invalid\n");
      return -1;
    }

  f = fopen(VOICE_CURL_SCRIPT, "w");
  if (!f)
    {
      syslog(LOG_ERR, "[dm-voice] cannot create curl script\n");
      return -1;
    }

  write_ok = fputs("#!/bin/sh\n", f) != EOF &&
             fputs("MIMO_API_KEY=$(cat " MIMO_KEY_PATH ")\n", f) != EOF &&
             fputs("[ -n $MIMO_API_KEY ] || exit 2\n", f) != EOF &&
             fputs(line, f) != EOF && fputc('\n', f) != EOF;
  close_rc = fclose(f);
  if (!write_ok || close_rc != 0)
    {
      syslog(LOG_ERR, "[dm-voice] cannot write curl script\n");
      return -1;
    }

  rc = system("sh " VOICE_CURL_SCRIPT);
  if (rc != 0)
    {
      syslog(LOG_ERR, "[dm-voice] curl script failed status=%d\n", rc);
      return -1;
    }
  return 0;
}

