449→/* Load and validate the key supplied at runtime. Never log or compile it. */
450→static int voice_key_load(char *key, size_t key_cap)
451→{
452→  FILE *f;
453→  size_t i;
454→  size_t n;
455→  int valid = 0;
456→
457→  if (!key || key_cap < 16)
458→    {
459→      return 0;
460→    }
461→  key[0] = '\0';
462→  f = fopen(MIMO_KEY_PATH, "rb");
463→  if (!f)
464→    {
465→      return 0;
466→    }
467→
468→  if (fgets(key, (int)key_cap, f))
469→    {
470→      n = strlen(key);
471→      while (n > 0 && (key[n - 1] == '\r' || key[n - 1] == '\n' ||
472→                       key[n - 1] == ' ' || key[n - 1] == '\t'))
473→        {
474→          key[--n] = '\0';
475→        }
476→      valid = n > 8 && n < key_cap - 1;
477→      for (i = 0; valid && i < n; i++)
478→        {
479→          unsigned char ch = (unsigned char)key[i];
480→          if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
481→                (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' ||
482→                ch == '.'))
483→            {
484→              valid = 0;
485→            }
486→        }
487→    }
488→
489→  fclose(f);
490→  if (!valid)
491→    {
492→      memset(key, 0, key_cap);
493→    }
494→  return valid;
495→}
