 875→static int ntpc_create_dgram_socket(int domain)
 876→{
 877→  struct timeval tv;
 878→  int ret;
 879→  int sd;
 880→  int err;
 881→
 882→  /* Create a datagram socket  */
 883→
 884→  sd = socket(domain, SOCK_DGRAM, 0);
 885→  if (sd < 0)
 886→    {
 887→      err = errno;
 888→      nerr("ERROR: socket failed: %d\n", err);
 889→      errno = err;
