 891→    }
 892→
 893→  /* Setup a send timeout on the socket */
 894→
 895→  tv.tv_sec  = CONFIG_NETUTILS_NTPCLIENT_TIMEOUT_MS / 1000;
 896→  tv.tv_usec = CONFIG_NETUTILS_NTPCLIENT_TIMEOUT_MS % 1000;
 897→
 898→  ret = setsockopt(sd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(struct timeval));
 899→  if (ret < 0)
 900→    {
 901→      err = errno;
 902→      nerr("ERROR: setsockopt(SO_SNDTIMEO) failed: %d\n", errno);
 903→      goto err_close;
 904→    }
 905→
 906→  /* Setup a receive timeout on the socket */
 907→
 908→  ret = setsockopt(sd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(struct timeval));
 909→  if (ret < 0)
 910→    {
 911→      err = errno;
 912→      nerr("ERROR: setsockopt(SO_RCVTIMEO) failed: %d\n", errno);
 913→      goto err_close;
 914→    }
 915→
 916→  return sd;
 917→
 918→err_close:
 919→  close(sd);
 920→  errno = err;
 921→  return ret;
