 76→ ****************************************************************************/
 77→
 78→int main(int argc, FAR char *argv[])
 79→{
 80→  struct ntpc_status_s status;
 81→  unsigned int i;
 82→  int ret;
 83→
 84→  ret = ntpc_status(&status);
 85→  if (ret < 0)
 86→    {
 87→      fprintf(stderr, "ERROR: ntpc_status() failed\n");
 88→      return EXIT_FAILURE;
 89→    }
 90→
 91→  printf("The number of last samples: %u\n", status.nsamples);
 92→  for (i = 0; i < status.nsamples; i++)
 93→    {
 94→      FAR const struct sockaddr *sa;
 95→      socklen_t salen;
 96→      FAR const char *name = "<noname>";
 97→      char offset_buf[NTP_TIME_STR_MAX_LEN];
 98→      char delay_buf[NTP_TIME_STR_MAX_LEN];
 99→
100→      sa = status.samples[i].srv_addr;
101→      salen = (sa->sa_family == AF_INET) ? sizeof(struct sockaddr_in)
102→                                         : sizeof(struct sockaddr_in6);
103→#ifdef CONFIG_LIBC_NETDB
104→      char hbuf[NI_MAXHOST];
105→
106→      ret = getnameinfo(sa, salen,
107→                        hbuf, sizeof(hbuf), NULL, 0, NI_NUMERICHOST);
108→      if (ret == 0)
109→        {
110→          name = hbuf;
111→        }
112→      else
113→        {
114→          fprintf(stderr, "WARNING: getnameinfo failed: %s\n",
115→                  gai_strerror(ret));
116→        }
117→#endif
118→
119→      format_ntptimestamp(status.samples[i].offset,
120→                          offset_buf, sizeof(offset_buf));
121→      format_ntptimestamp(status.samples[i].delay,
122→                          delay_buf, sizeof(delay_buf));
123→      printf("[%u] srv %s offset %s delay %s\n",
124→             i, name, offset_buf, delay_buf);
125→    }
126→
127→  return EXIT_SUCCESS;
128→}
