 25→int flowdesk_main(int argc, FAR char *argv[])
 26→{
 27→  lv_nuttx_dsc_t info;
 28→  lv_nuttx_result_t result;
 29→
 30→  (void)argc;
 31→  (void)argv;
 32→
 33→  if (lv_is_initialized())
 34→    {
 35→      return -1;
 36→    }
 37→
 38→  /* LCD is owned by flowdesk; luncher_mini is not started from rcS
 39→   * when CONFIG_DESKMATE_APP is enabled. killall is unavailable on
 40→   * this NuttX image, so do not rely on it. */
 41→
 42→#ifdef NEED_BOARDINIT
 43→  boardctl(BOARDIOC_INIT, 0);
 44→#endif
 45→
 46→  lv_init();
 47→  lv_nuttx_dsc_init(&info);
 48→#ifdef CONFIG_LV_USE_NUTTX_LCD
 49→  info.fb_path = "/dev/lcd0";
 50→#endif
 51→#ifdef CONFIG_EXAMPLES_LVGLDEMO_INPUT_DEVPATH
 52→  info.input_path = CONFIG_EXAMPLES_LVGLDEMO_INPUT_DEVPATH;
 53→#endif
 54→  lv_nuttx_init(&info, &result);
 55→  usleep(100000);
 56→  if (!result.disp)
 57→    {
 58→      return 1;
 59→    }
 60→
 61→  dm_init_fonts();
 62→  dm_voice_profile_init();
 63→
 64→  g_dm_root = lv_obj_create(lv_screen_active());
 65→  lv_obj_set_size(g_dm_root, DM_SCR_W, DM_SCR_H);
 66→  lv_obj_center(g_dm_root);
