 714→static void time_refresh_labels(void)
 715→{
 716→  char buf[64];
 717→  time_t now = time(NULL);
 718→  struct tm tmv;
 719→  int i;
 720→
 721→  for (i = 0; i < 5; i++)
 722→    {
 723→      if (s_time_value_l[i])
 724→        {
 725→          lv_snprintf(buf, sizeof(buf), "%d", s_time_value[i]);
 726→          lv_label_set_text(s_time_value_l[i], buf);
 727→        }
 728→    }
 729→
 730→  if (!s_time_now_l)
 731→    {
 732→      return;
 733→    }
 734→
 735→  if (now > 0 && localtime_r(&now, &tmv) != NULL)
 736→    {
 737→      lv_snprintf(buf, sizeof(buf), "%s %04d-%02d-%02d %02d:%02d",
 738→                  dm_t("系统时间", "Device"), tmv.tm_year + 1900,
 739→                  tmv.tm_mon + 1, tmv.tm_mday, tmv.tm_hour, tmv.tm_min);
 740→    }
 741→  else
 742→    {
 743→      lv_snprintf(buf, sizeof(buf), "%s", dm_t("系统时间不可用", "Clock unavailable"));
