140→static void extract_content(const char *path, char *out, size_t cap)
141→{
142→  FILE *f;
143→  char *buf;
144→  long sz;
145→  char *p;
146→  char *q;
147→
148→  out[0] = '\0';
149→  f = fopen(path, "rb");
150→  if (!f)
151→    {
152→      return;
153→    }
154→  fseek(f, 0, SEEK_END);
155→  sz = ftell(f);
156→  fseek(f, 0, SEEK_SET);
157→  if (sz <= 0 || sz > 64 * 1024)
158→    {
159→      fclose(f);
160→      return;
161→    }
162→  buf = malloc((size_t)sz + 1);
163→  if (!buf)
164→    {
165→      fclose(f);
166→      return;
167→    }
168→  if (fread(buf, 1, (size_t)sz, f) != (size_t)sz)
169→    {
170→      free(buf);
171→      fclose(f);
172→      return;
173→    }
174→  buf[sz] = '\0';
175→  fclose(f);
176→
177→  p = strstr(buf, "\"content\"");
178→  if (!p)
179→    {
180→      free(buf);
181→      return;
182→    }
183→  p = strchr(p + 9, '"');
184→  if (!p)
185→    {
186→      free(buf);
187→      return;
188→    }
189→  q = strchr(p + 1, '"');
190→  if (!q)
191→    {
192→      free(buf);
193→      return;
194→    }
195→  {
196→    size_t n = (size_t)(q - (p + 1));
197→    if (n >= cap)
198→      {
199→        n = cap - 1;
200→      }
201→    memcpy(out, p + 1, n);
202→    out[n] = '\0';
203→    /* unescape \" and \\ and \n lightly */
204→    {
205→      char *r = out;
206→      char *w = out;
207→      while (*r)
208→        {
209→          if (r[0] == '\\' && r[1] == 'n')
210→            {
211→              *w++ = ' ';
212→              r += 2;
213→            }
214→          else if (r[0] == '\\' && r[1] == '"')
215→            {
216→              *w++ = '"';
217→              r += 2;
218→            }
219→          else if (r[0] == '\\' && r[1] == '\\')
220→            {
221→              *w++ = '\\';
222→              r += 2;
223→            }
224→          else
225→            {
226→              *w++ = *r++;
227→            }
228→        }
229→      *w = '\0';
230→    }
231→  }
232→  free(buf);
233→}
