296→    }
297→  fwrite(body, 1, (size_t)n, f);
298→  fclose(f);
299→
300→  unlink(CHAT_RSP_PATH);
301→  snprintf(cmd, sizeof(cmd),
302→           "curl -sS --cacert /resource/etc/ssl/curl/ca-certificates.crt -m 20 -X POST %s/chat/completions "
303→           "-H 'Authorization: Bearer %s' "
304→           "-H 'Content-Type: application/json' "
305→           "-d @%s -o %s",
306→           MIMO_BASE, MIMO_KEY, CHAT_REQ_PATH, CHAT_RSP_PATH);
307→  if (run_curl_script(cmd) != 0)
308→    {
309→      strncpy(s_last_reply, local_reply(user_text),
310→              sizeof(s_last_reply) - 1);
311→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
312→      return s_last_reply;
313→    }
314→
315→  extract_content(CHAT_RSP_PATH, s_last_reply, sizeof(s_last_reply));
316→  if (!s_last_reply[0])
317→    {
318→      strncpy(s_last_reply, local_reply(user_text),
319→              sizeof(s_last_reply) - 1);
320→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
321→    }
322→  return s_last_reply;
323→}
