 497→static int wifi_cred_load(char *ssid, size_t slen, char *pass, size_t plen)
 498→{
 499→  FILE *f = fopen(DM_WIFI_SAVE_PATH, "r");
 500→  char line[96];
 501→
 502→  if (!f)
 503→    {
 504→      return wifi_cred_load_cfg(ssid, slen, pass, plen);
 505→    }
 506→  if (!fgets(line, sizeof(line), f))
 507→    {
 508→      fclose(f);
 509→      return wifi_cred_load_cfg(ssid, slen, pass, plen);
 510→    }
 511→  line[strcspn(line, "\r\n")] = 0;
 512→  if (!line[0])
 513→    {
 514→      fclose(f);
 515→      return wifi_cred_load_cfg(ssid, slen, pass, plen);
 516→    }
 517→  snprintf(ssid, slen, "%s", line);
 518→  if (fgets(line, sizeof(line), f))
 519→    {
 520→      line[strcspn(line, "\r\n")] = 0;
 521→      snprintf(pass, plen, "%s", line);
 522→    }
 523→  else
 524→    {
 525→      pass[0] = 0;
 526→    }
 527→  fclose(f);
 528→  return 0;
 529→}
