 417→static int json_escape(const char *in, char *out, size_t cap)
 418→{
 419→  size_t o = 0;
 420→  size_t i;
 421→
 422→  if (!in || !out || cap < 2)
 423→    {
 424→      if (out && cap)
 425→        {
 426→          out[0] = '\0';
 427→        }
 428→      return -1;
 429→    }
 430→
 431→  for (i = 0; in[i]; i++)
 432→    {
 433→      unsigned char ch = (unsigned char)in[i];
 434→      size_t need = (ch == '"' || ch == '\\' || ch == '\n') ? 2 :
 435→                    (ch >= 0x20 ? 1 : 0);
 436→
 437→      if (o + need >= cap)
 438→        {
 439→          out[o] = '\0';
 440→          return -1;
 441→        }
 442→      if (ch == '"' || ch == '\\')
 443→        {
 444→          out[o++] = '\\';
 445→          out[o++] = (char)ch;
 446→        }
 447→      else if (ch == '\n')
 448→        {
 449→          out[o++] = '\\';
 450→          out[o++] = 'n';
 451→        }
 452→      else if (ch >= 0x20)
 453→        {
 454→          out[o++] = (char)ch;
 455→        }
 456→    }
 457→  out[o] = '\0';
 458→  return (int)o;
 459→}
