1362→
1363→int dm_voice_play_file(const char *wav_path)
1364→{
1365→  struct voice_file_job_s *job;
1366→  pthread_t th;
1367→  pthread_attr_t attr;
1368→  int ret;
1369→
1370→  if (!wav_path || !wav_path[0])
1371→    {
1372→      return -1;
1373→    }
1374→
1375→  job = malloc(sizeof(*job));
1376→  if (!job)
1377→    {
1378→      return -1;
1379→    }
1380→  snprintf(job->path, sizeof(job->path), "%s", wav_path);
1381→
1382→  pthread_attr_init(&attr);
1383→  pthread_attr_setstacksize(&attr, 16384);
1384→  ret = pthread_create(&th, &attr, play_file_worker, job);
1385→  pthread_attr_destroy(&attr);
1386→  if (ret != 0)
1387→    {
1388→      free(job);
1389→      return -1;
1390→    }
1391→
1392→  pthread_detach(th);
1393→  return 0;
1394→}
