390→void dm_chat_tick(void)
391→{
392→  /* apply worker results on LVGL thread */
393→  if (s_out_ready)
394→    {
395→      s_out_ready = 0;
396→      if (s_out_ans[0])
397→        {
398→          set_ans(s_out_ans);
399→        }
400→      if (s_out_sub[0])
401→        {
402→          set_sub(s_out_sub);
403→        }
404→      dm_face_set(FACE_HAPPY, EYE_DECOR_NONE, 8);
405→      reset_to_idle();
406→    }
407→
408→  if (s_ui_rec && !s_busy)
409→    {
410→      char buf[80];
411→      uint64_t now_ms = chat_monotonic_ms();
412→      if (s_rec_started_ms != 0 && now_ms >= s_rec_started_ms)
413→        {
414→          s_rec_sec = (int)((now_ms - s_rec_started_ms) / 1000);
415→        }
416→      if (dm_voice_rec_active())
417→        {
418→          snprintf(buf, sizeof(buf),
419→                   dm_t("● 录音中 %d 秒 · 再点一下结束并发送",
420→                        "● Recording %ds · tap again to send"),
421→                   s_rec_sec);
422→          set_ans(buf);
423→          set_sub((s_rec_sec & 1) ? dm_t("正在听…", "Listening…")
424→                                  : dm_t("对准麦克风说话", "Speak to the mic"));
425→        }
426→      else
427→        {
428→          s_ui_rec = false;
429→          if (s_rec_sec < 2)
430→            {
431→              s_mic_err = 1;
432→              set_ans(dm_t("麦克风故障，无法录音", "Mic failed"));
433→              set_sub(dm_t("检查 /dev/audio/pcm0c", "Check mic device"));
434→              reset_to_idle();
435→            }
436→          else
437→            {
438→              /* Recording auto-stop reached the configured limit.  Send the
439→               * captured WAV instead of silently discarding it. */
440→              kick_job(1);
441→            }
442→        }
443→    }
444→}
