289→/* emit {"role":..,"content":..}, entries (each with trailing comma) */
290→int dm_chat_hist_json(char *out, int cap)
291→{
292→  char esc[HIST_LINE * 2];
293→  int o = 0;
294→  int i;
295→
296→  if (!out || cap < 2)
297→    {
298→      return -1;
299→    }
300→  out[0] = '\0';
301→  for (i = 0; i < s_hist_n; i++)
302→    {
303→      int n;
304→
305→      if (s_hist[i].user[0])
306→        {
307→          json_escape(s_hist[i].user, esc, sizeof(esc));
308→          n = snprintf(out + o, (size_t)(cap - o),
309→                       "{\"role\":\"user\",\"content\":\"%s\"},", esc);
310→          if (n < 0 || n >= cap - o)
311→            {
312→              out[o] = '\0';
313→              return -1;
314→            }
315→          o += n;
316→        }
317→      if (s_hist[i].bot[0])
318→        {
319→          json_escape(s_hist[i].bot, esc, sizeof(esc));
320→          n = snprintf(out + o, (size_t)(cap - o),
321→                       "{\"role\":\"assistant\",\"content\":\"%s\"},", esc);
322→          if (n < 0 || n >= cap - o)
323→            {
324→              out[o] = '\0';
325→              return -1;
326→            }
327→          o += n;
328→        }
329→    }
330→  return o;
331→}
