415→const char *dm_chat_ai_ask(const char *user_text)
416→{
417→  char esc[400];
418→  char persona[1024];
419→  char hist[1400];
420→  char body[2400];
421→  char cmd[1200];
422→  const char *persona_src;
423→  FILE *f;
424→  int n;
425→
426→  s_last_reply[0] = '\0';
427→  s_last_request_remote_ok = 0;
428→  if (!user_text || !user_text[0])
429→    {
430→      return local_reply("");
431→    }
432→
433→  if (!dm_wifi_connected())
434→    {
435→      strncpy(s_last_reply, local_reply(user_text), sizeof(s_last_reply) - 1);
436→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
437→      return s_last_reply;
438→    }
439→
440→  /* Do not send HTTPS while the board clock is still at its boot epoch;
441→   * this causes mbedTLS to reject valid certificates as not-yet-valid. */
442→  if (dm_wifi_wait_time_sync(40) != 0)
443→    {
444→      syslog(LOG_WARNING, "[dm-chat] system clock not synchronized\n");
445→      strncpy(s_last_reply, local_reply(user_text), sizeof(s_last_reply) - 1);
446→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
447→      return s_last_reply;
448→    }
449→
450→  if (json_escape(user_text, esc, sizeof(esc)) < 0)
451→    {
452→      return local_reply(user_text);
453→    }
454→
455→  persona_src = s_persona_ctx[0] ? s_persona_ctx
456→                                 : "你是openvela小助手，桌边陪伴助手，回答简洁温暖，不超过80字，用中文。";
457→  if (json_escape(persona_src, persona, sizeof(persona)) < 0)
458→    {
459→      return local_reply(user_text);
460→    }
461→
462→  dm_chat_hist_json(hist, sizeof(hist));
463→  n = snprintf(body, sizeof(body),
464→               "{\"model\":\"%s\",\"messages\":["
465→               "{\"role\":\"system\",\"content\":\"%s\"},"
466→               "%s"
467→               "{\"role\":\"user\",\"content\":\"%s\"}],"
468→               "\"max_completion_tokens\":400,\"thinking\":{\"type\":\"disabled\"}}",
469→               MIMO_MODEL, persona, hist, esc);
470→  if (n <= 0 || n >= (int)sizeof(body))
471→    {
472→      return local_reply(user_text);
473→    }
474→
475→  f = fopen(CHAT_REQ_PATH, "w");
476→  if (!f)
477→    {
478→      return local_reply(user_text);
479→    }
480→  fwrite(body, 1, (size_t)n, f);
481→  fclose(f);
482→
483→  unlink(CHAT_RSP_PATH);
484→  /* Use the device-supported short options and reject HTTP error codes. */
485→  snprintf(cmd, sizeof(cmd),
486→           "curl -K " MIMO_CURL_CONFIG " -s -S -f -m 20 -X POST %s/chat/completions "
487→           "-H 'Content-Type: application/json' "
488→           "-d @%s -o %s",
489→           MIMO_BASE, CHAT_REQ_PATH, CHAT_RSP_PATH);
490→  if (run_curl_script(cmd) != 0)
491→    {
492→      strncpy(s_last_reply, local_reply(user_text),
493→              sizeof(s_last_reply) - 1);
494→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
495→      return s_last_reply;
496→    }
497→
498→  extract_content(CHAT_RSP_PATH, s_last_reply, sizeof(s_last_reply));
499→  if (s_last_reply[0])
500→    {
501→      s_last_request_remote_ok = 1;
502→      dm_chat_hist_push(user_text, s_last_reply);
503→    }
504→  else
505→    {
506→      strncpy(s_last_reply, local_reply(user_text),
507→              sizeof(s_last_reply) - 1);
508→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
509→    }
510→  return s_last_reply;
511→}
