 114→int dm_voice_rec_start(int max_seconds)
 115→{
 116→  pthread_t th;
 117→  pthread_attr_t attr;
 118→
 119→  pthread_mutex_lock(&s_rec_lock);
 120→  if (s_rec_active)
 121→    {
 122→      pthread_mutex_unlock(&s_rec_lock);
 123→      return 0;
 124→    }
 125→
 126→  /* Do not contend for the audio DMA while playback is active.  Use
 127→   * trylock so a UI click never waits behind a long speaker operation. */
 128→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 129→    {
 130→      pthread_mutex_unlock(&s_rec_lock);
 131→      return -EBUSY;
 132→    }
 133→
 134→  unlink(WAV_REC);
 135→  s_rec = nxrecorder_create();
 136→  if (!s_rec)
 137→    {
 138→      pthread_mutex_unlock(&s_audio_lock);
 139→      pthread_mutex_unlock(&s_rec_lock);
 140→      s_st = DM_VOICE_ERR;
 141→      return -1;
 142→    }
 143→  {
 144→    int ret = nxrecorder_setdevice(s_rec, "/dev/audio/pcm0c");
 145→    if (ret != OK)
 146→      {
 147→        syslog(LOG_ERR, "[dm-voice] set microphone device failed: %d\n", ret);
 148→        nxrecorder_release(s_rec);
 149→        s_rec = NULL;
 150→        pthread_mutex_unlock(&s_audio_lock);
 151→        pthread_mutex_unlock(&s_rec_lock);
 152→        s_st = DM_VOICE_ERR;
 153→        return ret;
 154→      }
 155→
 156→    ret = nxrecorder_recordinternal(s_rec, WAV_REC, AUDIO_FMT_PCM,
 157→                                    REC_CH, REC_BITS, REC_RATE, 1);
 158→    if (ret != OK)
 159→      {
 160→        syslog(LOG_ERR,
 161→               "[dm-voice] recorder start failed: %d (rate=%d ch=%d bits=%d)\n",
 162→               ret, REC_RATE, REC_CH, REC_BITS);
 163→        nxrecorder_release(s_rec);
 164→        s_rec = NULL;
 165→        pthread_mutex_unlock(&s_audio_lock);
 166→        pthread_mutex_unlock(&s_rec_lock);
 167→        s_st = DM_VOICE_ERR;
 168→        return ret;
 169→      }
 170→  }
 171→
 172→  s_rec_active = 1;
 173→  s_st = DM_VOICE_REC;
 174→  pthread_mutex_unlock(&s_audio_lock);
 175→  pthread_mutex_unlock(&s_rec_lock);
 176→
 177→  pthread_attr_init(&attr);
 178→  pthread_attr_setstacksize(&attr, 4096);
 179→  if (pthread_create(&th, &attr, rec_auto_stop,
 180→                     (void *)(intptr_t)(max_seconds > 0 ? max_seconds
 181→                                                        : REC_MAX_SEC)) == 0)
 182→    {
 183→      pthread_detach(th);
 184→    }
 185→  pthread_attr_destroy(&attr);
 186→  return 0;
 187→}
