 189→int dm_voice_rec_stop(void)
 190→{
 191→  FILE *f;
 192→  long size;
 193→
 194→  pthread_mutex_lock(&s_rec_lock);
 195→  if (s_rec_active)
 196→    {
 197→      /* Stop/join can wait for the NuttX audio worker.  Keep this off the
 198→       * LVGL event thread and hold the audio gate until the recorder releases
 199→       * its DMA/session resources. */
 200→      pthread_mutex_lock(&s_audio_lock);
 201→      if (s_rec)
 202→        {
 203→          nxrecorder_stop(s_rec);
 204→          nxrecorder_release(s_rec);
 205→          s_rec = NULL;
 206→        }
 207→      s_rec_active = 0;
 208→      s_st = DM_VOICE_IDLE;
 209→      pthread_mutex_unlock(&s_audio_lock);
 210→    }
 211→  pthread_mutex_unlock(&s_rec_lock);
 212→
 213→  f = fopen(WAV_REC, "rb");
 214→  if (!f)
 215→    {
 216→      syslog(LOG_ERR, "[dm-voice] recording file missing\n");
 217→      s_st = DM_VOICE_ERR;
 218→      return -1;
 219→    }
 220→
 221→  if (fseek(f, 0, SEEK_END) != 0)
 222→    {
 223→      fclose(f);
 224→      s_st = DM_VOICE_ERR;
 225→      return -1;
 226→    }
 227→
 228→  size = ftell(f);
 229→  fclose(f);
 230→  if (size <= 44)
 231→    {
 232→      syslog(LOG_ERR, "[dm-voice] recording has no audio payload (bytes=%ld)\n",
 233→             size);
 234→      s_st = DM_VOICE_ERR;
 235→      return -1;
 236→    }
 237→
 238→  /* nxrecorder writes raw PCM for AUDIO_FMT_PCM; report only sizes/format
 239→   * metadata so we can distinguish a capture failure from an API failure. */
 240→  syslog(LOG_INFO, "[dm-voice] captured PCM bytes=%ld rate=%d ch=%d bits=%d\n",
 241→         size, REC_RATE, REC_CH, REC_BITS);
 242→  return 0;
 243→}
