 247→/* ---- player: nxplayer (buffer-queue API) ---- */
 248→
 249→/* The audio driver owns a small number of DMA channels.  Serialize all
 250→ * playback and recording setup/teardown so the app never starts a new stream
 251→ * while an earlier stream is still releasing its buffers. */
 252→
 253→/* nxplayer treats .wav as raw PCM and never reads the WAV header
 254→ * (its PCM ops->pre_parse is NULL), so the fmt chunk is parsed here and
 255→ * the payload is fed via nxplayer_playraw() with explicit parameters. */
 256→static int play_wav(const char *path)
 257→{
 258→  const char *src = (path && path[0]) ? path : WAV_TTS;
 259→  struct nxplayer_s *p = NULL;
 260→  FILE *f = NULL;
 261→  FILE *o = NULL;
 262→  uint8_t hdr[44];
 263→  char buf[1024];
 264→  size_t n;
 265→  size_t raw_len = 0;
 266→  uint32_t rate;
 267→  uint16_t ch;
 268→  uint16_t bits;
 269→  uint64_t bytes_per_sec;
 270→  uint64_t play_ms;
 271→  int rc = -1;
 272→
 273→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 274→    {
 275→      return -EBUSY;
 276→    }
 277→  if (s_rec_active)
 278→    {
 279→      pthread_mutex_unlock(&s_audio_lock);
 280→      return -EBUSY;
 281→    }
 282→
 283→  p = nxplayer_create();
 284→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
 285→    {
 286→      goto out;
 287→    }
 288→
 289→  f = fopen(src, "rb");
 290→  if (!f)
 291→    {
 292→      goto out;
 293→    }
 294→  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
 295→    {
 296→      goto out;
 297→    }
 298→  ch = (uint16_t)(hdr[22] | (hdr[23] << 8));
 299→  rate = (uint32_t)(hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) |
 300→                    ((uint32_t)hdr[27] << 24));
 301→  bits = (uint16_t)(hdr[34] | (hdr[35] << 8));
 302→  if (rate < 8000 || rate > 48000)
 303→    {
 304→      rate = 24000;
 305→    }
 306→  if (ch < 1 || ch > 2)
 307→    {
 308→      ch = 1;
 309→    }
 310→  if (bits != 8 && bits != 16)
 311→    {
 312→      bits = 16;
 313→    }
 314→
 315→  o = fopen(PCM_RAW, "wb");
 316→  if (!o)
 317→    {
 318→      goto out;
 319→    }
 320→  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
 321→    {
 322→      if (fwrite(buf, 1, n, o) != n)
 323→        {
 324→          goto out;
 325→        }
 326→      raw_len += n;
 327→    }
 328→  if (ferror(f) || raw_len == 0)
 329→    {
 330→      goto out;
 331→    }
 332→  fclose(o);
 333→  o = NULL;
 334→  fclose(f);
 335→  f = NULL;
 336→
 337→  if (nxplayer_playraw(p, PCM_RAW, AUDIO_FMT_PCM, 0, (uint8_t)ch,
 338→                       (uint8_t)bits, rate, 1) != OK)
 339→    {
 340→      goto out;
 341→    }
 342→
 343→  /* nxplayer_playraw() returns as soon as its worker is started.  Keep the
 344→   * audio gate until the PCM duration elapses and stop/join the worker, so a
 345→   * following capture/playback cannot race the previous DMA release. */
 346→  bytes_per_sec = (uint64_t)rate * ch * bits / 8;
 347→  play_ms = bytes_per_sec ? ((uint64_t)raw_len * 1000 / bytes_per_sec) : 1000;
 348→  play_ms += 150;
 349→  if (play_ms > 30000)
 350→    {
 351→      play_ms = 30000;
 352→    }
 353→  while (play_ms >= 1000)
 354→    {
 355→      sleep(1);
 356→      play_ms -= 1000;
 357→    }
 358→  if (play_ms > 0)
 359→    {
 360→      usleep((useconds_t)(play_ms * 1000));
 361→    }
 362→
 363→  (void)nxplayer_stop(p);
 364→  rc = 0;
 365→
 366→out:
 367→  if (o)
 368→    {
 369→      fclose(o);
 370→    }
 371→  if (f)
 372→    {
 373→      fclose(f);
 374→    }
 375→  if (p)
 376→    {
 377→      nxplayer_release(p);
 378→    }
 379→  pthread_mutex_unlock(&s_audio_lock);
 380→  return rc;
 381→}
