 537→/* Curl reads a short-lived, owner-only config file. The shell script itself
 538→ * never contains the key and does not depend on NSH command substitution. */
 539→static int run_curl_script(const char *line)
 540→{
 541→  char key[128];
 542→  FILE *kf;
 543→  FILE *sf;
 544→  int key_write_ok;
 545→  int key_close_rc;
 546→  int script_write_ok;
 547→  int script_close_rc;
 548→  int rc;
 549→
 550→  if (!voice_key_load(key, sizeof(key)))
 551→    {
 552→      s_last_failure = DM_VOICE_FAILURE_API_KEY;
 553→      syslog(LOG_ERR, "[dm-voice] runtime API key missing or invalid\n");
 554→      return -1;
 555→    }
 556→
 557→  kf = fopen(MIMO_CURL_CONFIG, "w");
 558→  if (!kf || chmod(MIMO_CURL_CONFIG, S_IRUSR | S_IWUSR) != 0)
 559→    {
 560→      if (kf)
 561→        {
 562→          fclose(kf);
 563→        }
 564→      memset(key, 0, sizeof(key));
 565→      unlink(MIMO_CURL_CONFIG);
 566→      return -1;
 567→    }
 568→  key_write_ok = fprintf(kf, "header = \"Authorization: Bearer %s\"\n",
 569→                         key) > 0;
 570→  key_close_rc = fclose(kf);
 571→  memset(key, 0, sizeof(key));
 572→  if (!key_write_ok || key_close_rc != 0)
 573→    {
 574→      unlink(MIMO_CURL_CONFIG);
 575→      return -1;
 576→    }
 577→
 578→  sf = fopen(VOICE_CURL_SCRIPT, "w");
 579→  if (!sf)
 580→    {
 581→      unlink(MIMO_CURL_CONFIG);
 582→      syslog(LOG_ERR, "[dm-voice] cannot create curl script\n");
 583→      return -1;
 584→    }
 585→
 586→  script_write_ok = fputs("#!/bin/sh\n", sf) != EOF &&
 587→                    fputs(line, sf) != EOF && fputc('\n', sf) != EOF;
 588→  script_close_rc = fclose(sf);
 589→  if (!script_write_ok || script_close_rc != 0)
 590→    {
 591→      unlink(MIMO_CURL_CONFIG);
 592→      syslog(LOG_ERR, "[dm-voice] cannot write curl script\n");
 593→      return -1;
 594→    }
 595→
 596→  rc = system("sh " VOICE_CURL_SCRIPT);
 597→  unlink(MIMO_CURL_CONFIG);
 598→  if (rc != 0)
 599→    {
 600→      syslog(LOG_ERR, "[dm-voice] curl script failed status=%d\n", rc);
 601→      return -1;
 602→    }
 603→  return 0;
 604→}
