 607→static const char b64tab[] =
 608→    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
 609→
 610→static int b64_encode(const unsigned char *in, size_t inlen, char *out,
 611→                      size_t outcap)
 612→{
 613→  size_t i = 0;
 614→  size_t o = 0;
 615→
 616→  if (!in || !out || outcap < 2 || inlen > (outcap - 1) / 4 * 3)
 617→    {
 618→      return -1;
 619→    }
 620→
 621→  while (i < inlen)
 622→    {
 623→      size_t remain = inlen - i;
 624→      unsigned int v = (unsigned int)in[i++] << 16;
 625→      if (remain > 1)
 626→        {
 627→          v |= (unsigned int)in[i++] << 8;
 628→        }
 629→      if (remain > 2)
 630→        {
 631→          v |= (unsigned int)in[i++];
 632→        }
 633→      out[o++] = b64tab[(v >> 18) & 63];
 634→      out[o++] = b64tab[(v >> 12) & 63];
 635→      out[o++] = remain > 1 ? b64tab[(v >> 6) & 63] : '=';
 636→      out[o++] = remain > 2 ? b64tab[v & 63] : '=';
 637→    }
 638→  out[o] = '\0';
 639→  return (int)o;
 640→}
 641→
 642→static int b64_decode(const char *in, unsigned char *out, size_t outcap)
 643→{
 644→  const char *p;
 645→  unsigned int val = 0;
 646→  int bits = 0;
 647→  size_t o = 0;
 648→  size_t symbols = 0;
 649→  size_t padding = 0;
 650→  int ended = 0;
 651→
 652→  if (!in || !out)
 653→    {
 654→      return -1;
 655→    }
 656→
 657→  /* Some compatible gateways return a data URL instead of bare Base64. */
 658→  if (strncmp(in, "data:", 5) == 0)
 659→    {
 660→      const char *comma = strchr(in, ',');
 661→      const char *base64 = strstr(in, ";base64");
 662→      if (!comma || !base64 || base64 > comma)
 663→        {
 664→          return -1;
 665→        }
 666→      in = comma + 1;
 667→    }
 668→
 669→  for (; *in; in++)
 670→    {
 671→      unsigned char ch = (unsigned char)*in;
 672→      if (ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n')
 673→        {
 674→          continue;
 675→        }
 676→      if (ch == '=')
 677→        {
 678→          ended = 1;
 679→          padding++;
 680→          if (padding > 2)
 681→            {
 682→              return -1;
 683→            }
 684→          continue;
 685→        }
 686→      if (ended)
 687→        {
 688→          return -1;
 689→        }
 690→
 691→      p = strchr(b64tab, ch);
 692→      if (!p)
 693→        {
 694→          return -1;
 695→        }
 696→      symbols++;
 697→      val = (val << 6) | (unsigned int)(p - b64tab);
 698→      bits += 6;
 699→      if (bits >= 8)
 700→        {
 701→          bits -= 8;
 702→          if (o >= outcap)
 703→            {
 704→              return -1;
 705→            }
 706→          out[o++] = (unsigned char)((val >> bits) & 0xff);
 707→          val &= bits ? ((1u << bits) - 1u) : 0u;
 708→        }
 709→    }
 710→
 711→  if (symbols == 0 || symbols % 4 == 1 ||
 712→      (padding == 1 && symbols % 4 != 3) ||
 713→      (padding == 2 && symbols % 4 != 2) ||
 714→      (padding > 0 && (symbols + padding) % 4 != 0) ||
 715→      (bits != 0 && bits != 2 && bits != 4) || val != 0)
 716→    {
 717→      return -1;
 718→    }
 719→  return (int)o;
 720→}
 721→
 722→static int http_post_json(const char *path, const char *json_body,
 723→                          const char *out_path)
 724→{
 725→  char cmd[1400];
 726→  FILE *f;
 727→  size_t body_len;
 728→  int write_ok;
 729→  int close_rc;
 730→  int rc;
 731→
 732→  if (!dm_wifi_connected())
 733→    {
 734→      s_last_failure = DM_VOICE_FAILURE_CHAT;
 735→      return -1;
 736→    }
 737→  if (dm_wifi_wait_time_sync(40) != 0)
 738→    {
 739→      s_last_failure = DM_VOICE_FAILURE_TIME;
 740→      syslog(LOG_WARNING, "[dm-voice] secure request deferred: clock not ready\n");
 741→      return -1;
 742→    }
 743→
 744→  f = fopen(JSON_REQ, "w");
 745→  if (!f)
 746→    {
 747→      s_last_failure = DM_VOICE_FAILURE_CHAT;
 748→      return -1;
 749→    }
 750→  body_len = strlen(json_body);
 751→  write_ok = fwrite(json_body, 1, body_len, f) == body_len;
 752→  close_rc = fclose(f);
 753→  if (!write_ok || close_rc != 0)
 754→    {
 755→      s_last_failure = DM_VOICE_FAILURE_CHAT;
 756→      return -1;
 757→    }
 758→  unlink(out_path);
 759→  /* Use short curl options supported by the board build.  The runtime key is
 760→   * expanded by the shell and is not written into this script. */
 761→  snprintf(cmd, sizeof(cmd),
 762→           "curl -K " MIMO_CURL_CONFIG " "
 763→           "--cacert /resource/etc/ssl/curl/ca-certificates.crt "
 764→           "-s -S -f -m 25 -w 'HTTP_STATUS:%{http_code}\\n' "
 765→           "-X POST %s%s -H 'Content-Type: application/json' "
 766→           "-d @%s -o %s",
 767→           VOICE_BASE, path, JSON_REQ, out_path);
 768→  rc = run_curl_script(cmd);
 769→  if (rc != 0 && s_last_failure == DM_VOICE_FAILURE_NONE)
 770→    {
 771→      s_last_failure = DM_VOICE_FAILURE_CHAT;
 772→    }
 773→  return rc;
 774→}
