 776→static cJSON *voice_json_load(const char *path, long max_size)
 777→{
 778→  FILE *f;
 779→  char *buf;
 780→  long size;
 781→  cJSON *root;
 782→
 783→  f = fopen(path, "rb");
 784→  if (!f)
 785→    {
 786→      return NULL;
 787→    }
 788→  if (fseek(f, 0, SEEK_END) != 0 || (size = ftell(f)) <= 0 ||
 789→      size > max_size || fseek(f, 0, SEEK_SET) != 0)
 790→    {
 791→      fclose(f);
 792→      return NULL;
 793→    }
 794→  buf = malloc((size_t)size + 1);
 795→  if (!buf)
 796→    {
 797→      fclose(f);
 798→      return NULL;
 799→    }
 800→  if (fread(buf, 1, (size_t)size, f) != (size_t)size)
 801→    {
 802→      free(buf);
 803→      fclose(f);
 804→      return NULL;
 805→    }
 806→  fclose(f);
 807→  buf[size] = '\0';
 808→  root = cJSON_Parse(buf);
 809→  free(buf);
 810→  return root;
 811→}
