1113→static int tts_synth(const char *text, const char *wav_path,
1114→                     const char *voice_id)
1115→{
1116→  char esc[400];
1117→  char voice_esc[64];
1118→  char body[1000];
1119→  unsigned char *raw = NULL;
1120→  FILE *f = NULL;
1121→  long sz;
1122→  int n;
1123→  int rawlen;
1124→  int write_ok;
1125→  int close_rc;
1126→  int rc = -1;
1127→  cJSON *root = NULL;
1128→  cJSON *message;
1129→  cJSON *audio;
1130→  cJSON *data;
1131→
1132→  if (!text || !text[0] || !wav_path || !voice_id || !voice_id[0])
1133→    {
1134→      return -1;
1135→    }
1136→  if (json_escape(text, esc, sizeof(esc)) < 0 ||
1137→      json_escape(voice_id, voice_esc, sizeof(voice_esc)) < 0)
1138→    {
1139→      return -1;
1140→    }
1141→  n = snprintf(body, sizeof(body),
1142→               "{\"model\":\"%s\",\"messages\":["
1143→               "{\"role\":\"user\",\"content\":\"请使用指定音色，以自然清晰的语气朗读。\"},"
1144→               "{\"role\":\"assistant\",\"content\":\"%s\"}],"
1145→               "\"audio\":{\"format\":\"wav\",\"voice\":\"%s\"}}",
1146→               TTS_MODEL, esc, voice_esc);
1147→  if (n <= 0 || n >= (int)sizeof(body))
1148→    {
1149→      return -1;
1150→    }
1151→  syslog(LOG_INFO, "[dm-voice] TTS request start\n");
1152→  if (http_post_json("/chat/completions", body, TXT_CHAT) != 0)
1153→    {
1154→      syslog(LOG_ERR, "[dm-voice] TTS HTTP request failed\n");
1155→      return -1;
1156→    }
1157→
1158→  root = voice_json_load(TXT_CHAT, 4 * 1024 * 1024);
1159→  if (!root)
1160→    {
1161→      goto out;
1162→    }
1163→  message = voice_first_message(root);
1164→  audio = message ? cJSON_GetObjectItem(message, "audio") : NULL;
1165→  data = audio ? cJSON_GetObjectItem(audio, "data") : NULL;
1166→  if (!data || !cJSON_IsString(data) || !data->valuestring)
1167→    {
1168→      goto out;
1169→    }
1170→
1171→  sz = (long)strlen(data->valuestring);
1172→  if (sz <= 0 || sz > 4 * 1024 * 1024)
1173→    {
1174→      goto out;
1175→    }
1176→  raw = malloc((size_t)sz);
1177→  if (!raw)
1178→    {
1179→      goto out;
1180→    }
1181→  rawlen = b64_decode(data->valuestring, raw, (size_t)sz);
1182→  if (rawlen < 44 || memcmp(raw, "RIFF", 4) != 0 ||
1183→      memcmp(raw + 8, "WAVE", 4) != 0)
1184→    {
1185→      goto out;
1186→    }
1187→
1188→  f = fopen(wav_path, "wb");
1189→  if (!f)
1190→    {
1191→      goto out;
1192→    }
1193→  write_ok = fwrite(raw, 1, (size_t)rawlen, f) == (size_t)rawlen;
1194→  close_rc = fclose(f);
1195→  f = NULL;
1196→  if (write_ok && close_rc == 0)
1197→    {
1198→      rc = 0;
1199→      syslog(LOG_INFO, "[dm-voice] TTS WAV decoded bytes=%d\n", rawlen);
1200→    }
1201→
1202→out:
1203→  if (f)
1204→    {
1205→      fclose(f);
1206→    }
1207→  free(raw);
1208→  if (root)
1209→    {
1210→      cJSON_Delete(root);
1211→    }
1212→  if (rc != 0)
1213→    {
1214→      syslog(LOG_ERR, "[dm-voice] TTS response missing/invalid WAV data\n");
1215→      unlink(wav_path);
1216→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1217→        {
1218→          s_last_failure = DM_VOICE_FAILURE_TTS;
1219→        }
1220→    }
1221→  return rc;
1222→}
