1458→    }
1459→  snprintf(path, sizeof(path), WAV_VOL_TEST_FMT, profile_idx);
1460→  s_last_failure = DM_VOICE_FAILURE_NONE;
1461→  if (!voice_wav_cache_valid(path))
1462→    {
1463→      unlink(path);
1464→      if (tts_synth(sample_text, path, dm_voice_profile_api_id()) != 0 ||
1465→          !voice_wav_cache_valid(path))
1466→        {
1467→          int rc;
1468→          if (s_last_failure == DM_VOICE_FAILURE_NONE)
1469→            {
1470→              s_last_failure = DM_VOICE_FAILURE_TTS;
1471→            }
1472→          syslog(LOG_WARNING,
1473→                 "[dm-voice] cloud volume sample unavailable; using tone\n");
1474→          rc = dm_voice_beep();
1475→          return rc == 0 ? 1 : -1;
1476→        }
1477→    }
1478→
1479→  if (play_wav(path) == 0)
1480→    {
1481→      return 0;
1482→    }
1483→  return dm_voice_beep() == 0 ? 1 : -1;
1484→}
