  1→/*
  2→ * dm_ui_chat.c — tap-to-talk voice chat
  3→ * Rule: only the LVGL thread may touch widgets.
  4→ * Worker writes results into s_out_* ; dm_chat_tick() applies them.
  5→ */
  6→
  7→#include "deskmate.h"
  8→#include "dm_voice.h"
