342→
343→static lv_obj_t *s_draw_cv;
344→static lv_color_t *s_draw_buf;
345→static int s_draw_w = 2;
346→static uint32_t s_draw_col = 0x7DD3FC;
347→static bool s_draw_down;
348→static lv_point_t s_draw_last;
349→
350→static void draw_clear_buf(void)
351→{
352→  if (!s_draw_buf)
353→    {
354→      return;
355→    }
356→  lv_canvas_fill_bg(s_draw_cv, lv_color_hex(0x0a0a0a), LV_OPA_COVER);
357→}
358→
359→static void draw_dot(int x, int y)
360→{
361→  int dx;
362→  int dy;
363→  int r = s_draw_w;
364→  if (!s_draw_cv || !s_draw_buf)
365→    {
366→      return;
367→    }
368→  if (x < 0 || y < 0 || x >= DRAW_W || y >= DRAW_H)
369→    {
370→      return;
371→    }
372→  for (dy = -r; dy <= r; dy++)
373→    {
374→      for (dx = -r; dx <= r; dx++)
375→        {
376→          int px = x + dx;
377→          int py = y + dy;
378→          if (px < 0 || py < 0 || px >= DRAW_W || py >= DRAW_H)
379→            {
380→              continue;
381→            }
382→          if (dx * dx + dy * dy <= r * r + 1)
383→            {
384→              lv_canvas_set_px(s_draw_cv, px, py, lv_color_hex(s_draw_col),
385→                               LV_OPA_COVER);
386→            }
387→        }
388→    }
389→}
390→
391→static void draw_line(int x0, int y0, int x1, int y1)
392→{
393→  int dx = abs(x1 - x0);
394→  int dy = abs(y1 - y0);
395→  int sx = x0 < x1 ? 1 : -1;
396→  int sy = y0 < y1 ? 1 : -1;
397→  int err = dx - dy;
398→  for (;;)
399→    {
400→      draw_dot(x0, y0);
401→      if (x0 == x1 && y0 == y1)
402→        {
403→          break;
404→        }
405→      {
406→        int e2 = 2 * err;
407→        if (e2 > -dy)
408→          {
409→            err -= dy;
410→            x0 += sx;
411→          }
412→        if (e2 < dx)
413→          {
414→            err += dx;
415→            y0 += sy;
416→          }
417→        }
418→    }
419→}
