535→static void bmi_paint(void)
536→{
537→  char buf[16];
538→  double m = s_bmi_h / 100.0;
539→  double bmi = s_bmi_w / (m * m);
540→  const char *tag = "正常";
541→  uint32_t c = C_OK;
542→
543→  if (bmi < 18.5)
544→    {
545→      tag = "偏瘦";
546→      c = C_ACCENT;
547→    }
548→  else if (bmi < 24.0)
549→    {
550→      tag = "正常";
551→      c = C_OK;
552→    }
553→  else if (bmi < 28.0)
554→    {
555→      tag = "偏胖";
556→      c = C_STAR;
557→    }
558→  else
559→    {
560→      tag = "肥胖";
561→      c = 0xFF6B8A;
562→    }
563→
564→  snprintf(buf, sizeof(buf), "%.1f", bmi);
565→  if (s_bmi_val)
566→    {
567→      lv_label_set_text(s_bmi_val, buf);
568→    }
569→  if (s_bmi_tag)
570→    {
571→      lv_label_set_text(s_bmi_tag, tag);
572→      lv_obj_set_style_text_color(s_bmi_tag, lv_color_hex(c), LV_PART_MAIN);
573→    }
574→  snprintf(buf, sizeof(buf), "%d cm", s_bmi_h);
575→  if (s_bmi_h_l)
576→    {
577→      lv_label_set_text(s_bmi_h_l, buf);
578→    }
579→  snprintf(buf, sizeof(buf), "%d kg", s_bmi_w);
580→  if (s_bmi_w_l)
581→    {
582→      lv_label_set_text(s_bmi_w_l, buf);
583→    }
584→}
