/*
 * dm_ui_recorder.c — standalone persistent voice recorder page
 * All recorder, file-save and playback operations run outside the LVGL thread.
 */

#include "deskmate.h"
#include "dm_voice.h"

#ifdef CONFIG_DESKMATE_APP

#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <pthread.h>
#include <time.h>
#include <errno.h>

#define RECORDER_MAX_SEC 60

typedef enum
{
  REC_JOB_NONE = 0,
  REC_JOB_START,
  REC_JOB_STOP_SAVE,
  REC_JOB_PLAY
} recorder_job_t;

static lv_obj_t *s_page;
static lv_obj_t *s_status;
static lv_obj_t *s_elapsed;
static lv_obj_t *s_record_btn;
static lv_obj_t *s_play_btn;
static volatile int s_busy;
static volatile int s_job_done;
static volatile int s_job_result;
static volatile recorder_job_t s_job;
static volatile int s_recording;
static int s_has_saved;
static uint64_t s_record_started_ms;

static uint64_t recorder_monotonic_ms(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return 0;
    }
  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
}

static int recorder_saved_file_exists(void)
{
  FILE *f = fopen(DM_VOICE_RECORD_PATH, "rb");
  unsigned char hdr[12];
  int valid = 0;

  if (!f)
    {
      return 0;
    }
  if (fread(hdr, 1, sizeof(hdr), f) == sizeof(hdr) &&
      memcmp(hdr, "RIFF", 4) == 0 && memcmp(hdr + 8, "WAVE", 4) == 0)
    {
      valid = 1;
    }
  fclose(f);
  return valid;
}

static void recorder_refresh(void)
{
  const char *record_text;
  lv_obj_t *label;

  if (!s_record_btn || !s_play_btn)
    {
      return;
    }

  if (s_busy)
    {
      if (s_job == REC_JOB_START)
        {
          record_text = dm_t("准备录音…", "Starting…");
        }
      else if (s_job == REC_JOB_STOP_SAVE)
        {
          record_text = dm_t("正在保存…", "Saving…");
        }
      else
        {
          record_text = dm_t("录音机忙…", "Recorder busy…");
        }
    }
  else if (s_recording)
    {
      record_text = dm_t("停止并保存", "Stop & save");
    }
  else
    {
      record_text = dm_t("开始录音", "Start recording");
    }

  label = lv_obj_get_child(s_record_btn, 0);
  if (label)
    {
      lv_label_set_text(label, record_text);
    }

  if (s_busy || s_recording || !s_has_saved)
    {
      lv_obj_add_state(s_play_btn, LV_STATE_DISABLED);
    }
  else
    {
      lv_obj_clear_state(s_play_btn, LV_STATE_DISABLED);
    }

  lv_obj_set_style_bg_color(s_record_btn,
                            lv_color_hex(s_recording ? C_HEART : MD_PRIMARY),
                            LV_PART_MAIN);
}

static void *recorder_worker(void *arg)
{
  recorder_job_t job = (recorder_job_t)(intptr_t)arg;
  int rc;

  switch (job)
    {
      case REC_JOB_START:
        rc = dm_voice_rec_start(RECORDER_MAX_SEC);
        break;

      case REC_JOB_STOP_SAVE:
        rc = dm_voice_rec_stop();
        if (rc == 0)
          {
            rc = dm_voice_record_save(DM_VOICE_RECORD_PATH);
          }
        break;

      case REC_JOB_PLAY:
        rc = dm_voice_play_file_sync(DM_VOICE_RECORD_PATH);
        break;

      default:
        rc = -EINVAL;
        break;
    }

  s_job_result = rc;
  s_job_done = 1;
  return NULL;
}

static int recorder_start_job(recorder_job_t job)
{
  pthread_t th;
  pthread_attr_t attr;
  int ret;

  if (s_busy)
    {
      return -EBUSY;
    }

  s_busy = 1;
  s_job = job;
  s_job_done = 0;
  recorder_refresh();

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 16384);
  ret = pthread_create(&th, &attr, recorder_worker, (void *)(intptr_t)job);
  pthread_attr_destroy(&attr);
  if (ret != 0)
    {
      s_busy = 0;
      s_job = REC_JOB_NONE;
      return -ret;
    }

  pthread_detach(th);
  return 0;
}

static void record_button_cb(lv_event_t *e)
{
  (void)e;

  if (s_busy)
    {
      return;
    }
  if (s_recording)
    {
      (void)recorder_start_job(REC_JOB_STOP_SAVE);
    }
  else
    {
      (void)recorder_start_job(REC_JOB_START);
    }
}

static void play_button_cb(lv_event_t *e)
{
  (void)e;

  if (s_busy || s_recording || !s_has_saved)
    {
      return;
    }
  (void)recorder_start_job(REC_JOB_PLAY);
}

static void back_button_cb(lv_event_t *e)
{
  (void)e;
  if (s_busy || s_recording)
    {
      if (s_status)
        {
          lv_label_set_text(s_status,
                            dm_t("请先停止并保存录音", "Stop and save first"));
        }
      return;
    }
  dm_show(PAGE_FEATURES);
}

void dm_create_recorder(void)
{
  lv_obj_t *title;
  lv_obj_t *back;

  s_page = lv_obj_create(g_dm_root);
  lv_obj_set_size(s_page, DM_SCR_W, DM_SCR_H);
  lv_obj_set_pos(s_page, 0, 0);
  lv_obj_set_style_bg_color(s_page, lv_color_hex(MD_SURFACE), LV_PART_MAIN);
  lv_obj_set_style_bg_opa(s_page, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(s_page, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(s_page, 0, LV_PART_MAIN);
  lv_obj_clear_flag(s_page, LV_OBJ_FLAG_SCROLLABLE);
  g_dm_pages[PAGE_RECORDER] = s_page;

  back = dm_btn(s_page, "←", "<", 36, 26, MD_SURFACE_HIGH, MD_ON_SURFACE,
                back_button_cb, NULL);
  lv_obj_set_pos(back, 8, 8);
  title = dm_lbl(s_page, "录音机", "Recorder", g_dm_font_m, MD_ON_SURFACE);
  lv_obj_set_pos(title, 54, 10);

  s_status = dm_lbl(s_page, "准备就绪", "Ready", g_dm_font_s,
                    MD_ON_SURFACE_VARIANT);
  lv_obj_set_width(s_status, 296);
  lv_obj_set_style_text_align(s_status, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
  lv_obj_set_pos(s_status, 12, 54);

  s_elapsed = dm_lbl(s_page, "最长 60 秒", "Up to 60 seconds",
                     g_dm_font_s, MD_ON_SURFACE_VARIANT);
  lv_obj_set_width(s_elapsed, 296);
  lv_obj_set_style_text_align(s_elapsed, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
  lv_obj_set_pos(s_elapsed, 12, 78);

  s_record_btn = dm_btn(s_page, "开始录音", "Start recording", 280, 42,
                        MD_PRIMARY, MD_ON_PRIMARY,
                        record_button_cb, NULL);
  lv_obj_set_pos(s_record_btn, 20, 108);

  s_play_btn = dm_btn(s_page, "播放最近录音", "Play saved recording",
                      280, 42, MD_SECONDARY_CONTAINER,
                      MD_ON_SECONDARY_CONT, play_button_cb, NULL);
  lv_obj_set_pos(s_play_btn, 20, 160);

  {
    lv_obj_t *hint = dm_lbl(s_page,
                            "保存到开发板 /data；新录音覆盖上一段",
                            "Saved on device; each take replaces the previous",
                            g_dm_font_s, MD_ON_SURFACE_VARIANT);
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, 296);
    lv_obj_set_style_text_align(hint, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
    lv_obj_set_pos(hint, 12, 210);
  }

  s_busy = 0;
  s_job_done = 0;
  s_job_result = 0;
  s_job = REC_JOB_NONE;
  s_recording = 0;
  s_record_started_ms = 0;
  s_has_saved = recorder_saved_file_exists();
  recorder_refresh();
}

void dm_recorder_tick(void)
{
  if (s_job_done)
    {
      recorder_job_t completed = s_job;
      int rc = s_job_result;

      s_job_done = 0;
      s_busy = 0;
      s_job = REC_JOB_NONE;

      if (completed == REC_JOB_START)
        {
          if (rc == 0)
            {
              s_recording = 1;
              s_record_started_ms = recorder_monotonic_ms();
              if (s_status)
                {
                  lv_label_set_text(s_status,
                                    dm_t("正在录音…结束后自动保存",
                                         "Recording… save when stopped"));
                }
            }
          else if (s_status)
            {
              lv_label_set_text(s_status,
                                dm_t("无法启动录音，请稍后重试",
                                     "Could not start recording"));
            }
        }
      else if (completed == REC_JOB_STOP_SAVE)
        {
          s_recording = 0;
          s_record_started_ms = 0;
          if (rc == 0)
            {
              s_has_saved = 1;
              if (s_status)
                {
                  lv_label_set_text(s_status,
                                    dm_t("录音已保存，可通过喇叭播放",
                                         "Saved; ready to play on speaker"));
                }
            }
          else if (s_status)
            {
              lv_label_set_text(s_status,
                                dm_t("录音保存失败，请重新录制",
                                     "Save failed; please record again"));
            }
        }
      else if (completed == REC_JOB_PLAY && s_status)
        {
          lv_label_set_text(s_status,
                            rc == 0
                              ? dm_t("正在喇叭播放录音", "Playing on speaker")
                              : dm_t("播放失败，请先录制一段", "Playback failed"));
        }
      recorder_refresh();
    }

  if (s_recording && !s_busy)
    {
      uint64_t now_ms = recorder_monotonic_ms();
      if (s_record_started_ms != 0 && now_ms >= s_record_started_ms)
        {
          char elapsed[48];
          unsigned int seconds =
              (unsigned int)((now_ms - s_record_started_ms) / 1000);
          snprintf(elapsed, sizeof(elapsed),
                   dm_t("已录 %u / %u 秒", "%u / %u sec"),
                   seconds, RECORDER_MAX_SEC);
          if (s_elapsed)
            {
              lv_label_set_text(s_elapsed, elapsed);
            }
        }

      /* nxrecorder has an automatic time limit. Save its completed capture
       * instead of leaving it in /tmp when the limit is reached. */
      if (!dm_voice_rec_active())
        {
          if (recorder_start_job(REC_JOB_STOP_SAVE) != 0 && s_status)
            {
              lv_label_set_text(s_status,
                                dm_t("自动结束，正在等待保存", "Stopped; retrying save"));
            }
        }
    }
}

#endif /* CONFIG_DESKMATE_APP */

