 43→static uint64_t recorder_monotonic_ms(void)
 44→{
 45→  struct timespec ts;
 46→
 47→  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
 48→    {
 49→      return 0;
 50→    }
 51→  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
 52→}
