127→static void *recorder_worker(void *arg)
128→{
129→  recorder_job_t job = (recorder_job_t)(intptr_t)arg;
130→  int rc;
131→
132→  switch (job)
133→    {
134→      case REC_JOB_START:
135→        rc = dm_voice_rec_start(RECORDER_MAX_SEC);
136→        break;
137→
138→      case REC_JOB_STOP_SAVE:
139→        rc = dm_voice_rec_stop();
140→        if (rc == 0)
141→          {
142→            rc = dm_voice_record_save(DM_VOICE_RECORD_PATH);
143→          }
144→        break;
145→
146→      case REC_JOB_PLAY:
147→        rc = dm_voice_play_file_sync(DM_VOICE_RECORD_PATH);
148→        break;
149→
150→      default:
151→        rc = -EINVAL;
152→        break;
153→    }
154→
155→  pthread_mutex_lock(&s_job_lock);
156→  s_job_result = rc;
157→  s_job_done = 1;
158→  pthread_mutex_unlock(&s_job_lock);
159→  return NULL;
160→}
161→
162→static int recorder_start_job(recorder_job_t job)
163→{
164→  pthread_t th;
165→  pthread_attr_t attr;
166→  int ret;
167→
168→  if (s_busy)
169→    {
170→      return -EBUSY;
171→    }
172→
173→  s_busy = 1;
174→  s_job = job;
175→  pthread_mutex_lock(&s_job_lock);
176→  s_job_done = 0;
177→  pthread_mutex_unlock(&s_job_lock);
178→  recorder_refresh();
179→
180→  pthread_attr_init(&attr);
181→  pthread_attr_setstacksize(&attr, 16384);
182→  ret = pthread_create(&th, &attr, recorder_worker, (void *)(intptr_t)job);
183→  pthread_attr_destroy(&attr);
184→  if (ret != 0)
185→    {
186→      s_busy = 0;
187→      s_job = REC_JOB_NONE;
188→      if (s_status)
189→        {
190→          lv_label_set_text(s_status,
191→                            dm_t("无法启动录音任务", "Could not start recorder task"));
192→        }
193→      recorder_refresh();
194→      return -ret;
195→    }
196→
197→  pthread_detach(th);
198→  return 0;
199→}
