 30→struct voice_preview_job_s
 31→{
 32→  int profile_idx;
 33→};
 34→
 35→static void *voice_preview_worker(void *arg)
 36→{
 37→  struct voice_preview_job_s *job = arg;
 38→  int profile_idx = job->profile_idx;
 39→
 40→  free(job);
 41→  s_preview_ok = (dm_voice_profile_preview(profile_idx) == 0);
 42→  s_preview_done = 1;
 43→  return NULL;
 44→}
