 46→static void request_preview(int profile_idx)
 47→{
 48→  struct voice_preview_job_s *job;
 49→  pthread_t th;
 50→  pthread_attr_t attr;
 51→  int ret;
 52→
 53→  if (s_preview_busy)
 54→    {
 55→      return;
 56→    }
 57→
 58→  job = malloc(sizeof(*job));
 59→  if (!job)
 60→    {
 61→      if (s_tip_l)
 62→        {
 63→          lv_label_set_text(s_tip_l, dm_t("内存不足，无法试听",
 64→                                          "Not enough memory to preview"));
 65→        }
 66→      return;
 67→    }
 68→  job->profile_idx = profile_idx;
 69→  s_preview_busy = 1;
 70→  s_preview_done = 0;
 71→
 72→  pthread_attr_init(&attr);
 73→  pthread_attr_setstacksize(&attr, DM_VOICE_NET_WORKER_STACK);
 74→  ret = pthread_create(&th, &attr, voice_preview_worker, job);
 75→  pthread_attr_destroy(&attr);
 76→  if (ret == 0)
 77→    {
 78→      pthread_detach(th);
 79→    }
 80→  else
 81→    {
 82→      free(job);
 83→      s_preview_busy = 0;
 84→      if (s_tip_l)
 85→        {
 86→          lv_label_set_text(s_tip_l, dm_t("试听启动失败",
 87→                                          "Could not start preview"));
 88→        }
 89→    }
 90→}
