 214→/* NSH-safe single-quote wrap; reject embedded single quotes */
 215→static int shell_quote(const char *in, char *out, size_t outsz)
 216→{
 217→  size_t n;
 218→  size_t o = 0;
 219→
 220→  if (!in || !out || outsz < 3)
 221→    {
 222→      return -1;
 223→    }
 224→  if (strchr(in, '\'') != NULL)
 225→    {
 226→      return -1;
 227→    }
 228→  n = strlen(in);
 229→  if (n + 3 > outsz)
 230→    {
 231→      return -1;
 232→    }
 233→  out[o++] = '\'';
 234→  memcpy(out + o, in, n);
 235→  o += n;
 236→  out[o++] = '\'';
 237→  out[o] = 0;
 238→  return 0;
 239→}
