 481→/* Verify the current association is really the expected SSID.
 482→ * Returns 1 = match, 0 = mismatch / not associated, -1 = cannot read. */
 483→static int wifi_verify_assoc(const char *expected)
 484→{
 485→  char assoc[33];
 486→
 487→  if (!expected || !expected[0])
 488→    {
 489→      return -1;
 490→    }
 491→  if (!wifi_is_associated(assoc, sizeof(assoc)))
 492→    {
 493→      return 0;
 494→    }
 495→  if (!assoc[0])
 496→    {
 497→      return -1;
 498→    }
 499→  return strcmp(assoc, expected) == 0 ? 1 : 0;
 500→}
