 502→/* Port of 9.5 wifi_manager.c:get_wifi_status().
 503→ * 1 = associated, 0 = not associated (AP is all-zero), -1 = cannot read.
 504→ * "wapi show" returns early when there is no IPv4 yet, so it is only used as
 505→ * an EXTRA check after an address was obtained. */
 506→static int wifi_is_link_up(void)
 507→{
 508→  FILE *fp;
