 519→  while (fgets(buf, sizeof(buf), fp) != NULL)
 520→    {
 521→      if (strstr(buf, "AP: 00:00:00:00:00:00") != NULL)
 522→        {
 523→          associated = 0;
 524→          break;
 525→        }
 526→    }
