 650→static void wifi_unquote(char *s)
 651→{
 652→  size_t n;
 653→
 654→  if (!s || s[0] != '"')
 655→    {
 656→      return;
 657→    }
 658→  n = strlen(s);
 659→  if (n >= 2 && s[n - 1] == '"')
 660→    {
 661→      memmove(s, s + 1, n - 2);
 662→      s[n - 2] = 0;
 663→    }
 664→}
