 817→  if (wifi_cred_load_cfg(ssid, slen, pass, plen) == 0)
 818→    {
 819→      return 0;
 820→    }
 821→
 822→  return wifi_cred_load_wapi_json(ssid, slen, pass, plen);
 823→}
