 857→/* Parse /tmp/wifi_scan_result.txt:
 858→ *   bssid / frequency / signal level / encode / ssid
 859→ *   74:39:89:f8:f0:ae       5240    -59     0803    Programmers7
 860→ *   d2:ad:08:f8:eb:71       2462    -88     0803    DIRECT-71-HP Smart Tank 750
 861→ *
 862→ * Preserves spaces inside SSIDs, skips hidden (empty) SSIDs and non-MAC lines,
 863→ * deduplicates same-SSID entries (keeping strongest RSSI), and sorts by RSSI.
 864→ */
 865→static int collect_aps_from_txt(void)
 866→{
 867→  FILE *fp;
 868→  char line[256];
 869→  int n = 0;
 870→  int i;
 871→  int j;
 872→
 873→  fp = fopen("/tmp/wifi_scan_result.txt", "r");
 874→  if (!fp)
 875→    {
 876→      return -1;
 877→    }
 878→
 879→  pthread_mutex_lock(&s_lock);
 880→  s_ap_n = 0;
 881→
 882→  while (fgets(line, sizeof(line), fp) && n < DM_WIFI_AP_MAX)
 883→    {
 884→      char *p = line;
 885→      char *tok_bssid;
 886→      char *tok_freq;
 887→      char *tok_rssi;
 888→      char *tok_enc;
 889→      char *ssid_start;
 890→      size_t ssid_len;
 891→      int rssi;
 892→      bool is_open;
 893→      int dup_idx = -1;
 894→
 895→      line[strcspn(line, "\r\n")] = 0;
 896→
 897→      while (*p == ' ' || *p == '\t')
 898→        {
 899→          p++;
 900→        }
 901→      if (!*p || strncmp(p, "bssid", 5) == 0)
 902→        {
 903→          continue;
 904→        }
 905→
 906→      /* Field 0: BSSID (must contain ':') */
 907→      tok_bssid = p;
 908→      while (*p && *p != ' ' && *p != '\t')
 909→        {
 910→          p++;
 911→        }
 912→      if (!*p)
 913→        {
 914→          continue;
 915→        }
 916→      *p++ = 0;
 917→      if (strchr(tok_bssid, ':') == NULL)
 918→        {
 919→          continue;
 920→        }
 921→
 922→      /* Field 1: frequency */
 923→      while (*p == ' ' || *p == '\t')
 924→        {
 925→          p++;
 926→        }
 927→      tok_freq = p;
 928→      while (*p && *p != ' ' && *p != '\t')
 929→        {
 930→          p++;
 931→        }
 932→      if (!*p || !*tok_freq)
 933→        {
 934→          continue;
 935→        }
 936→      *p++ = 0;
 937→
 938→      /* Field 2: signal level (RSSI) */
 939→      while (*p == ' ' || *p == '\t')
 940→        {
 941→          p++;
 942→        }
 943→      tok_rssi = p;
 944→      while (*p && *p != ' ' && *p != '\t')
 945→        {
 946→          p++;
 947→        }
 948→      if (!*p || !*tok_rssi)
 949→        {
 950→          continue;
 951→        }
 952→      *p++ = 0;
 953→      rssi = atoi(tok_rssi);
 954→
 955→      /* Field 3: encode (0000 = open, otherwise encrypted) */
 956→      while (*p == ' ' || *p == '\t')
 957→        {
 958→          p++;
 959→        }
 960→      tok_enc = p;
 961→      while (*p && *p != ' ' && *p != '\t')
 962→        {
 963→          p++;
 964→        }
 965→      if (*p)
 966→        {
 967→          *p++ = 0;
 968→        }
 969→      if (!*tok_enc)
 970→        {
 971→          continue;
 972→        }
 973→      is_open = (strcmp(tok_enc, "0000") == 0);
 974→
 975→      /* Field 4+: entire remainder of line is SSID (may contain spaces) */
 976→      while (*p == ' ' || *p == '\t')
 977→        {
 978→          p++;
 979→        }
 980→      ssid_start = p;
 981→      ssid_len = strlen(ssid_start);
 982→      while (ssid_len > 0 &&
 983→             (ssid_start[ssid_len - 1] == ' ' ||
 984→              ssid_start[ssid_len - 1] == '\t'))
 985→        {
 986→          ssid_start[--ssid_len] = 0;
 987→        }
 988→      if (ssid_len == 0)
 989→        {
 990→          /* Hidden AP with blank SSID */
 991→          continue;
 992→        }
 993→
 994→      /* Deduplicate by SSID: keep strongest RSSI */
 995→      for (i = 0; i < n; i++)
 996→        {
 997→          if (strncmp(s_aps[i].ssid, ssid_start, sizeof(s_aps[i].ssid) - 1) == 0)
 998→            {
 999→              dup_idx = i;
1000→              break;
1001→            }
1002→        }
1003→      if (dup_idx >= 0)
1004→        {
1005→          if (rssi > s_aps[dup_idx].rssi)
1006→            {
1007→              s_aps[dup_idx].rssi = rssi;
1008→              s_aps[dup_idx].open = is_open;
1009→            }
1010→          continue;
1011→        }
1012→
1013→      strncpy(s_aps[n].ssid, ssid_start, sizeof(s_aps[n].ssid) - 1);
1014→      s_aps[n].ssid[sizeof(s_aps[n].ssid) - 1] = 0;
1015→      s_aps[n].rssi = rssi;
1016→      s_aps[n].open = is_open;
1017→      n++;
1018→    }
1019→
1020→  /* Sort APs by RSSI descending (strongest signal first) */
1021→  for (i = 0; i < n - 1; i++)
1022→    {
1023→      for (j = i + 1; j < n; j++)
1024→        {
1025→          if (s_aps[j].rssi > s_aps[i].rssi)
1026→            {
1027→              dm_ap_t tmp = s_aps[i];
1028→              s_aps[i] = s_aps[j];
1029→              s_aps[j] = tmp;
1030→            }
1031→        }
1032→    }
1033→
1034→  s_ap_n = n;
1035→  if (s_sel >= s_ap_n)
1036→    {
1037→      s_sel = (s_ap_n > 0) ? 0 : -1;
1038→    }
1039→  pthread_mutex_unlock(&s_lock);
1040→  fclose(fp);
1041→  return n;
1042→}
