1044→static void *scan_thread(void *arg)
1045→{
1046→  int i;
1047→  int n;
1048→
1049→  (void)arg;
1050→
1051→  if (!s_wifi_enabled)
1052→    {
1053→      s_scan_busy = 0;
1054→      s_scan_ready = 1;
1055→      return NULL;
1056→    }
1057→
1058→  /* Wait briefly if an auto-connect thread is yielding */
1059→  for (i = 0; i < 50 && s_conn_busy; i++)
1060→    {
1061→      usleep(100 * 1000);
1062→    }
1063→
1064→  if (ensure_driver() < 0)
1065→    {
1066→      s_scan_busy = 0;
1067→      s_scan_ready = 1;
1068→      return NULL;
1069→    }
1070→
1071→  /* Only bring interface up in STA mode if not already connected */
1072→  if (!dm_wifi_connected())
1073→    {
1074→      cli_sta_up();
1075→      usleep(200 * 1000);
1076→    }
1077→
1078→  /* Match 9.5 demo get_wifi.sh: wapi scan wlan0 > /tmp/wifi_scan_result.txt */
1079→  (void)system("wapi scan wlan0 > /tmp/wifi_scan_result.txt");
1080→  usleep(300 * 1000);
1081→
1082→  n = collect_aps_from_txt();
1083→  if (n <= 0)
1084→    {
1085→      usleep(500 * 1000);
1086→      (void)system("wapi scan wlan0 > /tmp/wifi_scan_result.txt");
1087→      usleep(300 * 1000);
1088→      n = collect_aps_from_txt();
1089→    }
1090→
1091→  syslog(LOG_INFO, "[deskmate-wifi] wapi scan -> %d aps\n", n);
1092→  for (i = 0; i < s_ap_n; i++)
1093→    {
1094→      syslog(LOG_INFO, "[deskmate-wifi]  ap %s rssi=%d open=%d\n",
1095→             s_aps[i].ssid, s_aps[i].rssi, (int)s_aps[i].open);
1096→    }
1097→
1098→  s_scan_busy = 0;
1099→  s_scan_ready = 1;
1100→  return NULL;
1101→}
