1103→int dm_wifi_start_scan(void)
1104→{
1105→  pthread_t th;
1106→  pthread_attr_t attr;
1107→  int ret;
1108→
1109→  if (!s_wifi_enabled)
1110→    {
1111→      return -1;
1112→    }
1113→
1114→  if (s_scan_busy)
1115→    {
1116→      return 0;
1117→    }
1118→
1119→  /* Interrupt any background boot auto-connect so manual scan is never blocked */
1120→  s_manual_override = 1;
1121→  if (s_conn_busy && !s_conn_is_auto)
1122→    {
1123→      return -1;
1124→    }
1125→
1126→  s_scan_ready = 0;
1127→  s_scan_busy = 1;
1128→  pthread_attr_init(&attr);
1129→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1130→  ret = pthread_create(&th, &attr, scan_thread, NULL);
1131→  pthread_attr_destroy(&attr);
1132→  if (ret != 0)
1133→    {
1134→      s_scan_busy = 0;
1135→      return -1;
1136→    }
1137→  pthread_detach(th);
1138→  return 0;
1139→}
