1141→/* Official connect — ifup → mode 2 → psk(3 2) → essid(1) → wait → renew */
1142→static void *conn_thread(void *arg)
1143→{
1144→  char cmd[192];
1145→  char qssid[80];
1146→  char qpass[160];
1147→  int i;
1148→  int attempt;
1149→  int got_ip = 0;
1150→  int is_auto = s_conn_is_auto;
1151→  struct in_addr addr;
1152→  char try_ssid[33];
1153→  char try_pass[64];
1154→  bool try_open;
1155→
1156→  (void)arg;
1157→
1158→  if (!s_wifi_enabled)
1159→    {
1160→      s_conn_busy = 0;
1161→      s_conn_fail = 1;
1162→      return NULL;
1163→    }
1164→
1165→  strncpy(try_ssid, s_pending_ssid, sizeof(try_ssid) - 1);
1166→  try_ssid[sizeof(try_ssid) - 1] = 0;
1167→  strncpy(try_pass, s_pending_pass, sizeof(try_pass) - 1);
1168→  try_pass[sizeof(try_pass) - 1] = 0;
1169→  try_open = s_pending_open;
1170→
1171→  if (try_ssid[0] == 0 || if_nametoindex(DM_WIFI_IF) == 0)
1172→    {
1173→      syslog(LOG_ERR, "[deskmate-wifi] connect abort: no ssid/wlan0\n");
1174→      s_conn_busy = 0;
1175→      s_conn_fail = 1;
1176→      return NULL;
1177→    }
1178→
1179→  if (ensure_driver() < 0)
1180→    {
1181→      s_conn_busy = 0;
1182→      s_conn_fail = 1;
1183→      return NULL;
1184→    }
1185→
1186→  if (is_auto && s_manual_override)
1187→    {
1188→      s_conn_busy = 0;
1189→      return NULL;
1190→    }
1191→
1192→  /* NOTE: credentials are persisted only after a verified connection (below).
1193→
1194→   * 9) The 9.5 wifi_manager retries the whole sequence every 5s until it is
1195→   * associated. Port that behaviour here: up to DM_WIFI_CONN_ROUNDS tries. */
1196→  for (attempt = 0; attempt < DM_WIFI_CONN_ROUNDS; attempt++)
1197→    {
1198→      if (attempt > 0)
1199→        {
1200→          syslog(LOG_INFO, "[deskmate-wifi] retry %d/%d in %ds\n",
1201→                 attempt + 1, DM_WIFI_CONN_ROUNDS, DM_WIFI_CONN_RETRY_SEC);
1202→          sleep(DM_WIFI_CONN_RETRY_SEC);
1203→        }
1204→
1205→      got_ip = 0;
1206→
1207→      /* 1) ifup + STA mode */
1208→      cli_sta_up();
1209→
1210→  /* 1.5) Drop the previous association so switching between networks
1211→   *      (WPA2 <-> open) always starts from a clean driver state. */
1212→  syslog(LOG_INFO, "[deskmate-wifi] wapi disconnect %s\n", DM_WIFI_IF);
1213→  (void)system("wapi disconnect wlan0");
1214→  usleep(100 * 1000);
1215→
1216→  /* 2) psk — WPA_ALG_CCMP = 3, WPA2 = 2 */
1217→  if (!try_open && try_pass[0])
1218→    {
1219→      if (shell_quote(try_pass, qpass, sizeof(qpass)) < 0)
1220→        {
1221→          s_conn_busy = 0;
1222→          s_conn_fail = 1;
1223→          return NULL;
1224→        }
1225→      snprintf(cmd, sizeof(cmd), "wapi psk %s %s 3 2", DM_WIFI_IF, qpass);
1226→      syslog(LOG_INFO,
1227→             "[deskmate-wifi] applying WPA2 credentials (redacted)\n");
1228→      if (system(cmd) != 0)
1229→        {
1230→          syslog(LOG_ERR, "[deskmate-wifi] psk failed (passphrase must be 8-63 chars)\n");
1231→          s_conn_busy = 0;
1232→          s_conn_fail = 1;
1233→          return NULL;
1234→        }
1235→    }
1236→  else
1237→    {
1238→      /* Open AP: clear any leftover WPA key (alg 0 = WPA_ALG_NONE), otherwise
1239→       * the driver keeps the previous CCMP key and cannot join open networks. */
1240→      syslog(LOG_INFO, "[deskmate-wifi] open AP: clear psk\n");
1241→      (void)system("wapi psk wlan0 00000000 0");
1242→    }
1243→
1244→  /* 3) essid — flag 1 = connect */
1245→  if (shell_quote(try_ssid, qssid, sizeof(qssid)) < 0)
1246→    {
1247→      s_conn_busy = 0;
1248→      s_conn_fail = 1;
1249→      return NULL;
1250→    }
1251→  snprintf(cmd, sizeof(cmd), "wapi essid %s %s 1", DM_WIFI_IF, qssid);
1252→  syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
1253→  if (system(cmd) != 0)
1254→    {
1255→      syslog(LOG_ERR, "[deskmate-wifi] essid join failed\n");
1256→      s_conn_busy = 0;
1257→      s_conn_fail = 1;
1258→      return NULL;
1259→    }
1260→
1261→  /* 4) Wait for WPA2 4-way handshake / association (interruptible if auto) */
1262→  for (i = 0; i < 25; i++)
1263→    {
1264→      if (!s_wifi_enabled)
1265→        {
1266→          s_conn_busy = 0;
1267→          return NULL;
1268→        }
1269→      if (is_auto && s_manual_override)
1270→        {
1271→          s_conn_busy = 0;
1272→          return NULL;
1273→        }
1274→      usleep(100 * 1000);
1275→    }
1276→
1277→  /* 5) DHCP renew — single DHCP call per attempt */
1278→  for (i = 0; i < 4; i++)
1279→    {
1280→      if (is_auto && s_manual_override)
1281→        {
1282→          s_conn_busy = 0;
1283→          return NULL;
1284→        }
1285→
1286→      (void)system("renew wlan0");
1287→      if (wifi_get_valid_ip(&addr) == 0)
1288→        {
1289→          got_ip = 1;
1290→          break;
1291→        }
1292→
1293→      if (is_auto && s_manual_override)
1294→        {
1295→          s_conn_busy = 0;
1296→          return NULL;
1297→        }
1298→
1299→      if (netlib_obtain_ipv4addr(DM_WIFI_IF) >= 0 &&
1300→          wifi_get_valid_ip(&addr) == 0)
1301→        {
1302→          got_ip = 1;
1303→          break;
1304→        }
1305→
1306→      syslog(LOG_WARNING, "[deskmate-wifi] renew retry %d\n", i + 1);
1307→      sleep(1);
1308→    }
1309→
1310→  /* Verify we are really associated with the intended SSID (an old IPv4
1311→   * address may still be configured while switching networks). */
1312→  if (got_ip)
1313→    {
1314→      int assoc = wifi_verify_assoc(try_ssid);
1315→      if (assoc == 0)
1316→        {
1317→          syslog(LOG_ERR,
1318→                 "[deskmate-wifi] associated to another SSID, treat as failure\n");
1319→          got_ip = 0;
1320→        }
1321→      else if (assoc < 0)
1322→        {
1323→          syslog(LOG_WARNING,
1324→                 "[deskmate-wifi] cannot verify ESSID, assume connected\n");
1325→        }
1326→    }
1327→
1328→      /* Ported check: "wapi show" reports AP all-zero when not associated. */
1329→      if (got_ip && wifi_is_link_up() == 0)
1330→        {
1331→          syslog(LOG_WARNING, "[deskmate-wifi] wapi show: not associated yet\n");
1332→          got_ip = 0;
1333→        }
1334→
1335→      if (got_ip)
1336→        {
1337→          break;
1338→        }
1339→
1340→      syslog(LOG_WARNING, "[deskmate-wifi] attempt %d/%d failed\n",
1341→             attempt + 1, DM_WIFI_CONN_ROUNDS);
1342→    }
1343→
1344→  if (got_ip && !s_wifi_enabled)
1345→    {
1346→      got_ip = 0;
1347→    }
1348→
1349→  /* Fix: Only set s_cur_ssid when got_ip is true! */
1350→  pthread_mutex_lock(&s_lock);
1351→  if (got_ip)
1352→    {
1353→      strncpy(s_cur_ssid, try_ssid, sizeof(s_cur_ssid) - 1);
1354→      s_cur_ssid[sizeof(s_cur_ssid) - 1] = 0;
1355→      strncpy(s_cur_ip, inet_ntoa(addr), sizeof(s_cur_ip) - 1);
1356→      s_cur_ip[sizeof(s_cur_ip) - 1] = 0;
1357→    }
1358→  else
1359→    {
1360→      s_cur_ssid[0] = 0;
1361→      s_cur_ip[0] = 0;
1362→    }
1363→  pthread_mutex_unlock(&s_lock);
1364→
1365→  if (!got_ip)
1366→    {
1367→      syslog(LOG_ERR,
1368→             "[deskmate-wifi] connect fail after %d attempts "
1369→             "(ssid=%s wlan0=%d)\n",
1370→             DM_WIFI_CONN_ROUNDS, try_ssid,
1371→             (int)if_nametoindex(DM_WIFI_IF));
1372→      s_conn_busy = 0;
1373→      s_conn_fail = 1;
1374→      return NULL;
1375→    }
1376→
1377→  syslog(LOG_INFO, "[deskmate-wifi] connected ssid=%s ip=%s\n",
1378→         s_cur_ssid, s_cur_ip);
1379→
1380→  /* FlowDesk owns credential persistence; let NTP start only after WLAN
1381→   * has a verified association and an IPv4 address. */
1382→  wifi_cred_save(try_ssid, try_pass);
1383→  s_manual_override = 0;
1384→  s_link_lost = 0;
1385→  if (!wifi_ntp_has_samples())
1386→    {
1387→      wifi_restart_ntp_after_link();
1388→    }
1389→
1390→  s_conn_busy = 0;
1391→  s_conn_ok = 1;
1392→  return NULL;
1393→}
