1395→static int wifi_start_connect_internal(const char *ssid, const char *pass,
1396→                                       int is_auto)
1397→{
1398→  pthread_t th;
1399→  pthread_attr_t attr;
1400→  int ret;
1401→  int i;
1402→
1403→  if (!ssid || !ssid[0])
1404→    {
1405→      return -1;
1406→    }
1407→
1408→  if (!is_auto)
1409→    {
1410→      s_manual_override = 1;
1411→      for (i = 0; i < 50 && (s_scan_busy || (s_conn_busy && s_conn_is_auto)); i++)
1412→        {
1413→          usleep(100 * 1000);
1414→        }
1415→    }
1416→
1417→  if (s_scan_busy || s_conn_busy)
1418→    {
1419→      return -1;
1420→    }
1421→
1422→  strncpy(s_pending_ssid, ssid, sizeof(s_pending_ssid) - 1);
1423→  s_pending_ssid[sizeof(s_pending_ssid) - 1] = 0;
1424→  if (pass)
1425→    {
1426→      strncpy(s_pending_pass, pass, sizeof(s_pending_pass) - 1);
1427→      s_pending_pass[sizeof(s_pending_pass) - 1] = 0;
1428→    }
1429→  else
1430→    {
1431→      s_pending_pass[0] = 0;
1432→    }
1433→  s_pending_open = (pass == NULL || s_pending_pass[0] == 0);
1434→
1435→  s_conn_ok = 0;
1436→  s_conn_fail = 0;
1437→  s_conn_is_auto = is_auto;
1438→  s_conn_busy = 1;
1439→
1440→  pthread_attr_init(&attr);
1441→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1442→  ret = pthread_create(&th, &attr, conn_thread, NULL);
1443→  pthread_attr_destroy(&attr);
1444→  if (ret != 0)
1445→    {
1446→      s_conn_busy = 0;
1447→      return -1;
1448→    }
1449→  pthread_detach(th);
1450→  return 0;
1451→}
1452→
1453→int dm_wifi_connect(const char *ssid, const char *pass)
1454→{
1455→  return wifi_start_connect_internal(ssid, pass, 0);
1456→}
