 17→#define MIMO_BASE "https://token-plan-ams.xiaomimimo.com/v1"
 18→#define MIMO_KEY_PATH "/data/deskmate_mimo.key"
 19→#define MIMO_EMBEDDED_KEY "tp-***REDACTED***"
 20→#define MIMO_CURL_CONFIG "/tmp/dm_chat_mimo.conf"
 21→#define MIMO_MODEL "mimo-v2.6-flash"
 22→#define CHAT_REQ_PATH "/tmp/dm_chat_req.json"
