 27→static int chat_key_load(char *key, size_t key_cap)
 28→{
 29→  FILE *f;
 30→  size_t i;
 31→  size_t n;
 32→  int valid = 0;
 33→
 34→  if (!key || key_cap < 16)
 35→    {
 36→      return 0;
 37→    }
 38→  key[0] = '\0';
 39→  f = fopen(MIMO_KEY_PATH, "rb");
 40→  if (!f)
 41→    {
 42→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 43→      return key[0] != '\0';
 44→    }
 45→  if (fgets(key, (int)key_cap, f))
 46→    {
 47→      n = strlen(key);
 48→      while (n > 0 && (key[n - 1] == '\r' || key[n - 1] == '\n' ||
 49→                       key[n - 1] == ' ' || key[n - 1] == '\t'))
 50→        {
 51→          key[--n] = '\0';
 52→        }
 53→      valid = n > 8 && n < key_cap - 1;
 54→      for (i = 0; valid && i < n; i++)
 55→        {
 56→          unsigned char ch = (unsigned char)key[i];
 57→          if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
 58→                (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' ||
 59→                ch == '.'))
 60→            {
 61→              valid = 0;
 62→            }
 63→        }
 64→    }
 65→  fclose(f);
 66→  if (!valid)
 67→    {
 68→      memset(key, 0, key_cap);
 69→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 70→      valid = key[0] != '\0';
 71→    }
 72→  return valid;
 73→}
 74→
 75→static int run_curl_script(const char *line)
 76→{
 77→  char key[128];
 78→  FILE *kf;
 79→  FILE *sf;
 80→  int key_write_ok;
 81→  int key_close_rc;
 82→  int script_write_ok;
 83→  int script_close_rc;
 84→  int rc;
 85→
 86→  if (!chat_key_load(key, sizeof(key)))
 87→    {
 88→      syslog(LOG_ERR, "[dm-chat] runtime API key missing or invalid\n");
 89→      return -1;
 90→    }
 91→
 92→  kf = fopen(MIMO_CURL_CONFIG, "w");
 93→  if (!kf || chmod(MIMO_CURL_CONFIG, S_IRUSR | S_IWUSR) != 0)
 94→    {
 95→      if (kf)
 96→        {
 97→          fclose(kf);
 98→        }
 99→      memset(key, 0, sizeof(key));
100→      unlink(MIMO_CURL_CONFIG);
101→      return -1;
102→    }
103→  key_write_ok = fprintf(kf, "header = \"Authorization: Bearer %s\"\n",
104→                         key) > 0;
105→  key_close_rc = fclose(kf);
106→  memset(key, 0, sizeof(key));
107→  if (!key_write_ok || key_close_rc != 0)
108→    {
109→      unlink(MIMO_CURL_CONFIG);
110→      return -1;
111→    }
112→
113→  sf = fopen(CHAT_CURL_SCRIPT, "w");
114→  if (!sf)
115→    {
116→      unlink(MIMO_CURL_CONFIG);
117→      syslog(LOG_ERR, "[dm-chat] cannot create curl script\n");
118→      return -1;
119→    }
120→  script_write_ok = fputs("#!/bin/sh\n", sf) != EOF &&
121→                    fputs(line, sf) != EOF && fputc('\n', sf) != EOF;
122→  script_close_rc = fclose(sf);
123→  if (!script_write_ok || script_close_rc != 0)
124→    {
125→      unlink(MIMO_CURL_CONFIG);
126→      syslog(LOG_ERR, "[dm-chat] cannot write curl script\n");
127→      return -1;
128→    }
129→
130→  rc = system("sh " CHAT_CURL_SCRIPT);
131→  unlink(MIMO_CURL_CONFIG);
132→  if (rc != 0)
133→    {
134→      syslog(LOG_ERR, "[dm-chat] curl script failed status=%d\n", rc);
135→      return -1;
136→    }
137→  return 0;
138→}
