208→static int json_escape(const char *in, char *out, size_t cap)
209→{
210→  size_t o = 0;
211→  size_t i;
212→
213→  if (!in || !out || cap < 2)
214→    {
215→      return -1;
216→    }
217→  for (i = 0; in[i] && o + 8 < cap; i++)
218→    {
219→      unsigned char ch = (unsigned char)in[i];
220→      if (ch == '"' || ch == '\\')
221→        {
222→          out[o++] = '\\';
223→          out[o++] = (char)ch;
224→        }
225→      else if (ch == '\n')
226→        {
227→          out[o++] = '\\';
228→          out[o++] = 'n';
229→        }
230→      else if (ch < 0x20)
231→        {
232→          /* skip control chars */
233→        }
234→      else
235→        {
236→          out[o++] = (char)ch;
237→        }
238→    }
239→  out[o] = '\0';
240→  return (int)o;
241→}
