521→/* ---- dictionary AI definition ---- */
522→int dm_dict_ai_define(const char *word, char *out, int cap)
523→{
524→  char esc[96];
525→  char body[700];
526→  char cmd[1100];
527→  FILE *f;
528→  int n;
529→
530→  if (!word || !word[0] || !out || cap < 8)
531→    {
532→      return -1;
533→    }
534→  out[0] = '\0';
535→  if (!dm_wifi_connected() || dm_wifi_wait_time_sync(40) != 0)
536→    {
537→      return -1;
538→    }
539→  if (json_escape(word, esc, sizeof(esc)) < 0)
540→    {
541→      return -1;
542→    }
543→  n = snprintf(body, sizeof(body),
544→               "{\"model\":\"%s\",\"messages\":["
545→               "{\"role\":\"system\",\"content\":\"你是专业词典助手，用中文简洁解释单词，不超过100字。\"},"
546→               "{\"role\":\"user\",\"content\":\"解释单词 %s：词性、常见释义、一个例句。\"}],"
547→               "\"max_completion_tokens\":180,\"thinking\":{\"type\":\"disabled\"}}",
548→               MIMO_MODEL, esc);
549→  if (n <= 0 || n >= (int)sizeof(body))
550→    {
551→      return -1;
552→    }
553→  f = fopen(CHAT_REQ_PATH, "w");
554→  if (!f)
555→    {
556→      return -1;
557→    }
558→  fwrite(body, 1, (size_t)n, f);
559→  fclose(f);
560→  unlink(CHAT_RSP_PATH);
561→  snprintf(cmd, sizeof(cmd),
562→           "curl -K " MIMO_CURL_CONFIG " "
563→           "--cacert /resource/etc/ssl/curl/ca-certificates.crt "
564→           "-s -S -f -m 18 -X POST %s/chat/completions "
565→           "-H 'Content-Type: application/json' "
566→           "-d @%s -o %s",
567→           MIMO_BASE, CHAT_REQ_PATH, CHAT_RSP_PATH);
568→  if (run_curl_script(cmd) != 0)
569→    {
570→      return -1;
571→    }
572→  extract_content(CHAT_RSP_PATH, out, (size_t)cap);
573→  return out[0] ? 0 : -1;
574→}
