 38→static uint64_t chat_monotonic_ms(void)
 39→{
 40→  struct timespec ts;
 41→
 42→  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
 43→    {
 44→      return 0;
 45→    }
 46→  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
 47→}
