278→static void ptt_click(lv_event_t *e)
279→{
280→  int rec_rc;
281→
282→  (void)e;
283→
284→  if (s_busy)
285→    {
286→      return;
287→    }
288→
289→  if (!s_ui_rec)
290→    {
291→      if (!dm_wifi_connected())
292→        {
293→          set_ans(dm_t("Wi-Fi 尚未就绪，请先连接网络",
294→                       "Wi-Fi is not ready; connect first"));
295→          set_sub(dm_t("连接完成后再开始语音聊天",
296→                       "Start voice chat after connection completes"));
297→          set_ptt("开始说话", "Start talk", C_BTN);
298→          return;
299→        }
300→      s_mic_err = 0;
301→      dm_voice_set_speaker_volume(80);
302→      rec_rc = dm_voice_rec_start(6);
303→      if (rec_rc != 0)
304→        {
305→          if (rec_rc == -EBUSY)
306→            {
307→              set_ans(dm_t("音频设备忙，请稍后再试",
308→                           "Audio device busy; try again shortly"));
309→              set_sub(dm_t("等待录音或播放结束", "Wait for recording or playback to finish"));
310→            }
311→          else
312→            {
313→              set_ans(dm_t("麦克风不可用", "Mic unavailable"));
314→              set_sub(dm_t("检查 /dev/audio/pcm0c",
315→                           "Check /dev/audio/pcm0c"));
316→            }
317→          set_ptt("开始说话", "Start talk", C_BTN);
318→          return;
319→        }
320→      s_ui_rec = true;
321→      s_rec_sec = 0;
322→      s_rec_started_ms = chat_monotonic_ms();
323→      dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
324→      set_ans(dm_t("● 录音中… 再点一下结束并发送",
325→                   "● Recording… tap again to send"));
326→      set_sub(dm_t("再点一下结束", "Tap again to stop"));
327→      set_ptt("结束并发送", "Stop & send", C_HEART);
328→    }
329→  else
330→    {
331→      s_ui_rec = false;
332→      s_rec_sec = 0;
333→      set_ptt("发送中…", "Sending…", C_BTN_HI);
334→      set_ans(dm_t("正在结束录音…", "Stopping mic…"));
335→
336→      if (s_mic_err)
337→        {
338→          set_ans(dm_t("麦克风故障，无法录音", "Mic failed"));
339→          set_sub(dm_t("检查 /dev/audio/pcm0c", "Check mic device"));
340→          reset_to_idle();
341→          return;
342→        }
343→
344→      /* Stop/join and network work run in voice_worker, not this LVGL event. */
345→      kick_job(1);
346→    }
347→}
