406→void dm_chat_tick(void)
407→{
408→  /* apply worker results on LVGL thread */
409→  if (s_out_ready)
410→    {
411→      s_out_ready = 0;
412→      if (s_out_ans[0])
413→        {
414→          set_ans(s_out_ans);
415→        }
416→      if (s_out_sub[0])
417→        {
418→          set_sub(s_out_sub);
419→        }
420→      dm_face_set(FACE_HAPPY, EYE_DECOR_NONE, 8);
421→      reset_to_idle();
422→    }
423→
424→  if (s_ui_rec && !s_busy)
425→    {
426→      char buf[80];
427→      uint64_t now_ms = chat_monotonic_ms();
428→      if (s_rec_started_ms != 0 && now_ms >= s_rec_started_ms)
429→        {
430→          s_rec_sec = (int)((now_ms - s_rec_started_ms) / 1000);
431→        }
432→      if (dm_voice_rec_active())
433→        {
434→          snprintf(buf, sizeof(buf),
435→                   dm_t("● 录音中 %d 秒 · 再点一下结束并发送",
436→                        "● Recording %ds · tap again to send"),
437→                   s_rec_sec);
438→          set_ans(buf);
439→          set_sub((s_rec_sec & 1) ? dm_t("正在听…", "Listening…")
440→                                  : dm_t("对准麦克风说话", "Speak to the mic"));
441→        }
442→      else
443→        {
444→          s_ui_rec = false;
445→          if (s_rec_sec < 2)
446→            {
447→              s_mic_err = 1;
448→              set_ans(dm_t("麦克风故障，无法录音", "Mic failed"));
449→              set_sub(dm_t("检查 /dev/audio/pcm0c", "Check mic device"));
450→              reset_to_idle();
451→            }
452→          else
453→            {
454→              /* Recording auto-stop reached the configured limit.  Send the
455→               * captured WAV instead of silently discarding it. */
456→              kick_job(1);
457→            }
458→        }
459→    }
460→}
