619→  struct nxplayer_s *p = NULL;
620→  int rc = -1;
621→
622→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
623→    {
624→      return -EBUSY;
625→    }
626→  if (s_rec_active)
627→    {
628→      pthread_mutex_unlock(&s_audio_lock);
629→      return -EBUSY;
630→    }
631→
632→  p = nxplayer_create();
633→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
634→    {
635→      syslog(LOG_ERR, "[dm-voice] beep cannot open speaker player\n");
636→      goto out;
637→    }
638→
639→  dm_vol_apply();
640→#ifndef CONFIG_AUDIO_EXCLUDE_VOLUME
641→  (void)nxplayer_setvolume(p, (uint16_t)(s_speaker_vol * 10));
642→#endif
643→  if (nxplayer_playtone(p, SPEAKER_RATE, 440, 1) != OK)
644→    {
645→      syslog(LOG_ERR, "[dm-voice] nxplayer_playtone failed errno=%d\n", errno);
646→      goto out;
647→    }
648→
649→  /* Tone playback is asynchronous; wait slightly beyond its duration and
650→   * join it before allowing the next audio operation. */
651→  usleep(1150 * 1000);
652→  (void)nxplayer_stop(p);
653→  rc = 0;
654→
655→out:
656→  if (p)
657→    {
658→      nxplayer_release(p);
659→    }
660→  pthread_mutex_unlock(&s_audio_lock);
661→  return rc;
662→}
