680→static int json_escape(const char *in, char *out, size_t cap)
681→{
682→  size_t o = 0;
683→  size_t i;
684→
685→  if (!in || !out || cap < 2)
686→    {
687→      if (out && cap)
688→        {
689→          out[0] = '\0';
690→        }
691→      return -1;
692→    }
693→
694→  for (i = 0; in[i]; i++)
695→    {
696→      unsigned char ch = (unsigned char)in[i];
697→      size_t need = (ch == '"' || ch == '\\' || ch == '\n') ? 2 :
698→                    (ch >= 0x20 ? 1 : 0);
699→
700→      if (o + need >= cap)
701→        {
702→          out[o] = '\0';
703→          return -1;
704→        }
705→      if (ch == '"' || ch == '\\')
706→        {
707→          out[o++] = '\\';
708→          out[o++] = (char)ch;
709→        }
710→      else if (ch == '\n')
711→        {
712→          out[o++] = '\\';
713→          out[o++] = 'n';
714→        }
715→      else if (ch >= 0x20)
716→        {
717→          out[o++] = (char)ch;
718→        }
719→    }
720→  out[o] = '\0';
721→  return (int)o;
722→}
