157→  if (fclose(in) != 0)
158→    {
159→      write_failed = 1;
160→    }
161→  if (fclose(out) != 0)
162→    {
163→      write_failed = 1;
164→    }
165→
166→  if (write_failed || !recorder_wav_exists(dst))
167→    {
168→      unlink(dst);
169→      return;
170→    }
171→
172→  s_slot_exists[0] = 1;
173→  s_slot_count = 1;
174→}
