176→static void recorder_state_save(int next_slot)
177→{
178→  FILE *f;
179→
180→  if (next_slot < 0 || next_slot >= RECORDER_SLOT_COUNT)
181→    {
182→      return;
183→    }
184→
185→  f = fopen(RECORDER_STATE_TMP, "w");
186→  if (!f)
187→    {
188→      return;
189→    }
190→  if (fprintf(f, "%d\n", next_slot) < 0)
191→    {
192→      fclose(f);
193→      unlink(RECORDER_STATE_TMP);
194→      return;
195→    }
196→  if (fclose(f) != 0)
197→    {
198→      unlink(RECORDER_STATE_TMP);
199→      return;
200→    }
201→  if (rename(RECORDER_STATE_TMP, RECORDER_STATE_PATH) != 0)
202→    {
203→      unlink(RECORDER_STATE_TMP);
204→    }
205→}
