207→static void recorder_scan_slots(void)
208→{
209→  FILE *f;
210→  int next_slot = -1;
211→  int i;
212→  char path[64];
213→
214→  s_slot_count = 0;
215→  s_selected_slot = -1;
216→  s_next_slot = 0;
217→
218→  for (i = 0; i < RECORDER_SLOT_COUNT; i++)
219→    {
220→      if (recorder_slot_path(i, path, sizeof(path)) == 0 &&
221→          recorder_wav_exists(path))
222→        {
223→          s_slot_exists[i] = 1;
224→          s_slot_count++;
225→        }
226→      else
227→        {
228→          s_slot_exists[i] = 0;
229→        }
230→    }
231→
232→  /* Keep recordings made by the previous single-file recorder visible. */
233→  recorder_copy_legacy_if_needed();
234→
235→  f = fopen(RECORDER_STATE_PATH, "r");
236→  if (f)
237→    {
238→      if (fscanf(f, "%d", &next_slot) != 1 ||
239→          next_slot < 0 || next_slot >= RECORDER_SLOT_COUNT)
240→        {
241→          next_slot = -1;
242→        }
243→      fclose(f);
244→    }
245→
246→  if (next_slot >= 0)
247→    {
248→      int previous = (next_slot + RECORDER_SLOT_COUNT - 1) %
249→                     RECORDER_SLOT_COUNT;
250→      s_next_slot = next_slot;
251→      if (s_slot_exists[previous])
252→        {
253→          s_selected_slot = previous;
254→        }
255→    }
256→
257→  if (s_selected_slot < 0 && s_slot_count > 0)
258→    {
259→      for (i = 0; i < RECORDER_SLOT_COUNT; i++)
260→        {
261→          if (s_slot_exists[i])
262→            {
263→              s_selected_slot = i;
264→              s_next_slot = (i + 1) % RECORDER_SLOT_COUNT;
265→              break;
266→            }
267→        }
268→    }
269→
270→  if (s_slot_count == 0)
271→    {
272→      s_next_slot = 0;
273→    }
274→}
