 29→static int chat_key_load(char *key, size_t key_cap)
 30→{
 31→  FILE *f;
 32→  size_t i;
 33→  size_t n;
 34→  int valid = 0;
 35→
 36→  if (!key || key_cap < 16)
 37→    {
 38→      return 0;
 39→    }
 40→  key[0] = '\0';
 41→  f = fopen(MIMO_KEY_PATH, "rb");
 42→  if (!f)
 43→    {
 44→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 45→      return key[0] != '\0';
 46→    }
 47→  if (fgets(key, (int)key_cap, f))
 48→    {
 49→      n = strlen(key);
 50→      while (n > 0 && (key[n - 1] == '\r' || key[n - 1] == '\n' ||
 51→                       key[n - 1] == ' ' || key[n - 1] == '\t'))
 52→        {
 53→          key[--n] = '\0';
 54→        }
 55→      valid = n > 8 && n < key_cap - 1;
 56→      for (i = 0; valid && i < n; i++)
 57→        {
 58→          unsigned char ch = (unsigned char)key[i];
 59→          if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
 60→                (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' ||
 61→                ch == '.'))
 62→            {
 63→              valid = 0;
 64→            }
 65→        }
 66→    }
 67→  fclose(f);
 68→  if (!valid)
 69→    {
 70→      memset(key, 0, key_cap);
 71→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 72→      valid = key[0] != '\0';
 73→    }
 74→  return valid;
 75→}
 76→
 77→/* Invoke curl through NuttX system(). Restrictive permissions are attempted
 78→ * when supported but must not block requests on filesystems without chmod. */
 79→static int run_curl_command(const char *line)
 80→{
 81→  char key[128];
 82→  FILE *kf;
 83→  int key_write_ok;
 84→  int key_close_rc;
 85→  int rc;
 86→  int saved_errno;
 87→
 88→  if (!line || !line[0] || !chat_key_load(key, sizeof(key)))
 89→    {
 90→      syslog(LOG_ERR, "[dm-chat] API key or curl command unavailable\n");
 91→      return -1;
 92→    }
 93→
 94→  kf = fopen(MIMO_CURL_CONFIG, "w");
 95→  if (!kf)
 96→    {
 97→      syslog(LOG_ERR, "[dm-chat] cannot create curl config errno=%d\n", errno);
 98→      memset(key, 0, sizeof(key));
 99→      return -1;
100→    }
101→  if (chmod(MIMO_CURL_CONFIG, S_IRUSR | S_IWUSR) != 0)
102→    {
103→      /* On this NuttX image chmod is not implemented. Continue with a
104→       * short-lived config file; its key is never put on the command line. */
105→      syslog(LOG_WARNING,
106→             "[dm-chat] chmod unavailable for curl config errno=%d; continuing\n",
107→             errno);
108→    }
109→  key_write_ok = fprintf(kf, "header = \"Authorization: Bearer %s\"\n",
110→                         key) > 0;
111→  key_close_rc = fclose(kf);
112→  memset(key, 0, sizeof(key));
113→  if (!key_write_ok || key_close_rc != 0)
114→    {
115→      syslog(LOG_ERR, "[dm-chat] cannot write curl config\n");
116→      unlink(MIMO_CURL_CONFIG);
117→      return -1;
118→    }
119→
120→  errno = 0;
121→  rc = system(line);
122→  saved_errno = errno;
123→  unlink(MIMO_CURL_CONFIG);
124→  if (rc != 0)
125→    {
126→      syslog(LOG_ERR,
127→             "[dm-chat] curl command failed system_status=%d errno=%d\n",
128→             rc, saved_errno);
129→      return -1;
130→    }
131→  return 0;
132→}
