346→static void extract_content(const char *path, char *out, size_t cap)
347→{
348→  FILE *f;
349→  char *buf;
350→  long sz;
351→  cJSON *root;
352→  cJSON *choices;
353→  cJSON *choice;
354→  cJSON *message;
355→  cJSON *content;
356→
357→  if (!out || cap < 2)
358→    {
359→      return;
360→    }
361→  out[0] = '\0';
362→  f = fopen(path, "rb");
363→  if (!f)
364→    {
365→      return;
366→    }
367→  if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) <= 0 ||
368→      sz > 64 * 1024 || fseek(f, 0, SEEK_SET) != 0)
369→    {
370→      fclose(f);
371→      return;
372→    }
373→  buf = malloc((size_t)sz + 1);
374→  if (!buf)
375→    {
376→      fclose(f);
377→      return;
378→    }
379→  if (fread(buf, 1, (size_t)sz, f) != (size_t)sz)
380→    {
381→      free(buf);
382→      fclose(f);
383→      return;
384→    }
385→  buf[sz] = '\0';
386→  fclose(f);
387→
388→  root = cJSON_Parse(buf);
389→  free(buf);
390→  if (!root)
391→    {
392→      return;
393→    }
394→  choices = cJSON_GetObjectItem(root, "choices");
395→  choice = choices && cJSON_IsArray(choices)
396→             ? cJSON_GetArrayItem(choices, 0) : NULL;
397→  message = choice ? cJSON_GetObjectItem(choice, "message") : NULL;
398→  content = message ? cJSON_GetObjectItem(message, "content") : NULL;
399→  if (content && cJSON_IsString(content) && content->valuestring)
400→    {
401→      snprintf(out, cap, "%s", content->valuestring);
402→    }
403→  cJSON_Delete(root);
404→}
