568→int dm_dict_ai_define(const char *word, char *out, int cap)
569→{
570→  char esc[96];
571→  char body[700];
572→  char cmd[1100];
573→  FILE *f;
574→  int n;
575→
576→  if (!word || !word[0] || !out || cap < 8)
577→    {
578→      return -1;
579→    }
580→  out[0] = '\0';
581→  if (!dm_wifi_connected() || dm_wifi_wait_time_sync(40) != 0)
582→    {
583→      return -1;
584→    }
585→  if (json_escape(word, esc, sizeof(esc)) < 0)
586→    {
587→      return -1;
588→    }
589→  n = snprintf(body, sizeof(body),
590→               "{\"model\":\"%s\",\"messages\":["
591→               "{\"role\":\"system\",\"content\":\"你是专业词典助手，用中文简洁解释单词，不超过100字。\"},"
592→               "{\"role\":\"user\",\"content\":\"解释单词 %s：词性、常见释义、一个例句。\"}],"
593→               "\"max_completion_tokens\":180,\"thinking\":{\"type\":\"disabled\"}}",
594→               MIMO_MODEL, esc);
595→  if (n <= 0 || n >= (int)sizeof(body))
596→    {
597→      return -1;
598→    }
599→  f = fopen(CHAT_REQ_PATH, "w");
600→  if (!f)
601→    {
602→      return -1;
603→    }
604→  fwrite(body, 1, (size_t)n, f);
605→  fclose(f);
606→  unlink(CHAT_RSP_PATH);
607→  snprintf(cmd, sizeof(cmd),
608→           "curl -K " MIMO_CURL_CONFIG " "
609→           "--cacert /resource/etc/ssl/curl/ca-certificates.crt "
610→           "-s -S -f -m 18 -X POST %s/chat/completions "
611→           "-H 'Content-Type: application/json' "
612→           "-d @%s -o %s",
613→           MIMO_BASE, CHAT_REQ_PATH, CHAT_RSP_PATH);
614→  if (run_curl_command(cmd) != 0)
615→    {
616→      return -1;
