 971→/* The chat UI can become available before boot auto-connect finishes.  Let
 972→ * the worker wait briefly for the app's verified WLAN/IP state before trying
 973→ * a cloud request; never block the LVGL thread. */
 974→static int voice_wait_for_wifi(void)
 975→{
 976→  int i;
 977→
 978→  for (i = 0; i <= VOICE_WIFI_WAIT_SEC; i++)
 979→    {
 980→      if (dm_wifi_connected())
 981→        {
 982→          return 0;
 983→        }
 984→      if (i < VOICE_WIFI_WAIT_SEC)
 985→        {
 986→          sleep(1);
 987→        }
 988→    }
 989→  return -1;
 990→}
