481→               "\"max_completion_tokens\":400,\"thinking\":{\"type\":\"disabled\"}}",
482→               MIMO_MODEL, persona, hist, esc);
483→  if (n <= 0 || n >= (int)sizeof(body))
484→    {
485→      return local_reply(user_text);
486→    }
487→
488→  f = fopen(CHAT_REQ_PATH, "w");
489→  if (!f)
490→    {
491→      syslog(LOG_ERR, "[dm-chat] cannot create request body errno=%d\n", errno);
492→      return local_reply(user_text);
493→    }
494→  write_ok = fwrite(body, 1, (size_t)n, f) == (size_t)n;
495→  close_rc = fclose(f);
496→  if (!write_ok || close_rc != 0)
497→    {
498→      syslog(LOG_ERR, "[dm-chat] cannot write request body\n");
499→      return local_reply(user_text);
500→    }
501→
502→  unlink(CHAT_RSP_PATH);
503→  curl_rc = run_curl_command(MIMO_BASE "/chat/completions",
504→                             CHAT_REQ_PATH, CHAT_RSP_PATH, 20);
505→  if (curl_rc != 0)
506→    {
507→      syslog(LOG_WARNING,
508→             "[dm-chat] HTTP request failed; inspect curl output/status above\n");
509→      strncpy(s_last_reply, local_reply(user_text),
510→              sizeof(s_last_reply) - 1);
511→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
