1448→      return -1;
1449→    }
1450→  dm_chat_hist_json(hist, sizeof(hist));
1451→
1452→  n = snprintf(body, sizeof(body),
1453→               "{\"model\":\"%s\",\"messages\":["
1454→               "{\"role\":\"system\",\"content\":\"你是openvela语音小助手，口语化简短回答，不超过60字。\"},"
1455→               "%s"
1456→               "{\"role\":\"user\",\"content\":\"%s\"}],"
1457→               "\"max_completion_tokens\":400,\"thinking\":{\"type\":\"disabled\"}}",
1458→               CHAT_MODEL, hist, esc);
1459→  if (n <= 0 || n >= (int)sizeof(body))
1460→    {
1461→      return -1;
1462→    }
1463→  syslog(LOG_INFO, "[dm-voice] chat completion request start\n");
1464→  if (http_post_json("/chat/completions", body, TXT_CHAT) != 0)
1465→    {
1466→      syslog(LOG_ERR, "[dm-voice] chat completion HTTP request failed\n");
1467→      return -1;
1468→    }
1469→
1470→  root = voice_json_load(TXT_CHAT, 64 * 1024);
1471→  if (!root)
1472→    {
1473→      syslog(LOG_ERR, "[dm-voice] chat completion response is not valid JSON\n");
1474→      return -1;
1475→    }
1476→  message = voice_first_message(root);
1477→  content = message ? cJSON_GetObjectItem(message, "content") : NULL;
1478→  if (content && cJSON_IsString(content) && content->valuestring)
1479→    {
1480→      snprintf(out, (size_t)cap, "%s", content->valuestring);
1481→    }
1482→  cJSON_Delete(root);
1483→
1484→  if (out[0])
1485→    {
1486→      syslog(LOG_INFO, "[dm-voice] chat completion success reply_bytes=%u\n",
1487→             (unsigned int)strlen(out));
1488→      dm_chat_hist_push(user, out);
1489→      return 0;
1490→    }
1491→  syslog(LOG_ERR,
1492→         "[dm-voice] chat completion response has no choices[0].message.content\n");
1493→  return -1;
1494→}
