1496→static int tts_synth(const char *text, const char *wav_path,
1497→                     const char *voice_id)
1498→{
1499→  char esc[400];
1500→  char voice_esc[64];
1501→  char body[1000];
1502→  unsigned char *raw = NULL;
1503→  FILE *f = NULL;
1504→  long sz;
1505→  int n;
1506→  int rawlen;
1507→  int write_ok;
1508→  int close_rc;
1509→  int rc = -1;
1510→  cJSON *root = NULL;
1511→  cJSON *message;
1512→  cJSON *audio;
1513→  cJSON *data;
1514→
1515→  if (!text || !text[0] || !wav_path || !voice_id || !voice_id[0])
1516→    {
1517→      return -1;
1518→    }
1519→  if (json_escape(text, esc, sizeof(esc)) < 0 ||
1520→      json_escape(voice_id, voice_esc, sizeof(voice_esc)) < 0)
1521→    {
1522→      return -1;
1523→    }
1524→  n = snprintf(body, sizeof(body),
1525→               "{\"model\":\"%s\",\"messages\":["
1526→               "{\"role\":\"user\",\"content\":\"请使用指定音色，以自然清晰的语气朗读。\"},"
1527→               "{\"role\":\"assistant\",\"content\":\"%s\"}],"
1528→               "\"audio\":{\"format\":\"wav\",\"voice\":\"%s\"}}",
1529→               TTS_MODEL, esc, voice_esc);
1530→  if (n <= 0 || n >= (int)sizeof(body))
1531→    {
1532→      return -1;
1533→    }
1534→  syslog(LOG_INFO, "[dm-voice] TTS request start\n");
1535→  if (http_post_json("/chat/completions", body, TXT_CHAT) != 0)
1536→    {
1537→      syslog(LOG_ERR, "[dm-voice] TTS HTTP request failed\n");
1538→      return -1;
1539→    }
1540→
1541→  root = voice_json_load(TXT_CHAT, 4 * 1024 * 1024);
1542→  if (!root)
1543→    {
1544→      goto out;
1545→    }
1546→  message = voice_first_message(root);
1547→  audio = message ? cJSON_GetObjectItem(message, "audio") : NULL;
1548→  data = audio ? cJSON_GetObjectItem(audio, "data") : NULL;
1549→  if (!data || !cJSON_IsString(data) || !data->valuestring)
1550→    {
1551→      goto out;
1552→    }
1553→
1554→  sz = (long)strlen(data->valuestring);
1555→  if (sz <= 0 || sz > 4 * 1024 * 1024)
1556→    {
1557→      goto out;
1558→    }
1559→  raw = malloc((size_t)sz);
1560→  if (!raw)
1561→    {
1562→      goto out;
1563→    }
1564→  rawlen = b64_decode(data->valuestring, raw, (size_t)sz);
1565→  if (rawlen < 44 || memcmp(raw, "RIFF", 4) != 0 ||
1566→      memcmp(raw + 8, "WAVE", 4) != 0)
1567→    {
1568→      goto out;
1569→    }
1570→
1571→  f = fopen(wav_path, "wb");
1572→  if (!f)
1573→    {
1574→      goto out;
1575→    }
1576→  write_ok = fwrite(raw, 1, (size_t)rawlen, f) == (size_t)rawlen;
1577→  close_rc = fclose(f);
1578→  f = NULL;
1579→  if (write_ok && close_rc == 0)
1580→    {
1581→      rc = 0;
1582→      syslog(LOG_INFO, "[dm-voice] TTS WAV decoded bytes=%d\n", rawlen);
1583→    }
1584→
1585→out:
1586→  if (f)
1587→    {
1588→      fclose(f);
1589→    }
1590→  free(raw);
1591→  if (root)
1592→    {
1593→      cJSON_Delete(root);
1594→    }
1595→  if (rc != 0)
1596→    {
1597→      syslog(LOG_ERR, "[dm-voice] TTS response missing/invalid WAV data\n");
1598→      unlink(wav_path);
1599→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1600→        {
1601→          s_last_failure = DM_VOICE_FAILURE_TTS;
1602→        }
1603→    }
1604→  return rc;
1605→}
