439→  s_last_reply[0] = '\0';
440→  s_last_request_remote_ok = 0;
441→  if (!user_text || !user_text[0])
442→    {
443→      return local_reply("");
444→    }
445→
446→  if (!dm_wifi_connected())
447→    {
448→      strncpy(s_last_reply, local_reply(user_text), sizeof(s_last_reply) - 1);
449→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
450→      return s_last_reply;
451→    }
452→
453→  /* Do not send HTTPS while the board clock is still at its boot epoch;
454→   * this causes mbedTLS to reject valid certificates as not-yet-valid. */
455→  if (dm_wifi_wait_time_sync(40) != 0)
456→    {
457→      syslog(LOG_WARNING, "[dm-chat] system clock not synchronized\n");
458→      strncpy(s_last_reply, local_reply(user_text), sizeof(s_last_reply) - 1);
459→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
460→      return s_last_reply;
461→    }
462→
463→  if (json_escape(user_text, esc, sizeof(esc)) < 0)
464→    {
465→      return local_reply(user_text);
466→    }
467→
468→  persona_src = s_persona_ctx[0] ? s_persona_ctx
469→                                 : "你是openvela小助手，桌边陪伴助手，回答简洁温暖，不超过80字，用中文。";
470→  if (json_escape(persona_src, persona, sizeof(persona)) < 0)
471→    {
472→      return local_reply(user_text);
473→    }
474→
475→  dm_chat_hist_json(hist, sizeof(hist));
476→  n = snprintf(body, sizeof(body),
477→               "{\"model\":\"%s\",\"messages\":["
478→               "{\"role\":\"system\",\"content\":\"%s\"},"
479→               "%s"
480→               "{\"role\":\"user\",\"content\":\"%s\"}],"
481→               "\"max_completion_tokens\":400,\"thinking\":{\"type\":\"disabled\"}}",
482→               MIMO_MODEL, persona, hist, esc);
483→  if (n <= 0 || n >= (int)sizeof(body))
484→    {
485→      return local_reply(user_text);
486→    }
487→
488→  f = fopen(CHAT_REQ_PATH, "w");
489→  if (!f)
490→    {
491→      syslog(LOG_ERR, "[dm-chat] cannot create request body errno=%d\n", errno);
492→      return local_reply(user_text);
493→    }
494→  write_ok = fwrite(body, 1, (size_t)n, f) == (size_t)n;
495→  close_rc = fclose(f);
496→  if (!write_ok || close_rc != 0)
497→    {
498→      syslog(LOG_ERR, "[dm-chat] cannot write request body\n");
499→      return local_reply(user_text);
500→    }
501→
502→  unlink(CHAT_RSP_PATH);
503→  curl_rc = run_curl_command(MIMO_BASE "/chat/completions",
504→                             CHAT_REQ_PATH, CHAT_RSP_PATH, 20);
505→  if (curl_rc != 0)
506→    {
507→      syslog(LOG_WARNING,
508→             "[dm-chat] HTTP request failed; inspect curl output/status above\n");
509→      strncpy(s_last_reply, local_reply(user_text),
510→              sizeof(s_last_reply) - 1);
511→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
512→      return s_last_reply;
513→    }
514→  syslog(LOG_INFO, "[dm-chat] HTTP request completed\n");
515→
516→  extract_content(CHAT_RSP_PATH, s_last_reply, sizeof(s_last_reply));
517→  if (s_last_reply[0])
518→    {
519→      s_last_request_remote_ok = 1;
520→      dm_chat_hist_push(user_text, s_last_reply);
521→    }
522→  else
523→    {
524→      strncpy(s_last_reply, local_reply(user_text),
525→              sizeof(s_last_reply) - 1);
526→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
527→    }
528→  return s_last_reply;
529→}
530→
531→const char *dm_chat_local_reply(const char *user_text)
532→{
533→  return local_reply(user_text);
534→}
