293→static void note_paint_cands(void)
294→{
295→  py_cand_t c[NOTE_CAND_MAX];
296→  int n;
297→  int i, j;
298→  int x = 0;
299→
300→  if (!s_kb_cand)
301→    {
302→      return;
303→    }
304→  lv_obj_clean(s_kb_cand);
305→  if (s_kb_mode != 0 || s_pin_len == 0)
306→    {
307→      return;
308→    }
309→  n = dm_pinyin_get_cands(s_pin, c, NOTE_CAND_MAX);
310→
311→  /* Show individual characters from each candidate group */
312→  for (i = 0; i < n && x < 280; i++)
313→    {
314→      const char *chars = c[i].chars;
315→      int chars_len = c[i].chars_len;
316→      for (j = 0; j < chars_len && x < 280; j++)
317→        {
318→          char buf[8];
319→          memcpy(buf, chars + j * 3, 3);
320→          buf[3] = 0;
321→          lv_obj_t *b = dm_btn(s_kb_cand, buf, buf, 32, 24, 0x0d3a4a,
322→                               C_ACCENT, note_kb_confirm_cb, (void *)(chars + j * 3));
323→          lv_obj_set_pos(b, x, 0);
324→          x += 34;
325→        }
326→    }
327→}
