225→ * 0→20, 15→~36, 30→~52, 45→~68, 60+→95 */
226→/* ===== multi-factor mood score (v1 board model) ===== */
227→
228→#define MF_WORDS_TARGET 25.0f
229→#define MF_FOCUS_TARGET 150.0f
230→#define MF_WATER_TARGET 8.0f
231→
