704→  items_ok[5] = 1;
705→
706→  for (i = 0; i < n; i++)
707→    {
708→      if (!items_ok[i])
709→        {
710→          continue;
711→        }
712→      acc += items_w[i] * items_s[i];
713→      wsum += items_w[i];
