731→int dm_health_score(void)
732→{
733→  int mood_v;
734→  int beh_v;
735→  int cov = 0;
736→  int nf = 0;
737→
738→  health_rollover_if_new_day();
739→
740→  mood_v = mood_score_from_recs(s_recs, s_rec_n);
741→  beh_v = behavior_score_from_board(&cov, &nf);
742→
743→  s_last_mood_n = s_rec_n;
