518→/* per-record mood score — same as calculateScore in score-detail.ux */
519→static float mood_record_score(const dm_mood_rec_t *rec)
520→{
521→  float base = 50.0f;
522→  int pos = 0;
523→  int neg = 0;
524→  int i;
525→  int ntag = 0;
526→  float tsum = 0.0f;
527→
528→  /* type average */
529→  for (i = 0; i < (int)(sizeof(s_moods) / sizeof(s_moods[0])); i++)
530→    {
531→      if (rec->mood_mask & s_moods[i].bit)
532→        {
533→          tsum += (float)s_moods[i].score;
534→          ntag++;
535→          if (s_moods[i].bit & M_POS_MASK)
536→            {
537→              pos++;
538→            }
539→          if (s_moods[i].bit & M_NEG_MASK)
540→            {
541→              neg++;
542→            }
543→        }
544→    }
545→  if (ntag > 0)
546→    {
547→      base = tsum / (float)ntag;
548→      /* mixed positive+negative: down up to 30% */
549→      if (pos > 0 && neg > 0)
550→        {
551→          float ratio = (float)neg / (float)(pos + neg);
552→          base = base * (1.0f - ratio * 0.3f);
553→        }
554→    }
555→
556→  /* quick text: 30% blend (same as app) */
557→  if (rec->quick > 0 && rec->quick <= DM_QUICK_MAX)
558→    {
559→      float qs = (float)s_quick_score[rec->quick - 1];
560→      base = base * 0.7f + qs * 0.3f;
561→    }
562→
563→  return base;
564→}
