static time_t cd_alarm_time(const cd_item_t *item)
{
  struct tm tmv;

  if (!item || !item->has_alarm)
    {
      return (time_t)-1;
    }
  memset(&tmv, 0, sizeof(tmv));
  tmv.tm_year = item->y - 1900;
  tmv.tm_mon = item->m - 1;
  tmv.tm_mday = item->d;
  tmv.tm_hour = item->hour;
  tmv.tm_min = item->minute;
  tmv.tm_isdst = -1;
  return mktime(&tmv);
}

int dm_countdown_add_voice(const char *name, int year, int month, int day,
                           int hour, int minute)
{
  time_t now = time(NULL);
  struct tm current;
  struct tm target_tm;
  struct tm verify;
  time_t target;
  size_t len;

  if (!name || !name[0] || month < 1 || month > 12 || day < 1 || day > 31 ||
      hour < 0 || hour > 23 || minute < 0 || minute > 59 ||
      year < 2024 || year > 2099)
    {
      return -1;
    }
  if (s_cd_n >= CD_MAX)
    {
      return -2;
    }
  localtime_r(&now, &current);
  if (current.tm_year + 1900 < 2024)
    {
      return -4;
    }

  memset(&target_tm, 0, sizeof(target_tm));
  target_tm.tm_year = year - 1900;
  target_tm.tm_mon = month - 1;
  target_tm.tm_mday = day;
  target_tm.tm_hour = hour;
  target_tm.tm_min = minute;
  target_tm.tm_isdst = -1;
  target = mktime(&target_tm);
  if (target == (time_t)-1)
    {
      return -1;
    }
  localtime_r(&target, &verify);
  if (verify.tm_year != target_tm.tm_year || verify.tm_mon != target_tm.tm_mon ||
      verify.tm_mday != target_tm.tm_mday || verify.tm_hour != hour ||
      verify.tm_min != minute || target <= now)
    {
      return -1;
    }

  len = strlen(name);
  if (len >= CD_NAME_MAX)
    {
      len = CD_NAME_MAX - 1;
      while (len > 0 && ((unsigned char)name[len] & 0xc0u) == 0x80u)
        {
          len--;
        }
    }
  if (len == 0)
    {
      return -1;
    }

  memset(&s_cd[s_cd_n], 0, sizeof(s_cd[s_cd_n]));
  s_cd[s_cd_n].y = year;
  s_cd[s_cd_n].m = month;
  s_cd[s_cd_n].d = day;
  s_cd[s_cd_n].hour = hour;
  s_cd[s_cd_n].minute = minute;
  s_cd[s_cd_n].has_alarm = 1;
  memcpy(s_cd[s_cd_n].name, name, len);
  s_cd[s_cd_n].name[len] = '\0';
  s_cd_sel = s_cd_n;
  s_cd_n++;
  if (cd_save() != 0)
    {
      s_cd_n--;
      memset(&s_cd[s_cd_n], 0, sizeof(s_cd[s_cd_n]));
      return -3;
    }
  cd_paint();
  dm_show(PAGE_COUNTDOWN);
  return 0;
}

