569→static int parse_intent(const char *text, assistant_intent_t *intent)
570→{
571→  static const char *const note_triggers[] = {
572→    "帮我记一下", "记一下", "记下来", "记一个", "记个", "备忘里"
573→  };
574→  static const char *const reminder_triggers[] = {
575→    "提醒", "闹钟", "倒数日", "记一下", "记一个", "计一个", "安排"
576→  };
577→  static const char *const mood_words[] = {
578→    "不开心", "心情不好", "难过", "伤心", "焦虑", "压力大", "很累",
579→    "疲惫", "孤独", "烦躁", "沮丧"
580→  };
581→  const char *day_mark;
582→  size_t date_start = 0;
583→  size_t date_end = 0;
584→  size_t time_start = 0;
585→  size_t time_end = 0;
586→  int has_dt;
587→  int minutes;
588→
589→  memset(intent, 0, sizeof(*intent));
590→
591→  has_dt = parse_datetime(text, &intent->year, &intent->month, &intent->day,
592→                          &intent->hour, &intent->minute, &date_start,
593→                          &date_end, &time_start, &time_end);
594→  if (has_dt == 1 &&
595→      contains_any(text, reminder_triggers,
596→                   sizeof(reminder_triggers) / sizeof(reminder_triggers[0])))
597→    {
598→      intent->type = INTENT_COUNTDOWN;
599→      clean_reminder_name(text, date_start, date_end, time_start, time_end,
600→                          intent->text, sizeof(intent->text));
601→      return 1;
602→    }
603→
604→  if (contains_any(text, note_triggers,
605→                   sizeof(note_triggers) / sizeof(note_triggers[0])))
606→    {
607→      const char *trigger = NULL;
608→      size_t trigger_len = 0;
609→      size_t i;
610→      for (i = 0; i < sizeof(note_triggers) / sizeof(note_triggers[0]); i++)
611→        {
612→          const char *found = strstr(text, note_triggers[i]);
613→          if (found && (!trigger || found < trigger))
614→            {
615→              trigger = found;
616→              trigger_len = strlen(note_triggers[i]);
617→            }
618→        }
619→      if (trigger)
620→        {
621→          const char *content = trigger + trigger_len;
622→          while (*content == ' ' || *content == '\t' || *content == ':' ||
623→                 *content == ',' || *content == '，' || *content == '：')
624→            {
625→              content++;
626→            }
627→          while (strncmp(content, "我", 3) == 0 ||
628→                 strncmp(content, "一下", 6) == 0 ||
629→                 strncmp(content, "记得", 6) == 0)
630→            {
631→              content += strncmp(content, "我", 3) == 0 ? 3 : 6;
632→            }
633→          if (!*content)
634→            {
635→              return 0;
636→            }
637→          intent->type = INTENT_NOTE;
638→          snprintf(intent->text, sizeof(intent->text), "%s", content);
639→          return 1;
640→        }
641→    }
642→
643→  if ((strstr(text, "专注") || strstr(text, "计时") || strstr(text, "番茄钟")) &&
644→      parse_duration_minutes(text, &minutes))
645→    {
646→      intent->type = INTENT_FOCUS;
647→      intent->minutes = minutes;
648→      return 1;
649→    }
650→
651→  if (contains_any(text, mood_words, sizeof(mood_words) / sizeof(mood_words[0])))
652→    {
653→      intent->type = INTENT_MOOD;
654→      snprintf(intent->text, sizeof(intent->text), "%s", text);
655→      return 1;
656→    }
657→
658→  return 0;
659→}
