661→static int run_intent(const assistant_intent_t *intent, char *reply, size_t cap)
662→{
663→  int rc;
664→  switch (intent->type)
665→    {
666→      case INTENT_FOCUS:
667→        rc = dm_focus_start_minutes(intent->minutes);
668→        if (rc == 0)
669→          {
670→            snprintf(reply, cap, "好，%d分钟专注已开始。我陪你。",
