728→int dm_assistant_intent_try(const char *text, char *reply, int reply_cap)
729→{
730→  assistant_intent_t parsed;
731→  int i;
732→
733→  if (!text || !text[0] || !reply || reply_cap < 8 ||
734→      !parse_intent(text, &parsed))
735→    {
736→      return 0;
737→    }
738→
739→  pthread_mutex_lock(&s_intent_lock);
740→  if (s_intent_active)
741→    {
742→      pthread_mutex_unlock(&s_intent_lock);
743→      return 0;
744→    }
745→  s_intent = parsed;
746→  s_intent_active = 1;
747→  s_intent_executing = 0;
748→  s_intent_done = 0;
749→  s_intent_reply[0] = '\0';
750→  pthread_mutex_unlock(&s_intent_lock);
751→
752→  for (i = 0; i < INTENT_WAIT_STEPS; i++)
753→    {
754→      int done;
755→      usleep(INTENT_WAIT_US);
756→      pthread_mutex_lock(&s_intent_lock);
757→      done = s_intent_done;
758→      if (done)
759→        {
760→          snprintf(reply, (size_t)reply_cap, "%s", s_intent_reply);
761→          s_intent_active = 0;
762→          s_intent_done = 0;
763→          pthread_mutex_unlock(&s_intent_lock);
764→          return 1;
765→        }
766→      pthread_mutex_unlock(&s_intent_lock);
767→    }
768→
769→  pthread_mutex_lock(&s_intent_lock);
770→  if (!s_intent_executing)
771→    {
772→      s_intent_active = 0;
773→      s_intent_done = 0;
774→      pthread_mutex_unlock(&s_intent_lock);
775→      return 0;
776→    }
777→  pthread_mutex_unlock(&s_intent_lock);
778→
779→  /* An operation already started on the LVGL thread; allow it to finish. */
780→  for (i = 0; i < 40; i++)
781→    {
782→      usleep(INTENT_WAIT_US);
783→      pthread_mutex_lock(&s_intent_lock);
784→      if (s_intent_done)
785→        {
786→          snprintf(reply, (size_t)reply_cap, "%s", s_intent_reply);
787→          s_intent_active = 0;
788→          s_intent_done = 0;
789→          pthread_mutex_unlock(&s_intent_lock);
790→          return 1;
791→        }
792→      pthread_mutex_unlock(&s_intent_lock);
793→    }
794→  pthread_mutex_lock(&s_intent_lock);
795→  s_intent_active = 0;
796→  s_intent_executing = 0;
797→  s_intent_done = 0;
798→  pthread_mutex_unlock(&s_intent_lock);
799→  return 0;
800→}
