226→static const char *first_of(const char *text, const char *a, const char *b)
227→{
228→  const char *pa = a ? strstr(text, a) : NULL;
229→  const char *pb = b ? strstr(text, b) : NULL;
230→  if (!pa)
231→    {
232→      return pb;
233→    }
234→  if (!pb)
235→    {
236→      return pa;
237→    }
238→  return pa < pb ? pa : pb;
239→}
