469→static void trim_reminder_punctuation(char *text, size_t *len)
470→{
471→  int changed = 1;
472→  while (*len > 0 && changed)
473→    {
474→      changed = 0;
475→      if (text[*len - 1] == ' ' || text[*len - 1] == '\t' ||
476→          text[*len - 1] == ',' || text[*len - 1] == ':' ||
477→          text[*len - 1] == '-' || text[*len - 1] == '.')
478→        {
479→          text[--(*len)] = '\0';
480→          changed = 1;
481→        }
482→      else if (*len >= 3 &&
483→               (memcmp(text + *len - 3, "。", 3) == 0 ||
484→                memcmp(text + *len - 3, "，", 3) == 0 ||
485→                memcmp(text + *len - 3, "！", 3) == 0 ||
486→                memcmp(text + *len - 3, "？", 3) == 0 ||
487→                memcmp(text + *len - 3, "；", 3) == 0 ||
488→                memcmp(text + *len - 3, "：", 3) == 0))
489→        {
490→          *len -= 3;
491→          text[*len] = '\0';
492→          changed = 1;
493→        }
494→    }
495→}
