497→static void clean_reminder_name(const char *text, size_t date_start,
498→                                size_t date_end, size_t time_start,
499→                                size_t time_end, char *out, size_t cap)
500→{
501→  char tmp[INTENT_TEXT_MAX];
502→  size_t len = strlen(text);
503→  size_t start = date_start;
504→  size_t end = date_end;
505→  size_t tstart = time_start;
506→  size_t tend = time_end;
507→  size_t out_len = 0;
508→  static const char *const leading[] = {
509→    "帮我设置提醒", "提醒一下", "提醒我", "我提醒我", "倒数日",
510→    "记一个", "计一个", "记一下", "记下来", "在", "请", "把", "到时候"
511→  };
512→  size_t i;
513→
514→  if (len >= sizeof(tmp))
515→    {
516→      len = sizeof(tmp) - 1;
517→    }
518→  memcpy(tmp, text, len);
519→  tmp[len] = '\0';
520→
521→  if (tstart >= end)
522→    {
523→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
524→      len -= tend - tstart;
525→      memmove(tmp + start, tmp + end, len - end + 1);
526→      len -= end - start;
527→    }
528→  else if (start >= tend)
529→    {
530→      memmove(tmp + start, tmp + end, len - end + 1);
531→      len -= end - start;
532→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
533→      len -= tend - tstart;
534→    }
535→  else
536→    {
537→      memmove(tmp + start, tmp + end, len - end + 1);
538→      len -= end - start;
539→      if (tstart > end)
540→        {
541→          tstart -= end - start;
542→          tend -= end - start;
543→        }
544→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
545→      len -= tend - tstart;
546→    }
547→
548→  while (len > 0)
549→    {
550→      int changed = 0;
551→      while (len > 0 && (tmp[0] == ' ' || tmp[0] == '\t' || tmp[0] == ',' ||
552→                         tmp[0] == ':' || tmp[0] == '-'))
553→        {
554→          memmove(tmp, tmp + 1, len);
555→          len--;
556→        }
557→      for (i = 0; i < sizeof(leading) / sizeof(leading[0]); i++)
558→        {
559→          size_t n = strlen(leading[i]);
560→          if (len >= n && memcmp(tmp, leading[i], n) == 0)
561→            {
562→              memmove(tmp, tmp + n, len - n + 1);
563→              len -= n;
564→              changed = 1;
565→              break;
566→            }
567→        }
568→      if (!changed)
569→        {
570→          break;
571→        }
572→    }
573→  trim_reminder_punctuation(tmp, &len);
574→
575→  if (len == 0)
576→    {
577→      snprintf(out, cap, "%s", "提醒事项");
578→      return;
579→    }
580→  out_len = len < cap - 1 ? len : cap - 1;
581→  if (out_len < len)
582→    {
583→      while (out_len > 0 && ((unsigned char)tmp[out_len] & 0xc0u) == 0x80u)
584→        {
585→          out_len--;
586→        }
587→    }
588→  memcpy(out, tmp, out_len);
589→  out[out_len] = '\0';
590→}
