750→int dm_assistant_intent_try(const char *text, char *reply, int reply_cap)
751→{
752→  assistant_intent_t parsed;
753→  int i;
754→
755→  if (!text || !text[0] || !reply || reply_cap < 8 ||
756→      !parse_intent(text, &parsed))
757→    {
758→      return 0;
759→    }
760→
761→  pthread_mutex_lock(&s_intent_lock);
762→  if (s_intent_active)
763→    {
764→      pthread_mutex_unlock(&s_intent_lock);
765→      return 0;
766→    }
767→  s_intent = parsed;
768→  s_intent_active = 1;
769→  s_intent_executing = 0;
770→  s_intent_done = 0;
771→  s_intent_reply[0] = '\0';
772→  pthread_mutex_unlock(&s_intent_lock);
773→
774→  for (i = 0; i < INTENT_WAIT_STEPS; i++)
775→    {
776→      int done;
777→      usleep(INTENT_WAIT_US);
778→      pthread_mutex_lock(&s_intent_lock);
779→      done = s_intent_done;
780→      if (done)
781→        {
782→          snprintf(reply, (size_t)reply_cap, "%s", s_intent_reply);
783→          s_intent_active = 0;
784→          s_intent_done = 0;
785→          pthread_mutex_unlock(&s_intent_lock);
786→          return 1;
787→        }
788→      pthread_mutex_unlock(&s_intent_lock);
789→    }
790→
791→  pthread_mutex_lock(&s_intent_lock);
792→  if (!s_intent_executing)
793→    {
794→      s_intent_active = 0;
795→      s_intent_done = 0;
796→      pthread_mutex_unlock(&s_intent_lock);
797→      return 0;
798→    }
799→  pthread_mutex_unlock(&s_intent_lock);
800→
801→  /* An operation already started on the LVGL thread; allow it to finish. */
802→  for (i = 0; i < 40; i++)
803→    {
804→      usleep(INTENT_WAIT_US);
805→      pthread_mutex_lock(&s_intent_lock);
806→      if (s_intent_done)
807→        {
808→          snprintf(reply, (size_t)reply_cap, "%s", s_intent_reply);
809→          s_intent_active = 0;
810→          s_intent_done = 0;
811→          pthread_mutex_unlock(&s_intent_lock);
812→          return 1;
813→        }
814→      pthread_mutex_unlock(&s_intent_lock);
815→    }
816→  pthread_mutex_lock(&s_intent_lock);
817→  s_intent_active = 0;
818→  s_intent_executing = 0;
819→  s_intent_done = 0;
820→  pthread_mutex_unlock(&s_intent_lock);
821→  return 0;
822→}
