827→  char reply[INTENT_REPLY_MAX];
828→
829→  pthread_mutex_lock(&s_intent_lock);
830→  if (!s_intent_active || s_intent_executing || s_intent_done)
831→    {
832→      pthread_mutex_unlock(&s_intent_lock);
833→      return;
834→    }
