473→static void trim_reminder_punctuation(char *text, size_t *len)
474→{
475→  int changed = 1;
476→  while (*len > 0 && changed)
477→    {
478→      changed = 0;
479→      if (text[*len - 1] == ' ' || text[*len - 1] == '\t' ||
480→          text[*len - 1] == ',' || text[*len - 1] == ':' ||
481→          text[*len - 1] == '-' || text[*len - 1] == '.')
482→        {
483→          text[--(*len)] = '\0';
484→          changed = 1;
485→        }
486→      else if (*len >= 3 &&
487→               (memcmp(text + *len - 3, "。", 3) == 0 ||
488→                memcmp(text + *len - 3, "，", 3) == 0 ||
489→                memcmp(text + *len - 3, "！", 3) == 0 ||
490→                memcmp(text + *len - 3, "？", 3) == 0 ||
491→                memcmp(text + *len - 3, "；", 3) == 0 ||
492→                memcmp(text + *len - 3, "：", 3) == 0))
493→        {
494→          *len -= 3;
495→          text[*len] = '\0';
496→          changed = 1;
497→        }
498→    }
499→}
