501→static void clean_reminder_name(const char *text, size_t date_start,
502→                                size_t date_end, size_t time_start,
503→                                size_t time_end, char *out, size_t cap)
504→{
505→  char tmp[INTENT_TEXT_MAX];
506→  size_t len = strlen(text);
507→  size_t start = date_start;
508→  size_t end = date_end;
509→  size_t tstart = time_start;
510→  size_t tend = time_end;
511→  size_t out_len = 0;
512→  static const char *const leading[] = {
513→    "帮我设置提醒", "提醒一下", "提醒我", "我提醒我", "倒数日",
514→    "记一个", "计一个", "记一下", "记下来", "在", "请", "把", "到时候"
515→  };
516→  size_t i;
517→
518→  if (len >= sizeof(tmp))
519→    {
520→      len = sizeof(tmp) - 1;
521→    }
522→  memcpy(tmp, text, len);
523→  tmp[len] = '\0';
524→
525→  if (tstart >= end)
526→    {
527→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
528→      len -= tend - tstart;
529→      memmove(tmp + start, tmp + end, len - end + 1);
530→      len -= end - start;
531→    }
532→  else if (start >= tend)
533→    {
534→      memmove(tmp + start, tmp + end, len - end + 1);
535→      len -= end - start;
536→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
537→      len -= tend - tstart;
538→    }
539→  else
540→    {
541→      memmove(tmp + start, tmp + end, len - end + 1);
542→      len -= end - start;
543→      if (tstart > end)
544→        {
545→          tstart -= end - start;
546→          tend -= end - start;
547→        }
548→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
549→      len -= tend - tstart;
550→    }
551→
552→  while (len > 0)
553→    {
554→      int changed = 0;
555→      while (len > 0 && (tmp[0] == ' ' || tmp[0] == '\t' || tmp[0] == ',' ||
556→                         tmp[0] == ':' || tmp[0] == '-'))
557→        {
558→          memmove(tmp, tmp + 1, len);
559→          len--;
560→        }
561→      for (i = 0; i < sizeof(leading) / sizeof(leading[0]); i++)
562→        {
563→          size_t n = strlen(leading[i]);
564→          if (len >= n && memcmp(tmp, leading[i], n) == 0)
565→            {
566→              memmove(tmp, tmp + n, len - n + 1);
567→              len -= n;
568→              changed = 1;
569→              break;
570→            }
571→        }
572→      if (!changed)
573→        {
574→          break;
575→        }
576→    }
577→  trim_reminder_punctuation(tmp, &len);
578→
579→  if (len == 0)
580→    {
581→      snprintf(out, cap, "%s", "提醒事项");
582→      return;
583→    }
584→  out_len = len < cap - 1 ? len : cap - 1;
585→  if (out_len < len)
586→    {
587→      while (out_len > 0 && ((unsigned char)tmp[out_len] & 0xc0u) == 0x80u)
588→        {
589→          out_len--;
590→        }
591→    }
592→  memcpy(out, tmp, out_len);
593→  out[out_len] = '\0';
594→}
