242→static int parse_duration_minutes(const char *text, int *minutes)
243→{
244→  const char *hour_word = strstr(text, "小时");
245→  const char *minute_word = strstr(text, "分钟");
246→  const char *short_minute = strstr(text, "分");
247→  const char *unit;
248→  size_t start;
249→  int number;
250→  int multiplier;
251→
252→  if (strstr(text, "半小时"))
253→    {
254→      *minutes = 30;
255→      return 1;
256→    }
257→  if (hour_word && (!minute_word || hour_word < minute_word))
258→    {
259→      unit = hour_word;
260→      multiplier = 60;
261→    }
262→  else
263→    {
264→      unit = minute_word ? minute_word : short_minute;
265→      multiplier = 1;
266→    }
267→  if (!unit)
268→    {
269→      return 0;
270→    }
271→  if (!parse_number_before(text, (size_t)(unit - text), &start, &number))
272→    {
273→      /* Accept the natural Mandarin form "一个小时". */
274→      if (multiplier == 60 && unit >= text + 3 &&
275→          memcmp(unit - 3, "个", 3) == 0 &&
276→          parse_number_before(text, (size_t)(unit - text - 3), &start,
277→                              &number))
278→        {
279→          /* parsed the number before 个 */
280→        }
281→      else
282→        {
283→          return 0;
284→        }
285→    }
286→  if (number < 1 || number > 120)
287→    {
288→      return 0;
289→    }
290→  *minutes = number * multiplier;
291→  if (*minutes > 120)
292→    {
293→      return 0;
294→    }
295→  return 1;
296→}
297→
298→static int parse_datetime(const char *text, int *year, int *month, int *day,
299→                          int *hour, int *minute, size_t *date_start,
300→                          size_t *date_end, size_t *time_start,
301→                          size_t *time_end)
302→{
303→  const char *day_mark = first_of(text, "号", "日");
304→  const char *month_mark = strstr(text, "月");
305→  const char *time_mark;
306→  const char *minute_mark;
307→  const char *year_mark;
308→  size_t year_start = 0;
309→  size_t day_start;
310→  size_t hour_start;
311→  size_t month_start = 0;
312→  int explicit_month = 0;
313→  int explicit_year = 0;
314→  int month_value = 0;
315→  int year_value = 0;
316→  int day_value;
317→  int hour_value;
318→  int minute_value = 0;
319→  time_t now;
320→  struct tm current;
321→  struct tm target_tm;
322→  time_t target;
323→  struct tm verify;
324→  int attempt;
325→  int resolved = 0;
326→
327→  if (!day_mark || !parse_number_before(text, (size_t)(day_mark - text),
328→                                        &day_start, &day_value) ||
329→      day_value < 1 || day_value > 31)
330→    {
331→      return 0;
332→    }
333→  if (month_mark && month_mark < day_mark &&
334→      parse_number_before(text, (size_t)(month_mark - text), &month_start,
335→                          &month_value) && month_value >= 1 &&
336→      month_value <= 12)
337→    {
338→      explicit_month = 1;
339→    }
340→  else
341→    {
342→      month_mark = NULL;
343→    }
344→
345→  year_mark = month_mark ? strstr(text, "年") : NULL;
346→  if (year_mark && year_mark < month_mark &&
347→      parse_number_before(text, (size_t)(year_mark - text), &year_start,
348→                          &year_value) && year_value >= 2024 &&
349→      year_value <= 2099)
350→    {
351→      explicit_year = 1;
352→    }
353→  time_mark = first_of(day_mark + 3, "点", "时");
354→  if (!time_mark ||
355→      !parse_number_before(text, (size_t)(time_mark - text), &hour_start,
356→                           &hour_value) || hour_value < 0 || hour_value > 23)
357→    {
358→      return 0;
359→    }
360→
361→  minute_value = 0;
362→  minute_mark = strstr(time_mark + 3, "分");
363→  if (minute_mark)
364→    {
365→      size_t minute_start;
366→      int parsed_minute;
367→      if (parse_number_before(text, (size_t)(minute_mark - text),
368→                              &minute_start, &parsed_minute) &&
369→          minute_start >= (size_t)(time_mark + 3 - text) &&
370→          parsed_minute >= 0 && parsed_minute <= 59)
371→        {
372→          minute_value = parsed_minute;
373→        }
374→      else
375→        {
376→          minute_mark = NULL;
377→        }
378→    }
379→  else if (strncmp(time_mark + 3, "半", 3) == 0)
380→    {
381→      minute_value = 30;
382→    }
383→
384→  now = time(NULL);
385→  localtime_r(&now, &current);
386→  if (current.tm_year + 1900 < 2024)
387→    {
388→      return -1;
389→    }
390→  *year = explicit_year ? year_value : current.tm_year + 1900;
391→  *month = explicit_month ? month_value : current.tm_mon + 1;
392→  *day = day_value;
393→  *hour = hour_value;
394→  *minute = minute_value;
395→
396→  /* For an omitted month, roll forward to the next valid occurrence. This
397→   * also handles dates such as the 31st when the current month is shorter. */
398→  for (attempt = 0; attempt < (explicit_year ? 1 : 12); attempt++)
399→    {
400→      memset(&target_tm, 0, sizeof(target_tm));
401→      target_tm.tm_year = *year - 1900;
402→      target_tm.tm_mon = *month - 1;
403→      target_tm.tm_mday = *day;
404→      target_tm.tm_hour = *hour;
405→      target_tm.tm_min = *minute;
406→      target_tm.tm_isdst = -1;
407→      target = mktime(&target_tm);
408→      if (target != (time_t)-1)
409→        {
410→          localtime_r(&target, &verify);
411→          if (verify.tm_year == *year - 1900 &&
412→              verify.tm_mon == *month - 1 && verify.tm_mday == *day &&
413→              verify.tm_hour == *hour && verify.tm_min == *minute &&
414→              (explicit_year || target > now))
415→            {
416→              resolved = 1;
417→              break;
418→            }
419→        }
420→
421→      if (explicit_year)
422→        {
423→          break;
424→        }
425→      if (explicit_month)
426→        {
427→          (*year)++;
428→        }
429→      else
430→        {
431→          (*month)++;
432→          if (*month > 12)
433→            {
434→              *month = 1;
435→              (*year)++;
436→            }
437→        }
438→    }
439→  if (!resolved)
440→    {
441→      return 0;
442→    }
443→
444→  if (date_start)
445→    {
446→      *date_start = explicit_year ? year_start
447→                                  : (explicit_month ? month_start : day_start);
448→    }
449→  if (date_end)
450→    {
451→      *date_end = (size_t)(day_mark - text) + 3;
452→    }
453→  if (time_start)
454→    {
455→      *time_start = hour_start;
456→    }
457→  if (time_end)
458→    {
459→      *time_end = (minute_mark ? (size_t)(minute_mark - text) + 3
460→                               : (size_t)(time_mark - text) + 3 +
461→                                 (minute_value == 30 ? 3 : 0));
462→    }
463→  return 1;
464→}
