466→static void trim_reminder_punctuation(char *text, size_t *len)
467→{
468→  int changed = 1;
469→  while (*len > 0 && changed)
470→    {
471→      changed = 0;
472→      if (text[*len - 1] == ' ' || text[*len - 1] == '\t' ||
473→          text[*len - 1] == ',' || text[*len - 1] == ':' ||
474→          text[*len - 1] == '-' || text[*len - 1] == '.')
475→        {
476→          text[--(*len)] = '\0';
477→          changed = 1;
478→        }
479→      else if (*len >= 3 &&
480→               (memcmp(text + *len - 3, "。", 3) == 0 ||
481→                memcmp(text + *len - 3, "，", 3) == 0 ||
482→                memcmp(text + *len - 3, "！", 3) == 0 ||
483→                memcmp(text + *len - 3, "？", 3) == 0 ||
484→                memcmp(text + *len - 3, "；", 3) == 0 ||
485→                memcmp(text + *len - 3, "：", 3) == 0))
486→        {
487→          *len -= 3;
488→          text[*len] = '\0';
489→          changed = 1;
490→        }
491→    }
492→}
493→
494→static void trim_reminder_clutter(char *text, size_t *len)
495→{
496→  static const char *const suffixes[] = {
497→    "提醒我", "提醒一下", "帮我提醒", "到时候", "请", "在"
498→  };
499→  size_t i;
500→  int changed = 1;
501→
502→  while (*len > 0 && changed)
503→    {
504→      changed = 0;
505→      for (i = 0; i < sizeof(suffixes) / sizeof(suffixes[0]); i++)
506→        {
507→          size_t n = strlen(suffixes[i]);
508→          if (*len >= n && memcmp(text + *len - n, suffixes[i], n) == 0)
509→            {
510→              *len -= n;
511→              text[*len] = '\0';
512→              trim_reminder_punctuation(text, len);
513→              changed = 1;
514→              break;
515→            }
516→        }
517→    }
518→}
