624→static int parse_intent(const char *text, assistant_intent_t *intent)
625→{
626→  static const char *const note_triggers[] = {
627→    "帮我记一下", "帮我记下", "记一下", "记下来", "记下", "记一个",
628→    "记个", "备忘里"
629→  };
630→  static const char *const reminder_triggers[] = {
631→    "提醒", "闹钟", "倒数日", "记一下", "记一个", "计一个", "安排",
632→    "设置提醒", "设个提醒"
633→  };
634→  static const char *const mood_words[] = {
635→    "不开心", "不高兴", "心情不好", "心情差", "情绪低落", "难受",
636→    "难过", "伤心", "焦虑", "压力大", "很累", "疲惫", "孤独",
637→    "烦躁", "沮丧"
638→  };
639→  static const char *const no_reminder[] = {
640→    "不要提醒", "别提醒", "不用提醒", "取消提醒", "不要闹钟", "取消闹钟"
641→  };
642→  static const char *const no_focus[] = {
643→    "不要专注", "别专注", "不用专注", "取消专注", "不要计时", "别计时"
644→  };
645→  size_t date_start = 0;
646→  size_t date_end = 0;
647→  size_t time_start = 0;
648→  size_t time_end = 0;
649→  int has_dt;
650→  int minutes;
651→  int cancel_reminder;
652→  int cancel_focus;
653→
654→  memset(intent, 0, sizeof(*intent));
655→  cancel_reminder = contains_any(
656→      text, no_reminder, sizeof(no_reminder) / sizeof(no_reminder[0]));
657→  cancel_focus = contains_any(text, no_focus,
658→                              sizeof(no_focus) / sizeof(no_focus[0]));
659→
660→  has_dt = parse_datetime(text, &intent->year, &intent->month, &intent->day,
661→                          &intent->hour, &intent->minute, &date_start,
662→                          &date_end, &time_start, &time_end);
663→  if (has_dt < 0 && !cancel_reminder &&
664→      contains_any(text, reminder_triggers,
665→                   sizeof(reminder_triggers) / sizeof(reminder_triggers[0])))
666→    {
667→      intent->type = INTENT_TIME_ERROR;
668→      return 1;
669→    }
670→  if (has_dt == 1 && !cancel_reminder &&
671→      contains_any(text, reminder_triggers,
672→                   sizeof(reminder_triggers) / sizeof(reminder_triggers[0])))
673→    {
674→      intent->type = INTENT_COUNTDOWN;
675→      clean_reminder_name(text, date_start, date_end, time_start, time_end,
676→                          intent->text, sizeof(intent->text));
677→      return 1;
678→    }
679→
680→  if (contains_any(text, note_triggers,
681→                   sizeof(note_triggers) / sizeof(note_triggers[0])))
682→    {
683→      const char *trigger = NULL;
684→      size_t trigger_len = 0;
685→      size_t i;
686→      for (i = 0; i < sizeof(note_triggers) / sizeof(note_triggers[0]); i++)
687→        {
688→          const char *found = strstr(text, note_triggers[i]);
689→          if (found && (!trigger || found < trigger))
690→            {
691→              trigger = found;
692→              trigger_len = strlen(note_triggers[i]);
693→            }
694→        }
695→      if (trigger)
696→        {
697→          const char *content = trigger + trigger_len;
698→          while (*content == ' ' || *content == '\t' || *content == ':' ||
699→                 *content == ',')
700→            {
701→              content++;
702→            }
703→          while (strncmp(content, "，", 3) == 0 ||
704→                 strncmp(content, "：", 3) == 0 ||
705→                 strncmp(content, "、", 3) == 0)
706→            {
707→              content += 3;
708→            }
709→          while (strncmp(content, "我", 3) == 0 ||
710→                 strncmp(content, "一下", 6) == 0 ||
711→                 strncmp(content, "记得", 6) == 0)
712→            {
713→              content += strncmp(content, "我", 3) == 0 ? 3 : 6;
714→            }
715→          if (!*content)
716→            {
717→              return 0;
718→            }
719→          intent->type = INTENT_NOTE;
720→          snprintf(intent->text, sizeof(intent->text), "%s", content);
721→          return 1;
722→        }
723→    }
724→
725→  if (!cancel_focus &&
726→      (strstr(text, "专注") || strstr(text, "计时") || strstr(text, "番茄钟")) &&
727→      parse_duration_minutes(text, &minutes))
728→    {
729→      intent->type = INTENT_FOCUS;
730→      intent->minutes = minutes;
731→      return 1;
732→    }
733→
734→  if (contains_any(text, mood_words, sizeof(mood_words) / sizeof(mood_words[0])))
735→    {
736→      intent->type = INTENT_MOOD;
737→      snprintf(intent->text, sizeof(intent->text), "%s", text);
738→      return 1;
739→    }
740→
741→  return 0;
742→}
