815→int dm_assistant_intent_try(const char *text, char *reply, int reply_cap)
816→{
817→  assistant_intent_t parsed;
818→  int i;
819→
820→  if (!text || !text[0] || !reply || reply_cap < 8 ||
821→      !parse_intent(text, &parsed))
822→    {
823→      return 0;
824→    }
825→
826→  pthread_mutex_lock(&s_intent_lock);
827→  if (s_intent_active)
828→    {
829→      pthread_mutex_unlock(&s_intent_lock);
830→      return 0;
831→    }
832→  s_intent = parsed;
833→  s_intent_active = 1;
834→  s_intent_executing = 0;
835→  s_intent_done = 0;
836→  s_intent_reply[0] = '\0';
837→  pthread_mutex_unlock(&s_intent_lock);
838→
839→  for (i = 0; i < INTENT_WAIT_STEPS; i++)
840→    {
841→      int done;
842→      usleep(INTENT_WAIT_US);
843→      pthread_mutex_lock(&s_intent_lock);
844→      done = s_intent_done;
845→      if (done)
846→        {
847→          snprintf(reply, (size_t)reply_cap, "%s", s_intent_reply);
848→          s_intent_active = 0;
849→          s_intent_done = 0;
850→          pthread_mutex_unlock(&s_intent_lock);
851→          return 1;
852→        }
853→      pthread_mutex_unlock(&s_intent_lock);
854→    }
855→
856→  pthread_mutex_lock(&s_intent_lock);
857→  if (!s_intent_executing)
858→    {
859→      s_intent_active = 0;
860→      s_intent_done = 0;
861→      pthread_mutex_unlock(&s_intent_lock);
862→      return 0;
863→    }
864→  pthread_mutex_unlock(&s_intent_lock);
865→
866→  /* An operation already started on the LVGL thread; allow it to finish. */
867→  for (i = 0; i < 40; i++)
868→    {
869→      usleep(INTENT_WAIT_US);
870→      pthread_mutex_lock(&s_intent_lock);
871→      if (s_intent_done)
872→        {
873→          snprintf(reply, (size_t)reply_cap, "%s", s_intent_reply);
874→          s_intent_active = 0;
875→          s_intent_done = 0;
876→          pthread_mutex_unlock(&s_intent_lock);
877→          return 1;
878→        }
879→      pthread_mutex_unlock(&s_intent_lock);
880→    }
881→  pthread_mutex_lock(&s_intent_lock);
882→  s_intent_active = 0;
883→  s_intent_executing = 0;
884→  s_intent_done = 0;
885→  pthread_mutex_unlock(&s_intent_lock);
886→  return 0;
887→}
888→
889→void dm_assistant_intent_tick(void)
890→{
891→  assistant_intent_t intent;
892→  char reply[INTENT_REPLY_MAX];
893→
894→  pthread_mutex_lock(&s_intent_lock);
895→  if (!s_intent_active || s_intent_executing || s_intent_done)
896→    {
897→      pthread_mutex_unlock(&s_intent_lock);
898→      return;
899→    }
900→  intent = s_intent;
901→  s_intent_executing = 1;
902→  pthread_mutex_unlock(&s_intent_lock);
903→
904→  reply[0] = '\0';
905→  (void)run_intent(&intent, reply, sizeof(reply));
906→
907→  pthread_mutex_lock(&s_intent_lock);
908→  snprintf(s_intent_reply, sizeof(s_intent_reply), "%s", reply);
909→  s_intent_done = 1;
910→  s_intent_executing = 0;
911→  pthread_mutex_unlock(&s_intent_lock);
912→}
