106→void dm_init_fonts(void)
107→{
108→  const char *paths[] = {
109→    "/data/font/MiSans-Regular.ttf",
110→    "/resource/fonts/MiSans-Normal.ttf",
111→    "/resource/fonts/MiSans-Regular.ttf",
112→  };
113→  int i;
114→
115→  g_dm_font_s = NULL;
116→  g_dm_font_m = NULL;
117→  g_dm_font_l = NULL;
118→  g_dm_font_xl = NULL;
119→
120→  for (i = 0; i < 3 && !g_dm_font_s; i++)
121→    {
122→      g_dm_font_s = try_ft(paths[i], 12);
123→      if (g_dm_font_s)
124→        {
125→          g_dm_font_m = try_ft(paths[i], 16);
126→          g_dm_font_l = try_ft(paths[i], 20);
127→          g_dm_font_xl = try_ft(paths[i], 42);
128→        }
129→    }
130→
131→  if (!g_dm_font_s)
132→    {
133→      g_dm_font_s = &lv_font_montserrat_12;
134→      g_dm_font_m = &lv_font_montserrat_16;
135→      g_dm_font_l = &lv_font_montserrat_20;
136→      g_dm_font_xl = &lv_font_montserrat_48;
137→    }
