1684→static int voice_tts_play_unlocked(const char *text)
1685→{
1686→  s_last_failure = DM_VOICE_FAILURE_NONE;
1687→  if (!text || !text[0])
1688→    {
1689→      return -1;
1690→    }
1691→  s_st = DM_VOICE_TTS;
1692→  if (tts_synth(text, WAV_TTS, dm_voice_profile_api_id()) != 0)
1693→    {
1694→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1695→        {
1696→          s_last_failure = DM_VOICE_FAILURE_TTS;
1697→        }
1698→      s_st = DM_VOICE_ERR;
1699→      return -1;
1700→    }
1701→  s_st = DM_VOICE_PLAY;
1702→  if (play_wav(WAV_TTS) != 0)
1703→    {
1704→      s_last_failure = DM_VOICE_FAILURE_TTS;
1705→      s_st = DM_VOICE_ERR;
1706→      return -1;
1707→    }
1708→  s_st = DM_VOICE_IDLE;
1709→  return 0;
1710→}
