227→static void kick_job(int job)
228→{
229→  pthread_t th;
230→  pthread_attr_t attr;
231→
232→  if (s_busy)
233→    {
234→      return;
235→    }
236→  s_busy = true;
237→  s_job = job;
238→  s_ui_rec = false;
239→  s_rec_sec = 0;
240→  s_out_ready = 0;
241→  s_out_ans[0] = '\0';
242→  s_out_sub[0] = '\0';
243→
244→  dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
245→  set_ans(job == 1 ? dm_t("识别中…", "Recognizing…")
246→                   : dm_t("思考中…", "Thinking…"));
247→  set_ptt("处理中…", "Working…", C_BTN_HI);
248→
249→  pthread_attr_init(&attr);
250→  pthread_attr_setstacksize(&attr, DM_VOICE_NET_WORKER_STACK);
251→  if (pthread_create(&th, &attr, voice_worker, NULL) == 0)
252→    {
253→      pthread_detach(th);
254→    }
255→  else
256→    {
257→      s_busy = false;
258→      if (job == 1 && dm_voice_rec_active())
259→        {
260→          /* Keep the recording controllable if worker creation failed. */
261→          s_ui_rec = true;
262→          set_ans(dm_t("正在录音，稍后再点结束",
263→                       "Recording; tap stop again"));
264→          set_ptt("结束并发送", "Stop & send", C_HEART);
265→        }
266→      else
267→        {
268→          set_ptt("开始说话", "Start talk", C_BTN);
269→        }
270→    }
271→  pthread_attr_destroy(&attr);
272→}
