287→static void ptt_click(lv_event_t *e)
288→{
289→  int rec_rc;
290→
291→  (void)e;
292→
293→  if (s_busy)
294→    {
295→      return;
296→    }
297→
298→  if (!s_ui_rec)
299→    {
300→      if (!dm_wifi_connected())
301→        {
302→          set_ans(dm_t("Wi-Fi 尚未就绪，请先连接网络",
303→                       "Wi-Fi is not ready; connect first"));
304→          set_sub(dm_t("连接完成后再开始语音聊天",
305→                       "Start voice chat after connection completes"));
306→          set_ptt("开始说话", "Start talk", C_BTN);
307→          return;
308→        }
309→      s_mic_err = 0;
310→      dm_voice_set_speaker_volume(80);
311→      rec_rc = dm_voice_rec_start(6);
312→      if (rec_rc != 0)
313→        {
314→          if (rec_rc == -EBUSY)
315→            {
316→              set_ans(dm_t("音频设备忙，请稍后再试",
317→                           "Audio device busy; try again shortly"));
318→              set_sub(dm_t("等待录音或播放结束", "Wait for recording or playback to finish"));
319→            }
320→          else
321→            {
322→              set_ans(dm_t("麦克风不可用", "Mic unavailable"));
323→              set_sub(dm_t("检查 /dev/audio/pcm0c",
324→                           "Check /dev/audio/pcm0c"));
325→            }
326→          set_ptt("开始说话", "Start talk", C_BTN);
327→          return;
328→        }
329→      s_ui_rec = true;
330→      s_rec_sec = 0;
331→      s_rec_started_ms = chat_monotonic_ms();
332→      dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
333→      set_ans(dm_t("● 录音中… 再点一下结束并发送",
334→                   "● Recording… tap again to send"));
335→      set_sub(dm_t("再点一下结束", "Tap again to stop"));
336→      set_ptt("结束并发送", "Stop & send", C_HEART);
337→    }
338→  else
339→    {
340→      s_ui_rec = false;
341→      s_rec_sec = 0;
342→      set_ptt("发送中…", "Sending…", C_BTN_HI);
343→      set_ans(dm_t("正在结束录音…", "Stopping mic…"));
344→
345→      if (s_mic_err)
346→        {
347→          set_ans(dm_t("麦克风故障，无法录音", "Mic failed"));
348→          set_sub(dm_t("检查 /dev/audio/pcm0c", "Check mic device"));
349→          reset_to_idle();
350→          return;
351→        }
352→
353→      /* Stop/join and network work run in voice_worker, not this LVGL event. */
354→      kick_job(1);
355→    }
356→}
