256→static void calc_back(void)
257→{
258→  size_t n;
259→
260→  if (s_calc_just_eq)
261→    {
262→      calc_reset();
263→      return;
264→    }
265→  if (!s_calc_typing)
266→    {
267→      return;
268→    }
269→  n = strlen(s_calc_cur);
270→  if (n > 1)
271→    {
272→      s_calc_cur[n - 1] = 0;
273→    }
274→  else
275→    {
276→      snprintf(s_calc_cur, sizeof(s_calc_cur), "0");
277→      s_calc_typing = false;
278→    }
279→  calc_show();
280→}
