470→static void sen_try_copy(void)
471→{
472→  struct pollfd fds[3];
473→  int n = 0;
474→  int ti = -1;
475→  int hi = -1;
476→  int li = -1;
477→
478→  sen_init();
479→
480→  if (s_sen_tfd >= 0)
481→    {
482→      ti = n;
483→      fds[n].fd = s_sen_tfd;
484→      fds[n].events = POLLIN;
485→      n++;
486→    }
487→  if (s_sen_hfd >= 0)
488→    {
489→      hi = n;
490→      fds[n].fd = s_sen_hfd;
491→      fds[n].events = POLLIN;
492→      n++;
493→    }
494→  if (s_sen_lfd >= 0)
495→    {
496→      li = n;
497→      fds[n].fd = s_sen_lfd;
498→      fds[n].events = POLLIN;
499→      n++;
500→    }
501→  if (n > 0)
502→    {
503→      /* short wait — real-time, do not block UI long */
504→      (void)poll(fds, n, 20);
505→    }
506→
507→  if (s_sen_tfd >= 0)
508→    {
509→      struct sensor_temp d;
510→      if (orb_copy(ORB_ID(sensor_temp), s_sen_tfd, &d) == OK)
511→        {
512→          s_sen_tv = d.temperature;
513→          s_sen_tok = true;
514→        }
515→    }
516→  if (s_sen_hfd >= 0)
517→    {
518→      struct sensor_humi d;
519→      if (orb_copy(ORB_ID(sensor_humi), s_sen_hfd, &d) == OK)
520→        {
521→          s_sen_hv = d.humidity;
522→          s_sen_hok = true;
523→        }
524→    }
525→  if (s_sen_lfd >= 0)
526→    {
527→      struct sensor_light d;
528→      if (orb_copy(ORB_ID(sensor_light), s_sen_lfd, &d) == OK)
529→        {
530→          s_sen_lv = d.light;
531→          s_sen_lok = true;
532→        }
533→    }
534→  (void)ti;
535→  (void)hi;
536→  (void)li;
537→}
