int dm_focus_start_seconds(int32_t seconds)
{
  int32_t display_minutes;

  if (g_dm.focus_run && !g_dm.focus_finished)
    {
      return -1;
    }
  if (seconds < 1 || seconds > 120 * 60)
    {
