253→  int number;
254→
255→  if (!unit)
256→    {
257→      return 0;
258→    }
259→  if (allow_half_hour && unit_bytes == 6 && unit >= text + 3 &&
260→      memcmp(unit - 3, "半", 3) == 0)
261→    {
262→      *seconds += 30 * 60;
263→      return 1;
264→    }
265→  if (!parse_number_before(text, (size_t)(unit - text), &start, &number))
