 55→static void roll_digit(dm_digit_t *d, int digit, int w, int h,
 56→                       const lv_font_t *font, bool animate)
 57→{
 58→  lv_anim_t a;
 59→  roll_old_t *ud;
 60→  lv_obj_t *nw;
 61→
 62→  if (!d->clip)
 63→    {
 64→      return;
 65→    }
 66→
 67→  if (digit == d->digit && d->cur)
 68→    {
 69→      return;
 70→    }
 71→
 72→  /* kill in-flight roll on this digit so we never stack labels */
 73→  lv_anim_delete(d->cur, NULL);
 74→
 75→  nw = lv_label_create(d->clip);
 76→  dm_style(nw, font, C_INK);
 77→  set_digit_label(nw, digit);
 78→  lv_obj_set_width(nw, w);
 79→  lv_obj_set_style_text_align(nw, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
 80→
 81→  if (!animate || !d->cur || d->digit < 0)
 82→    {
 83→      if (d->cur && lv_obj_is_valid(d->cur))
 84→        {
 85→          lv_obj_delete(d->cur);
 86→        }
 87→      lv_obj_set_pos(nw, 0, 0);
 88→      d->cur = nw;
 89→      d->digit = digit;
 90→      return;
 91→    }
 92→
 93→  ud = lv_malloc(sizeof(roll_old_t));
 94→  if (!ud)
 95→    {
 96→      lv_obj_delete(d->cur);
 97→      lv_obj_set_pos(nw, 0, 0);
 98→      d->cur = nw;
 99→      d->digit = digit;
100→      return;
101→    }
102→
103→  ud->old = d->cur;
104→  d->cur = nw;
105→  d->digit = digit;
106→
107→  lv_obj_set_pos(nw, 0, h);
108→  lv_anim_init(&a);
109→  lv_anim_set_var(&a, nw);
110→  lv_anim_set_values(&a, h, 0);
111→  lv_anim_set_time(&a, 170);
112→  lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_y);
113→  lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
114→  lv_anim_start(&a);
115→
116→  lv_anim_init(&a);
117→  lv_anim_set_var(&a, ud->old);
118→  lv_anim_set_values(&a, 0, -h);
119→  lv_anim_set_time(&a, 170);
120→  lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_y);
121→  lv_anim_set_path_cb(&a, lv_anim_path_ease_in);
122→  lv_anim_set_user_data(&a, ud);
123→  lv_anim_set_ready_cb(&a, anim_ready_free_old);
124→  lv_anim_start(&a);
125→}
