167→void dm_clock_set(dm_clock_t *c, int32_t seconds_left)
168→{
169→  int32_t left = seconds_left < 0 ? 0 : seconds_left;
170→  int mm = (int)(left / 60);
171→  int ss = (int)(left % 60);
172→  int digits[4];
173→  int dw;
174→  int h;
175→  int i;
176→  bool animate = true;
177→  char wide_text[16];
178→
179→  if (!c || !c->box)
180→    {
181→      return;
182→    }
183→
184→  if (mm > 99)
185→    {
186→      snprintf(wide_text, sizeof(wide_text), "%d:%02d", mm, ss);
187→      lv_label_set_text(c->wide, wide_text);
188→      lv_obj_clear_flag(c->wide, LV_OBJ_FLAG_HIDDEN);
189→      lv_obj_add_flag(c->colon, LV_OBJ_FLAG_HIDDEN);
190→      for (i = 0; i < 4; i++)
191→        {
192→          lv_obj_add_flag(c->d[i].clip, LV_OBJ_FLAG_HIDDEN);
193→        }
194→      return;
195→    }
196→
197→  lv_obj_add_flag(c->wide, LV_OBJ_FLAG_HIDDEN);
198→  lv_obj_clear_flag(c->colon, LV_OBJ_FLAG_HIDDEN);
199→  for (i = 0; i < 4; i++)
200→    {
201→      lv_obj_clear_flag(c->d[i].clip, LV_OBJ_FLAG_HIDDEN);
202→    }
203→
204→  digits[0] = mm / 10;
205→  digits[1] = mm % 10;
206→  digits[2] = ss / 10;
207→  digits[3] = ss % 10;
208→
209→  dw = (lv_obj_get_width(c->box) * 2) / 10;
210→  h = lv_obj_get_height(c->box);
211→
212→  /* first paint: no roll animation */
213→  if (c->d[0].digit < 0)
214→    {
215→      animate = false;
216→    }
217→
218→  for (i = 0; i < 4; i++)
219→    {
220→      roll_digit(&c->d[i], digits[i], dw, h, g_dm_font_xl, animate);
221→    }
222→}
